/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040315-3","meetingId":"h16-c-budget","date":"2004年3月15日","dateIso":"2004-03-15","committee":"予算特別委員会","time":"午前１０時０4分～午後６時１６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を179件整理しています。","topics":[{"id":"topic-01","title":"平成１６年度品川区一般会計予算","agenda":"平成１６年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"私は、３２０ページ、生涯学習費のうち、次のページ３２１ページのＰＴＡ活動支援事業について、お尋ねをします。これは中学校のＰＴＡが主となって１８校が、なぜ協議会がつくられるのか、それに至った経緯をお教え願いたいと思いますとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"地域健全育成運営協議会、各中学校のＰＴＡに委託しているものですが、平成２年度から開始しております。それからテーマを決めて、こういうことには具体的にどう対応したらいいか、それから警察の方等を講師に招いてお話を伺ったりしているものです。","id":"exchange-001"},{"speaker":"大沢委員","kind":"意見","question":"平成２年度ということで、地域でどの程度の職責といいますか、ボランティアでされている方を具体的に網羅なくお答え願えればと思いますとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"各学校に応じて、地域の実情に応じて、その学校で情報交換が必要な方たちを個別に選定しております。基本的には、子どもたちを取り巻く団体の代表者、それから、民生委員、町会長が入るところもありますし、各校独自で行っております。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"各校独自で行っているということで、それは学校によって多少ばらつきがあるということか尋ねました。","respondent":"上川内生涯学習課長","answer":"ばらつきがあるというよりも、その学校と親御さんたちが必要だと思う方をメンバーに選んでいるです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"私たちがどうのこうのという問題ではないんですが、そこら辺のご見解が、お声かけをして話し合いをしているということでよろしゅうありますか尋ねました。","respondent":"上川内生涯学習課長","answer":"おっしゃるとおりです。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、１８校独自ということなので、平成１４年度なんですが、１８の中学校で４８回の健全育成運営協議会が開かれておりますけれども、これは横並びで、単純に４９割る１８という理解でよろしいんか尋ねました。","respondent":"上川内生涯学習課長","answer":"こちらのほうとしましては、地域の方々と、子どもたちのまちの中の状況、学校の状況等を情報交換していただくという趣旨で、春休み、夏休み、冬休みの前に３回程度をお願いしているものですが、現実に２回から３回、３回が圧倒的に多うあります。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"では、時期的なものは、春休み、夏休み前に随時開かれるという理解をさせていただいてよろしいか尋ねました。","respondent":"上川内生涯学習課長","answer":"あくまで、ＰＴＡは自主的な団体ですので、私たちのほうで３回という枠を決めたのは、休み前ですが、その学校の実態によりまして多少ずれることもあろうかと思います。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"ＰＴＡが自主的にということですけれども、せっかく地域の方に時間を割いていただいて、協議会を皆さんで活発な情報交換をしていただいているわけですけれども、それについて、行政のほうから、何か意見の集約とか、取りまとめとかというのは、１８校の横のつながりでなされているのか尋ねました。","respondent":"上川内生涯学習課長","answer":"当課のほうのＰＴＡ支援事業の一つですが、専門部研修会等、かなり研修会を行っております。その中で、情報交換等をしております。","id":"exchange-007"},{"speaker":"大沢委員","kind":"意見","question":"区のほうでその集約といいますか、横のつながりで、各協議会に出た話を吸い上げているということで理解をします。生涯学習という見地から見た場合、どのような意義を持ち合わせるものか、ご見解をお願いしたいと思いますとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"生涯学習課としては、家庭教育の支援事業というものもありますし、青少年の健全育成という課題もあります。その観点から、生涯学習課のほうで管轄しているものです。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"生涯学習という観点から、もう一つお伺いをしたいんですけれども、広くＰＴＡの方が地域の方をリストアップをして、お呼びしていると。それについて、もちろん話ができるような常識的な人数だとは思うんですが、人数のおよその目安みたいなものはあるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"特にこちらのほうからお願いしているものではございませんが、情報交換が細かくできる範囲の中で、各ＰＴＡは実施しているものです。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"現状は、話ができる範囲内ということなんですが、地域健全育成運営協議会に、生徒の参加している学校といいますか、生徒を協議会に参加させているような学校ってあるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"構成メンバーとしましては、校長先生、それから校区の小学校の校長先生、教頭先生、生活指導主任等が学校側からはメンバーとして、大体出ております。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"行政の側でも、地域健全育成運営協議会についてのご指導をお願いしたいと思いますけれども、そのような形をお考えの中に入れていただけるかどうか。はっきりは難しいですけれども、最後に方向性だけお伺いしたいと思います。","respondent":"古川教育次長","answer":"しかしながら、さまざまな協議会の運営の中では、先ほどご質問にございましたけれども、当該の学校の生徒がその場に参加することも、現実にあります。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"あらゆる方面からの構成員ということで、上辺だけの話ではなくて、より突っ込んだ話がこの協議会でされることを、またできるようにご指導していただくことをお願いいたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"３２１ページのシルバー大学、それから、３２３ページの総合体育館、２点、お聞きしたいと思います。それについて、それまでの申込み状況、それから、ここまでの申込み状況、数とか、団体であるとか、何か変化があればお知らせを願います。","respondent":"梶教育委員会事務局副参事","answer":"その中で、今までは登録だけしていて使っていない団体等がありましたけれども、そういうものは一通り精査されたのではないかと考えています。１カ月に関して１０の時間帯、特にこちらのほうは聞いてございませんので、大体今までと同じような形ではないかと考えています。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、取り立てて変化はないということで、お伺いをいたしました。そういう中で、４種類の登録団体以下障害者の団体まで、例えば、各団体がかち合った場合とか、どういう抽選方法になるのか。","respondent":"梶教育委員会事務局副参事","answer":"その場合については、４カ月前の抽選には参加できない。その場合は、先着順ということになってあります。","id":"exchange-014"},{"speaker":"若林委員","kind":"意見","question":"これが、今年に入って、２月から漏れるという事態が起こりました。そういう変化がない中で、こういう事態を把握していらっしゃるかどうか、ちょっとお知らせ願いますとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"恣意的なものは排除していまして、機械的に抽選をしているという中で、たまたま確率的にそうなったかとも思います。まだ実施してから１年余り程度なので、増えたりしているという状況もありますので、よろしくお願いします。","id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"３カ月全然当たらないというのはいかがかなと思いましたので、私もそこら辺を確認しながら、ご相談したいと思います。何のために、またどのような方のためにあるのか、お知らせを願います。","respondent":"上川内生涯学習課長","answer":"２年、３年と続きますとだんだん専門分野に入り、メンバーも少なくなってまいります。今度は趣味のうるおい塾というものを実施しておりまして、今は元気な方たちも多くなっておりますので、それを地域に生かしたいという声もあります。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"内容が、いろいろプログラム等豊富なようで、大変に好評を博していると伺っております。区のほうとして、受講者からの評価、そこら辺、どのようなお声が届いておりますか尋ねました。","respondent":"上川内生涯学習課長","answer":"皆様、必ず入学式がありまして、卒業式等あります。今まで会社人間だった男性もシルバー大学に入ることによってお友達が増えたと伺っておりますので、生き生きとした活動をなさっております。","id":"exchange-017"},{"speaker":"若林委員","kind":"意見","question":"ぜひ、このシルバー大学、今後ともさらなる充実をお願いしたいと思いますが、今、入学式と卒業式という言い方がございました。多分、卒業式は修了式のことだと思いますが、どのような枠でここに参加されるのか、お知らせ願いますとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"その中には、ＯＢの方、それからさまざまなボランティアとしてご援助いただいた方等を含めまして実施しております。ちなみに、入学式は４００名、修了式は３６０名の参加が、近年ではございました。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"今の入学式では４００名、修了式では３６０名の参加ということでございました。ここら辺の意味と、４００名の入学に対して、修了式に参加される方がなぜ４００名でないのか、これをお聞きいたします。","respondent":"上川内生涯学習課長","answer":"修了式は全部式典ではなくて、全体のパーティ等も含めたものですので、講師の方とか、リーダーの方とかも入ります。それから、入学式につきましても、これから決まっている講師の方等の数字も入りますので、イコールシルバー大学生という数字ではございません。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"修了式、修了パーティに、会費という言い方でいいのでしょうか、それを納めて参加する。ここら辺の、これからの対応をお願いしたいと思うんですが、答えるよう求めました。","respondent":"上川内生涯学習課長","answer":"会費というのはパーティの飲食代でございまして、式典には皆様出られますが、式典とパーティとは時間と会場を別にしております。パーティの中にはＯＢの方の参加もありますので、飲食のパーティですので、その実費の部分を実行委員会の中で賄っております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"その後、どういう検討をされてきているのかを、ちょっと伺いたいと思うんです。そういう点で、ぜひ、その辺の検討状況について伺いたいと思います。","respondent":"上川内生涯学習課長","answer":"スケートボードにつきましては、今現在、私どものほうに、団体とか、個人の方でやりたいという要請等はございません。スケートボードにつきましては、まだまだ危険性が伴うものでもありますし、要請が具体的にありましたら考慮していきたい。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"３カ月にわたって意見交換をしたり、子どもたちの要望がどういうものなのかとヒヤリングをしたりとか、２年前にできたということなんです。大沢委員のご質問で、そういう立場でぜひ検討していただきたいと考えていますけれども、意識についてお伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"臨海部のほうの、住宅からかなり離れて騒音の問題がないようなところで何とかならないかということで、私どものほうでも検討しております。区民公園でどうかということも検討しましたけれども、一昨年から昨年にかけて、私どもから要請をしております。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりあそこまで行くのはなかなか大変なことですから、排除しないで進めていただきたいということを強くお願いしたいと思うんです。そういう作業を、教育の立場から進めてほしいと求めましたが、その点ではいかがか尋ねました。","respondent":"古川教育次長","answer":"私ども認識していますが、管理工事課長からご説明申し上げましたが、模索しています。これは一般論になりますけれども、さまざまなニュースポーツに対する場の整備につきましては、今後とも十分に検討していきたいと考えています。","id":"exchange-023"},{"speaker":"木下委員","kind":"質問","question":"英語学習を大体何校ぐらいでやっていらっしゃいますかとお聞きしましたら、大体半分ぐらいの学校が１年生から教えていると聞いたんです。１年生から英語学習を導入する方向性が決まったのか、どうなのか、お答え願いますか尋ねました。","respondent":"中島指導課長","answer":"国際理解教育、小学校における英語学習についてのお尋ねです。プラン２１推進の中で、現在、取り入れております１年生からの英語学習を全校的に展開していきたいと考えています。","id":"exchange-024"},{"speaker":"木下委員","kind":"質問","question":"ということは、小学校全校で導入するという理解でよろしいんか尋ねました。","respondent":"中島指導課長","answer":"そのとおりです。","id":"exchange-025"},{"speaker":"木下委員","kind":"質問","question":"ちょっとお聞きしたいんですが、小学校における英語学習で、５、６年生とそれ以外の学年の子どもたちの英語学習というのは、国際理解教育のほうに当てはまるという理解でよろしいんか尋ねました。","respondent":"中島指導課長","answer":"したがいまして、実際には総合的な学習の時間の中に単元として位置づけて、コミュニケーションを中心とした英語学習をやってあります。今後、展開されていく小学校におきましても、こういったコミュニケーションを中心とした形での単元として実施していくという形から。","id":"exchange-026"},{"speaker":"木下委員","kind":"質問","question":"品川区は首都東京の玄関ですから、できるだけ早く導入していただけるように、お願いしたいと思います。もっと貿易力も増えていくわけですから、２０年後をにらんだ形で、そこら辺の考え方としてはいかがか尋ねました。","respondent":"中島指導課長","answer":"例えばインドネシアですとか、トルコですとか、そういったアジアの国々の人々を招いて交流活動をしているといったような状況もあります。今後の各学校の取り組み、英語学習を推進していく中での発展という部分で、私どもの課題ととらえさせていただければと考えています。","id":"exchange-027"},{"speaker":"木下委員","kind":"質問","question":"報われることが少なく、魅力に乏しいということで、教頭先生になりたがる方が少ないみたいなことが書いてあるんです。実際に品川区として、教頭先生になりたがっている方とか、傾向としてはどういう傾向がありますか尋ねました。","respondent":"中島指導課長","answer":"来年度は、定年退職という形でやはりお１人です。経営という部分に大きくかかわっていく職務であろうと考えていますので、また、モチベーションというものをぜひ高めていきたいと考えています。","id":"exchange-028"},{"speaker":"木下委員","kind":"意見","question":"いろいろ権限を移譲して、やりがいを高めるということでも、名称変更等を考えていらっしゃる要因だと思うんです。もし副校長になった場合に、教頭先生からどういう部分の権限が増えるのか、代表的なものをお教えいただけばと思いますとの意見を述べました。","respondent":"中島指導課長","answer":"こちらにつきましては、先ほどもちょっとご答弁させていただきましたけれども、現在、東京都のほうで具体的な事案決定につきまして協議をしている状況でございまして、またそういった情報を踏まえながら、私どもも検討をしていきたいと考えています。","id":"exchange-029"},{"speaker":"木下委員","kind":"質問","question":"教頭先生がやりがいがあるような形で、いろいろな面、ご検討をほしいと求めました。ということで、お願いいたしまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"プラン２１関連事業関係、３０９ページ、ちょっと質問をさせてほしいと求めました。その２点、お答えをほしいと求めました。","respondent":"中島指導課長、谷田部学務課長","answer":"道路上の対応が必要だというような部分、一つ一つを教育委員会で対応しているというわけではございませんけれども、子どもたちに考えさせ。各学校の取り組みという部分で、具体的になっている状況もあると聞いてあります。 小中学校、幼稚園の維持管理費経費の中の光熱水費ですけれども、学務課予算の中に計上いたしまして、学務課が直接支払いをするという仕組みになってあります。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"概算なので、大きい額、小さい額ばらばらですから何とも言えないんですけれども、平均だと１,２００万円です。今月は８０万円になりましたよ、９０万円になりましたよというのが具体的に生徒に見えれば、お考えはいかがか尋ねました。","respondent":"中島指導課長","answer":"児童生徒が自分たちで取り組んでも、また、どうにもならないような部分があります。これからも、またそういった情報収集にも努めてまいりたいと考えております。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば年間で１０万円、２０万円浮いたと、そっちの思いです。予算上とか、法的な縛りとか問題があるかもしれませんが、そこら辺のお考えを説明するよう求めました。","respondent":"谷田部学務課長","answer":"プラン２１を進めるに当たりまして、そういう省エネの取り組みも、今後の参考にさせていただきたいと思ってあります。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"プールの水１回取りかえ分が２０万円という、プールの水ですから、そういったものを使うことができないか。要するに、学校の意欲を、それだけみんなで頑張ったことによって結果が出たものを移すことができないかなというそっちなんですけれども。","respondent":"市岡企画財政課長","answer":"事業部編成枠方針をとっておりまして、学校も次の努力への新しい予算にその分を反映させることは十分可能だと考えておりますので、そういう方向で努力をしたいと考えます。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校はやっぱり一生懸命やっていらっしゃる、先生たちがやっている部分で、その辺を考えてあげていただきたいなと思います。学校ですからちょっと表現は悪いかもしれないけれども、校長先生、その辺はどうか尋ねました。","respondent":"中島指導課長","answer":"各学校の熱意、努力、そういったものに傾斜的に予算を振り分けている部分もあります。学校では，それに応じた形で、この年度末におきまして、最終的に十分な成果を出していただいていると伺っております。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"制度が始まって２年間、各学校ばらばらになっているのか、それともある程度統一しているのか。それから、２年経って、成果と今後の課題という点では、どのようにお考えか尋ねました。","respondent":"中島指導課長","answer":"現在の状況を、今後またより客観的に見ていけるような方策を考えていく、これが今後の一つの大きな課題になるだろうと思います。この制度のあり方を、来年度、見直していきたいと考えています。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"なぜこういう質問をするかというと、議会の議決をいただきまして、海外調査団に参加させていただきました。外部評価者制度を変えるということも、お話があったんで、その辺もちょっと、最後にほしいと求めました。","respondent":"中島指導課長","answer":"外部評価者制度の評価項目につきましては、それと必ずしも大きくかけ離れているものではございません。より客観性が持てるように、今後、検討してまいりたいと考えています。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"３０１ページのプラン２１関連事業の中の小中連携、時間の許す限り、お願いしたいと思います。小・中連携教育というのと、小・中一貫教育というのがあるんですが、この違いはどんなふうにとらえていかれるんか尋ねました。","respondent":"中島指導課長","answer":"この小・中連携教育ですけれども、基本的には、小・中連携教育の実践がプラン２１で推進されてきている中で、より接続を滑らかにしていこうという形で考えたのが、小・中一貫教育というような視点でとらえていただければと思ってあります。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"そうすると、今後、小・中一貫教育を進めていくという上では、予算のほうも、連携教育から一貫教育のほうに移行し、連携というところはなくなってくるという理解でよろしいんか尋ねました。","respondent":"中島指導課長","answer":"そのときに、小・中連携という部分が、小・中一貫のさまざまな特色ある小・中一貫という形に補完されていく可能性はあろうかと思います。今の段階で、そこまではっきり申し上げられなくて、申しわけございません。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"それは、もう少し具体的にどういう時期に、どういうものをしてというところ。そこら辺の対応を、どういうふうにされるのか、教えてほしいと求めました。","respondent":"中島指導課長","answer":"小・中学校別に考え方を説明したり、Ｑ＆Ａをやったりという形で、まずは管理職レベルでの理解を図っているところです。現在もやっております小中一貫校での説明の場ですとか、中Ｐ連等での説明の場でもって、一つ一つご説明をしていきたいと考えております。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、平成１８年度以降から移行していくということは、大崎地区での完全移行、開校になると思うんですが、そこと同時並行という形になるという感覚なんか尋ねました。","respondent":"中島指導課長","answer":"平成１８年度に大崎地区の小中一貫校の施設が開設されるということで、そこの時期と移行が始まる時期は、年度的には同じです。研究開発は進めておりますけれども、平成１８年度に、それなりの移行の期間を経て進めていくという状況はあります。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"一つの行事をするにしても、２０回とか、３０回とかというかなり激しい打ち合わせをされておりました。その辺、教育委員会としてはどういうふうに指導されていこうとされているのか、お聞きしたいと思います。","respondent":"中島指導課長","answer":"大崎地区のほうは、やはり１年先んじているだけに、それぞれの教員認識は非常に高まっているところです。現在、東京都教育委員会とのすり合わせ事項ということで、進めている状況にあるところです。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"親側としてこういうことをお願いしたいということも、多分要望として出てくるかと思いますので、それをぜひお願いしたいと思っています。この辺をどういうふうに、小学校に対して進めていこうとされているのか、説明を求めました。","respondent":"中島指導課長","answer":"こういった教科担任制がどこまで可能かという部分がこれからの検討になっていくわけですが、進めていきたいと考えています。先ほど申し上げましたのは、小・中連携ができるような教員の可能性も含めて、今後の大きな課題の部分かなととらえております。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、教科担任制という制度をとるのか、ＴＴという形もあろうかと思いますし、補助というのもありますので、いろいろな方法がある。先生方が１人で悩まない、そういうのをしていただきたいなと思うんですが、その辺はいかがか尋ねました。","respondent":"中島指導課長","answer":"東京都が実施しております教員加配、教員を１名増員するという制度も、個に応じた指導の重点として必要だというところから来ております。今後も、その方向を重視して考えていきたいと考えております。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"インターネット等々で公表されたわけなんですが、今年は小学校６年生ということで、これらの扱い方について。学力定着度調査の結果がどう反映されたのか、どういう方向で学力定着度調査を進めていこうとしているのか、お考えをちょっとお聞きしたいと思います。","respondent":"中島指導課長","answer":"定期的にミニテストを実施して、アンケートを実施していくとか、そういったようなさまざまな視点からの学校分析が寄せられてあります。今後、中学校におきましても、こういった態度表明のあり方を検討していきたいと考えています。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"時間がありませんので別途お聞きしますが、ホームルームの中でカルテをつくって、その子どもの指導に当たっているというところがありました。あゆみのほうも、それにあわせていろいろと考えていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"３１３ページの小中一貫校推進経費と、３０１ページのまちの人々に学ぶ授業、２９７ページの教職員研修についてお伺いしたいと思います。実施設計等委託ということで ４,０００万円が計上されておりますが、「等」とありますけれども、実施建設以外の「等」の内容を説明するよう求めました。","respondent":"鷹倉庶務課長","answer":"平成１６年度における小中一貫校の経費ですが、それから、移転等に伴う経費等が入ってあります。それから、大井地区における小中一貫校につきましては、実施設計、それから一部、仮校舎の借り上げ等が入ってあります。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"実施設計等委託のところで、委託先の内容と、また、今、「等」というのが仮校舎の賃借というお話ですけれども、そうすると、場所等もお決めになられたのか、その辺を説明するよう求めました。","respondent":"鷹倉庶務課長","answer":"平成１６年度の実施設計というのは、大井地区の部分です。検討していますけれども、仮校舎は、伊藤中学校の敷地の中でうまく回しながら運営していきたいと考えているところです。","id":"exchange-048"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、ちょっと変わりますけれども、昨年１０月１日に説明会を開かれた以降、説明会をもし持たれていれば、その回数と状況等がございましたら、説明を求めました。","respondent":"鷹倉庶務課長","answer":"大井地区におきまして、今、ご指摘のございましたように、１０月１日に説明会をさせていただきました。２月に入って、今回、説明会を持たせていただきました。","id":"exchange-049"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望としてお願いしておきたいと思います。３０１ページのまちの人々に学ぶ授業というところで、昨年度で結構ですけれども、主な実施状況を説明するよう求めました。","respondent":"中島指導課長","answer":"現在、区立の小中学校を抱えている地域の中には、さまざまな知識ですとか、技能、またノウハウを持っていらっしゃる方がたくさんいらっしゃいます。そのことで学校と地域社会とのより一層強い連携を図る、こういったところが、この授業のねらいです。","id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"どのようなお話をされるか、もし、ありましたら説明を求めました。","respondent":"中島指導課長","answer":"年間１８時間の実施、１０時間の実施というのが、予算上上げられている部分です。その準備段階で来ていただいて、具体的な職業についての話を伺うとか、こういったような状況があります。","id":"exchange-051"},{"speaker":"武内委員","kind":"質問","question":"拡大を行うとなっておりますけれども、予算のほうは、昨年と比べて減っているんでしょうか。それとも増えているんか尋ねました。","respondent":"中島指導課長","answer":"今年度と同額という形です。","id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"要望します。２９９ページに四つぐらいありますけれども、ほか８研修は結構ですけれども、大体どんな研修をされているか説明を求めました。","respondent":"中島指導課長","answer":"特にプラン２１に連動する形での経営ビジョンをどのように持つか、こういったような内容を中心に研修をしているものです。情報交換の部分と、さまざまな学校に関係する機関の方々からのレクチャー、または具体的なワークショップといったもの中心に進めているものです。","id":"exchange-053"},{"speaker":"武内委員","kind":"質問","question":"教育事情視察、これは、どういったものを視察されるのか。教育研究奨励費、この辺も内容を説明するよう求めました。","respondent":"中島指導課長","answer":"例えば、通常学級とより連携をしていくというような一つの手だても持ちながら研究に取り組むとかというような手法でやっているものです。この視察が年に４回ほどございまして、そういった中で、先進地区の視察等を含めて実施しているものです。","id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"これも事務事業評価のほうに、研修の方法や内容を見直しをすると載っておりますけれども、これは見直しをされた予算なのか、それともこれから見直しを考えられるのか、その辺をあわせて説明を求めました。","respondent":"中島指導課長","answer":"現在、もう既に見直しをしている部分があります。来年度も、それに伴いまして、その内容につきましては見直しを図っていきたいと考えているものです。","id":"exchange-055"},{"speaker":"武内委員","kind":"意見","question":"やはり、子どもたちの成長というのは、学校の先生の成長が伴わなければ成し得ないものかなと考えていますので、いろいろご苦労は多いとは思いますけれども、ぜひ研修をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"石田委員","kind":"確認","question":"これは、前回から何度もこういう場面で話が出ておりまして、確認だけします。必ずそういうところをつくってほしいんだという話があって、その考え方でいいのかどうかだけ、答弁をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"石田委員","kind":"質問","question":"私も、一般質問で食育について質問をいたしました。そこら辺の点もあわせて、わかったら説明を求めました。","respondent":"谷田部学務課長","answer":"中学校につきましては、たしか昭和４１年に１校で始まりまして、昭和４６年までに中学校全校で給食が実施されたという経過になってあります。その場合、滞納の発生の率ですけれども、私どものつかんでいる状態では、小中学校合計して０.２％ぐらいという数字があります。","id":"exchange-058"},{"speaker":"石田委員","kind":"質問","question":"そういうメニューも増やすから、しっかり食については家庭でも教えてくださいと、そういう意味合いの中でやってきている。一つの給食のあり方だと、私は思うんですが、そこら辺の考え方を説明するよう求めました。","respondent":"谷田部学務課長","answer":"４点目が、学級活動、または保健体育の時間等々で行われているわけです。そういう意味では、統一の献立で調理された食事を取りながら、その中でさまざまな教育活動を行っているです。","id":"exchange-059"},{"speaker":"石田委員","kind":"質問","question":"支給だ、海外でもそう訳されているものについて、給食ということの今の意味合いをどうとらえているか。その言葉だけのとらえ方を説明するよう求めました。","respondent":"谷田部学務課長","answer":"長く定着している言葉だというふうに、私は理解しています。私どもも、そういう中で愛称も含めて検討するということも、方向性等はあるなと思ってあります。","id":"exchange-060"},{"speaker":"石田委員","kind":"質問・要望","question":"仲間意識を養うことでもできれば、昼食という意味もある、それから食に対して丁寧に言葉を扱うんだよという意味合いもある。例えばそういう意味合いを広くアンケートを取るとか、そういう考えがもしありましたら、ぜひ教えていただきたい。","respondent":"鷹倉庶務課長","answer":"たしか、品川区には品川めしというものもかつてあったと聞いてあります。今、委員のご提案の品川のごはん、これも一つのネーミングだと思いますので、今後、十分検討してまいりたいと思ってあります。","id":"exchange-061"},{"speaker":"石田委員","kind":"質問・要望","question":"考え方だけ、ちょっと教えてほしいと求めました。小中一貫校も各地域に１校ずつなんていうソフト面のことは、そういうことを言っていくんだというお考えだけ、ちょっと説明を求めました。","respondent":"鷹倉庶務課長","answer":"基本的な考え方は、私ども、品川区の総合実施計画の中で、今回も新たに改定したものをお出ししていく予定です。この辺を見据えながら、実施計画の中できちっと位置づけながら、させていただきたいと考えているところです。","id":"exchange-062"},{"speaker":"石田委員","kind":"質問・要望","question":"やめようかと思ったんですけれども、具体的にソフトの部分はある程度示してほしいと求めましたので、その具体的な考え方だけ、最後に。","respondent":"鷹倉庶務課長","answer":"具体的な考え方ですけれども、小中一貫の問題、地区をいろいろ考えていかなきゃいけないという問題があります。小中一貫校の展開をにらみながら、学校改築が出てくるのかなと、この辺が基本的に考えられることかと考えております。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、３０１ページの小・中一貫教育と、同じページのすまいるスクールに関連して伺いたいと思います。今年の２月５日のプレス発表の中で、だれが、どこで最終決定を行ったのか尋ねました。","respondent":"鷹倉庶務課長","answer":"何月何日までは、ちょっと出ませんけれども、基本的に、私ども教育委員会で政策予算の審議をしてまいります。これが１１月から１２月にかけてやりまして、あるいは、三役査定の中で決まっていくということかと思います。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"今直ちに調べていただきたいのと、これまでも決定してから発表すると言っているわけですから、もう一度答えるよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会の決定ですと、１１月２７日に審議をされたということでよろしかったんでしょうか。７月１０日に、７月１０日以前に教育委員会で何らかの話が行われて、そうではないんか尋ねました。","respondent":"富田教育改革担当課長","answer":"具体的な構造改革特区の研究開発学校として大井地区の小学校１校、中学校１校を指定して研究開発学校としていくという、それが具体的な内容です。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたいのは、７月１０日の時点で、品川区長としては、全区展開をするということを政府に上げているわけですよね、申請をしているわけですよ。ということは、品川区の意志として、小・中一貫教育の全区展開をするんだと決めたのがいつかと伺っているんです。","respondent":"富田教育改革担当課長","answer":"先ほど申し上げましたように、特区申請の中で、全区展開をすると書いているわけではございませんで、できるところでは、こういった小・中一貫教育を他の小・中学校でも実施していきたいという考え方を述べたところまでです。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"７月１０日の時点で、区民に品川区の小・中一貫教育を全区展開するという説明をしたのは、一体いつでしょうか。説明を求めました。","respondent":"富田教育改革担当課長","answer":"これで３度目になりますけれども、特区申請の中では、すべての区立小中学校で小・中一貫教育を実施していくというふうに述べたものではございません。小・中一貫教育を、施設一体型の小中一貫校以外の学校でも実施していく旨を書いているものです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"なぜ追及するかというと、そもそも小・中一貫教育が区民に明らかになったのは１月１８日の朝日新聞、議事録でも見ました。その辺について、一言伺いたいと思います。","respondent":"古川教育次長","answer":"特区のほうもそういうことを要求してまいりますし、私どもも、品川区の教育委員会がとらえていくかという一つの考え方を示したわけです。２月５日のプレス発表、それぞれの段階におけるものの考え方、私は考えてあります。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"実施される教育内容は、資料もおろか報告もされてないんで、なぜ、報告せずに実施するのか。それと、４月から実施する初年度の教育課程の内容とは一体何なんでしょうか、説明してほしいと求めました。","respondent":"中島指導課長","answer":"４月から、大井地区の小中一貫校で実施します教育課程ですけれども、教育課程の実施につきましては。具体的には、午前中にも出ましたけれども、英語学習を１年から実施をしていく。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問だけ、次に進めさせてほしいと求めました。改めて、戦前の教育は何が問題で、一体今の教育基本法はどんな人間像をつくろうとしているのか、説明してほしいと求めました。","respondent":"若月教育長","answer":"これをトップダウンと言われちゃったら、何もできないわけですね。ご説明をするということでありまして、トップダウンだから、ここだけははっきりさせておきたいと思います。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"５分なので、次のことを質問したいと思います。この資料というのは、どこの所管の責任で、だれが提出したものなのか、説明してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたかったのは、この資料を提出した所管の責任者はだれかということです。もう一度だけ説明を求めました。","respondent":"富田教育改革担当課長","answer":"小中一貫校のコンセプトにつきましては、主に教育委員会事務局指導課のほうで、たたき台としてはつくってきているものです。小中一貫校開設に向けては、教育委員会で決定をとっているものです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"確認","question":"そこだけ１点、確認させてください。区が掲げる考え方というのは、そういうものなのかどうか、確認したいと求めました。","respondent":"中島指導課長","answer":"平成１４年のその時期以降にも、カリキュラム検討委員会の中でさまざまな検討をする中で、少しずつそれを改良してきている状況があります。願わくば、最新の資料等に目を通していただきまして、私どもの考え方をご理解いただければなと考えています。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"７月１０日の特区申請書の中で、「５年生以上は、ステップアップ学習を設ける」と書かれているんですね。一部の子どもたちだけに特別な授業を行うエリート教育じゃないかと思うので、ぜひ、教育長のご見解を教えてほしいと求めました。","respondent":"中島指導課長","answer":"そして自分が取り組みたい内容、そして自分が課題として認識している内容、これがステップアップ学習のねらいであります。これからの品川区の子どもたちの９年間を一体化した中で、基礎学力の定着と個性の伸長を図る夢と、そして希望を育む学校であると確信しています。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"１分なんで、すまいるスクールについて一言だけ聞きたかったので、話題を変えさせてほしいと求めました。この辺について、区長はどのような趣旨で言ったのか、説明してほしいと求めました。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは、さまざまな役割を持ってあります。４月からは放課後児童健全育成事業も担っていく、さまざまな役割を持って、これからさらに進んでまいりたいと考えております。","id":"exchange-076"},{"speaker":"三村委員","kind":"質問","question":"お伺いをしたいんですけれども、なぜ公募が行われず、ＮＰＯへの委託ありきで進められてきたのかお伺いいたします。第３者機関的な選定委員会が必要かと思いますけれども、選定委員会設置について、ご所見をお伺いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"その中で、地方自治法の改正がされますので、この制度を取らざるを得ないということで、途中で変更したものです。専門性を生かしたＮＰＯを使った形で検討してまいりましたので、そこから新たに公募をして、特に公募等はしておりません。","id":"exchange-077"},{"speaker":"三村委員","kind":"質問","question":"選定委員のメンバーは、どのような方だったのかお聞きしたいと思います。本来であれば、手続条例制定が必要かと思いますけれども、それについてのご意見をほしいと求めました。","respondent":"市岡企画財政課長","answer":"それから、公募が前提とはなっておりません。選定の方法については、法律は決めておりませんので、公平な選定を行うための選定委員会を設置したです。","id":"exchange-078"},{"speaker":"三村委員","kind":"質問","question":"ぜひ、透明性のある選定をよろしくお願いいたしたいと思います。変更になったという形でよろしいのか、ちょっとその辺よくわからないので、お聞きしたいんですけれども。","respondent":"中島指導課長","answer":"行事のみの連携とか、いろいろな要素が入ってまいりますので、一貫教育という部分とは大きく変わっているところと考えております。基本的には、一貫校以外はすべて学校が分離しておりますので、その中で、一貫教育を推進していくという方向です。","id":"exchange-079"},{"speaker":"三村委員","kind":"質問","question":"特区申請を見る限りにおいては、一体型と分離型を合わせて５校程度となっていたんですけれども、分離型を広げて全区展開ということなんですか。じゃなくて、分離型は全く念頭に置かなくなったという理解でよろしいんか尋ねました。","respondent":"中島指導課長","answer":"分離している学校で一貫教育を推進するですので、いわば、分離型が全区で実施をするというふうにとらえていただければと考えています。","id":"exchange-080"},{"speaker":"三村委員","kind":"質問・要望","question":"質問をされていたので、同じ質問でかぶってしまいますので、お聞きをしていきたいと思うんです。こういうような形で展開をしていく、ぜひきちんと長期展望を示していただきたいと思うんですけれども、お考えのほうをお聞きしたいと思います。","respondent":"中島指導課長","answer":"先ほどもちょっと申し上げましたけれども、この４月からすぐにそれの実施を考えているわけではございません。平成１８年度からの移行というスケジューリングを考えておりますので、これからそういったことの説明に尽くしていきたいと考えています。","id":"exchange-081"},{"speaker":"三村委員","kind":"質問","question":"５校に１校、五つの行政区に１校、荏原地区だと行政区一つの中に二つの小学校のブロックがあるんです。この状態ですと、小学校のブロック制については、荏原地区の小中一貫校に関連してどういうふうにお考えなのかお聞きしたいんです。","respondent":"谷田部学務課長","answer":"学校選択は５年になりますので、４ブロックが定着しているというのと、それから行政の地区とはまた別の話です。私ども学校選択制は、この４ブロックを基本として、今後も学校選択を進めていきたいと考えています。","id":"exchange-082"},{"speaker":"三村委員","kind":"質問","question":"そこに１校だけ小中一貫校をつくると、小中一貫校は選べない学校のブロックが出てくるかと思うんです。２校つくるのか、ブロックをなくすのかという判断をされるんじゃないのかなと思ったんですけれども、その辺もう１回、お聞きしたいんです。","respondent":"古川教育次長","answer":"地域バランスをとらえたときに、今申し上げました行政区域の中に１校では足りないという場合は、当然２校ということも出てこようかと思ってあります。この間、お話し申し上げておりますし、それは今も変わってございません。","id":"exchange-083"},{"speaker":"三村委員","kind":"質問","question":"ちょっと、どんどん変わっていってしまうので、ほんとうにどういうふうに考えていいのかわからないことが多いんです。逆にハードルが高くなるんじゃないかという心配もされるんですけれども、教育委員会のお考えのほうは、どういうふうに把握されているか尋ねました。","respondent":"中島指導課長","answer":"３、２という形で実施していこうと、これは全区展開のコンセプトでもあります。６年生までしかありませんから、その後の７年生を見越した形での３ということになりますけれども、それを実施していく。","id":"exchange-084"},{"speaker":"三村委員","kind":"質問","question":"もう１点、校庭の使用が制限されて、使いにくくなるんじゃないかというような保護者の声も聞いているんです。その辺の整合性とか、調整をどういうふうに考えていらっしゃるのか、お聞きしたいんです。","respondent":"中島指導課長","answer":"例えば、教室と教室の間のオープンスペースも１教室分の幅があるぐらいの非常に大きなスペースを取ってあります。居場所の確保、これが一番のねらいですので、それを実現していきたいと考えています。","id":"exchange-085"},{"speaker":"三村委員","kind":"質問・要望","question":"ちょっともう１点だけ、３０１ページのプラン２１に関係して、時間があるのでちょっとお聞きしたいんです。その中の主な意見、３点とか、５点とか、どういった意見が出されているのかお聞きしたいんですけれども。","respondent":"中島指導課長","answer":"年度切り換えで予算上の措置もございまして、新年度に入ってからの処理という形になる見込みです。冊子にもしていければなと、こんなふうにも考えてありますので、そこでまたいろいろとご意見を頂戴できればと思ってあります。","id":"exchange-086"},{"speaker":"三村委員","kind":"質問・要望","question":"いろいろな方からご意見が多数集まったということなので、ぜひそういった意見に真摯に耳を傾けていただいて、今後の教育委員会の進め方についても反映をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"原委員","kind":"質問","question":"５８校中の８校ということで行われているわけですけれども、あるいは対策があると思うんで、その辺についてお伺いをします。あるいは、風がよく通って寒いと、そんな話まで聞こえてくるんですが、その辺は認識をされていますか尋ねました。","respondent":"鷹倉庶務課長","answer":"部屋の隅で、壁との関係でわずか１mmとか２mmあいているわけですけれども、そこについてはすぐにふさぐということを考えてあります。","id":"exchange-088"},{"speaker":"原委員","kind":"質問","question":"確かにプレハブの仮校舎だということですから、しかしその中においても、これから幾つかの学校を改築していくわけですよ。これから出てくる仮校舎についても、しっかり検証していかなきゃいけないと思うので、その辺のお考えを説明するよう求めました。","respondent":"鷹倉庶務課長","answer":"これから、いろいろ改築していく中で、仮校舎不可避の問題です。今回、ご指摘いただいている点も踏まえながら、万全な態勢をとっていきたいと考えています。","id":"exchange-089"},{"speaker":"原委員","kind":"質問","question":"次に、ソフト面についてお伺いします。そういうところからくるストレス、ストレスからいろいろな問題も波及してくるんではないかと思うんですが、その辺のところのお考えはどうか尋ねました。","respondent":"中島指導課長","answer":"教育委員会と学校が一体となりまして、教育課程に合わせる形で、そこが賄えるようにフォローしてまいりたいと考えています。中学校に入れておりますスクールカウンセラー、その体制をつくるというような方向性を重視していきたいと、こんなふうに考えてあります。","id":"exchange-090"},{"speaker":"原委員","kind":"質問・要望","question":"の授業のおくれをどういうふうにしたらいいのかとか、いろいろ出てくると思うので、十分にお考えをいただきたいと要望しておきます。あるいは、全体の工事の計画を考えながら予定を組んでいくとか、その辺はいかがでございましょう。","respondent":"鷹倉庶務課長","answer":"ただ、そこの学校の敷地条件、近隣の住宅の条件だとかいろいろございまして、その中で、最終的に選択されていくことになります。ただ、今お話のあった点が重要な点だということは認識しておりまして、今後もそのようにしていきたいと思ってあります。","id":"exchange-091"},{"speaker":"原委員","kind":"質問・要望","question":"ぜひ、言ったところの部分も、かなり隣接した住居もありますので、お考えをほしいと求めました。そしてそのご父兄もいるわけなので、その辺の対策については、いかがでございましょう。","respondent":"中島指導課長","answer":"小学校であれば、その流れを、新しい校舎で実現される教育の質の部分をお話ししてご理解をいただくように努めていくことが大切かなと考えています。","id":"exchange-092"},{"speaker":"原委員","kind":"質問・要望","question":"その学校を選ぶ、来ていただく、来てくれるような形をとっていただきたいなと思います。そういったところの交渉について、そういった団体にはどういう配慮をされていくのか、お伺いをさせてほしいと求めました。","respondent":"古川教育次長","answer":"学校は、小中５８校あります。スポーツの場でもありますので、そういった面におきましても、周辺の学校をお使いいただくような調整を図っていきたいと考えています。","id":"exchange-093"},{"speaker":"山村委員","kind":"質問","question":"３０１ページの国際理解教育および、時間がありましたら３０３ページ、和楽器による音楽教育について質問したいと思います。会計を閉めてから給食費が納入された場合の会計処理はどうなされているのかということをお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"金銭債権の時効はたしか２年だと聞いてありますので、卒業した後も、粘り強く納めていただくような働きかけは、各学校とも取り組んです。繰り越すお金につきましては、極力少なくするということで、翌年度のほうに回すという処理をしています。","id":"exchange-094"},{"speaker":"山村委員","kind":"質問","question":"次に３０５ページのインターネット活用教育推進事業について、ご質問したいんですが、私がかわりに聞こうかなと考えています。","respondent":"中島指導課長","answer":"指導できる教員になりますと、４３.８％という形です。ちなみに、国の調査結果、そして都の調査結果との比較ができるわけですけれども、大方の部分で、それを上回っているという状況が、本区にはあります。","id":"exchange-095"},{"speaker":"山村委員","kind":"質問","question":"ただいまお伺いした、中学校ではさらに悪くて４３.８％ということなんですが、すべての分野で扱えるとは思うんですよ。そういう意味では、このままで放っておくわけにもいかないと思うんですが、どのような指導をなされているのか教えてほしいと求めました。","respondent":"中島指導課長","answer":"すべての学校にコンピュータ室を設置させていただいておりまして、夏に６日間集中研修ということで、午後の研修会を実施しています。この中に、多くの教員の参加を得てありますので、そういったところで底上げを図っているという状況です。","id":"exchange-096"},{"speaker":"山村委員","kind":"質問・要望","question":"そういう意味では、もっと徹底すべきだと思うんです。もっと徹底していただきたいという思いがありまして、今後、どのように徹底していくのかというのを聞かせてほしいと求めました。","respondent":"中島指導課長","answer":"パソコンを活用をしていく、こういったような環境を整備していきながら、教員のコンピュータに対する意識を変えていきたいと考えています。","id":"exchange-097"},{"speaker":"山村委員","kind":"質問","question":"インターネットを使った授業をやるということは決まっているわけですから、逆に言えば、すごく問題だと思うんです。このことについて、教育委員会のほうではどのようにお考えなのか、教えてほしいと求めました。","respondent":"古川教育次長","answer":"確かに数字的には向上してきてありますけれども、まだまだそういった部分においての教員の中に十分でない部分が、確かにあろうかと思ってあります。","id":"exchange-098"},{"speaker":"山村委員","kind":"質問・要望","question":"教育次長の心強いお言葉で、期待が持てる次第ですので、次の質問にいかせてほしいと求めました。３０１ページの国際理解教育、プラン２１、教えてほしいと求めました。","respondent":"中島指導課長","answer":"実際に本区におきまして実施されている交流といたしましては、こちらの方々を招きまして、特に文化交流という形で進めてあります。その方々を招いて、お互いに絵をかきながらコミュニケーションを図ったりとか、そういったような交流活動をしているような状況もあります。","id":"exchange-099"},{"speaker":"山村委員","kind":"意見","question":"そういう意味で、今後もっとインターナショナルスクールは利用されるべきだと思います。品川区にも何校かあると思いますので、そこら辺、何か計画されていたり、考えられていることがありましたら、ご説明してほしいと求めました。","respondent":"中島指導課長","answer":"先ほど、ちょっとお話し申し上げた第三日野小学校では、インターナショナルスクールとの交流も実施していると聞いてあります。現在のところ考えてございませんけれども、具体的な指導の内容を、こちらのほうで助言できるような場面をつくってまいりたいと考えています。","id":"exchange-100"},{"speaker":"山村委員","kind":"質問","question":"第三日野小学校でやられているということはわかっているんですが、具体的にどのようなことをやられているんか尋ねました。","respondent":"中島指導課長","answer":"第三日野小学校の児童、またインターナショナルスクールの生徒、これの相互訪問というような交流をやっていると聞いてあります。","id":"exchange-101"},{"speaker":"山村委員","kind":"質問","question":"相互訪問ということだと、ちょっといまいちよくわからないんですけれども、あまり英語の授業とは関係なくということでしょうか、例えば中学校では。","respondent":"中島指導課長","answer":"国際理解教育の中の英語学習としての取り組みではなくて、それともう一つ、国際交流活動の部分としての取り組みになります。交流をしながらコミュニケーションし合うといったような形の取り組みですので、若干低くなってくる部分だろうと考えています。","id":"exchange-102"},{"speaker":"山村委員","kind":"質問","question":"英語学習、教育における活用というものは、何かやられているのか、考えているのか教えてほしいと求めました。","respondent":"中島指導課長","answer":"本区の英語学習におきましては、これから、１年生からすべての小学校で実施していきたいという、一貫教育の全区展開とも重ね合わせられるところです。","id":"exchange-103"},{"speaker":"山村委員","kind":"質問","question":"あまり今の説明だとよくわからないんですが、インターナショナルスクールとか、大使館、外国の施設を利用したことで、何か考えられている案があるんでしたら、説明を求めました。","respondent":"中島指導課長","answer":"英語学習の中で、私どもが作成しているカリキュラムの中には、そういった体験的な部分も織り込まれてはありますけれども、それを教育委員会として特別固定化した形で学校に実施をさせるというような状況は、現在のところ考えてございません。","id":"exchange-104"},{"speaker":"山村委員","kind":"質問","question":"そういう意味では、インターナショナルスクールとか、利用価値があると思うんです。小学校で今後６年間英語学習をするという上で、そこら辺、何を基本をした英語学習をされるつもりなのか教えてほしいと求めました。","respondent":"中島指導課長","answer":"小学校から文法を教えるというような予定は全くございません。異文化理解の部分ですとか、交流活動の部分で、総合的に子どもたちが英語に接する機会を増やしていくというような方向は考えてあります。","id":"exchange-105"},{"speaker":"山村委員","kind":"質問","question":"そういう意味で、インターナショナルスクールでしたら小学生もいらっしゃるわけですから、英語の学習にもなると思います。小さい子どもに英語を教えるエキスパートですから、どう考えても、いろいろと取り入れていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"嶋委員","kind":"質問・要望","question":"午前中にありましたけれども、私のほうからは、環境体験学習ということでお話を伺わせていただきたいと考えています。環境体験学習について、ちょっとお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"嶋委員","kind":"質問","question":"すみません、言葉が足りなくて申しわけありません。昨年１０月に施行されました環境保全活動・環境教育推進法ということで、いよいよ昨年１０月にスタートして、ちょっとお聞きをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"嶋委員","kind":"質問","question":"実はどうして成るのか、どうやって木を育てていくのか、カブト虫が生きています。その方たちが、まちの人々に学ぶ授業の一貫としてやっていけないかどうかとても気になっておりますので、お聞きいたします。","respondent":"中島指導課長","answer":"例えば、そういったようなテーマを持ちながら、地域に密着した形での環境体験を進めているというような状況もあります。私ども教育委員会のほうで支援をして、その辺につきましては、何ができるのかというところをまずは明確にしていければなと考えています。","id":"exchange-109"},{"speaker":"嶋委員","kind":"質問・要望","question":"昨年はやはりそこで、１,５００匹の蛍を、学校の教室に蚊帳を張りまして子どもたちに直に蛍に触ってもらったと。一人でも多くの子どもたちに、または大人たちに感動を与えるのではないかと思ってお聞きをいたしましたので、ご答弁ほしいと求めました。","respondent":"中島指導課長","answer":"失礼いたしました。今のようなすばらしい取り組みについて、そういった体験を、少しでも多くの子どもたちができるような体制づくりを進めたいと思います。","id":"exchange-110"},{"speaker":"嶋委員","kind":"質問・要望","question":"二つ目に、３２３ページの学校施設開放について。どのような決まりをされているのか、お聞かせほしいと求めました。","respondent":"上川内生涯学習課長","answer":"迷惑になるような行為はやめてくださいということとともに、車でのご来場は、原則は禁止いたしますということが書いてあります。事前に校長先生なり、学校のほうと協議をして、車をとめる場所等を決めて利用してくださいというお願いをしているところです。","id":"exchange-111"},{"speaker":"嶋委員","kind":"確認","question":"では、学校の側の校長先生との取り決めの中にあるということで、確認をしてよろしいでしょうか。これは、品川区内で何園ぐらい実施されているのかお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"食の教育を就学前の段階で行ってありますけれども、給食の体験をしているというのは、ちょっと私も初めて聞いたところです。小学校を訪問して、そこで交流を行っているという話は聞いてありますけれども、給食のことについては、ちょっと存じ上げておりません。","id":"exchange-112"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうに要望的なものが来ておりまして、月１回給食があります、親御さんから喜ばれている。月１回でなくて増やしてほしいとか、そういうご要望でございましたので、ちょっとお聞かせをいただいたものです。","respondent":"谷田部学務課長","answer":"その給食の話は、私どものほうでは、ちょっと耳に届いてございません。基本的には、学校給食はそこの児童生徒のために提供するものですので、幼稚園は弁当を持参するのが基本になってあります。","id":"exchange-113"},{"speaker":"嶋委員","kind":"質問・要望","question":"わかりました。プラン２１の小・中一貫教育の中で一つだけ、平成１８年開校ということですので、もしお考えがあればお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"ほかの学校でもすべて標準服を着用していますので、標準服の着用という部分は考えてあります。これが、７年生からになるのか、５年生からになるのか、この辺はまた、協議してまいりたいと考えています。","id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"７款の教育費、１項教育総務費、３目教育指導費、３０３ページに当たる人権尊重教育推進費、この関連で。これは、どのような形で取り入れられてきたのか、ちょっとお聞きしたいと思います。","respondent":"中島指導課長","answer":"こういったような区の方針の中に、学校におきましても、男女平等教育を推進していくことが必要であるという方向性があります。必ず男児が先というような形を、これについての今後の方向性がいろいろな部分で論じられてきている状況があると、こんなように考えてあります。","id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"学校にすべて混合名簿にしなくちゃいけないという指令か何か来ているんでしょうか。その点、なぜ、男女混合名簿にこだわるのかということについて、もう少し詳しくお話しほしいと求めました。","respondent":"中島指導課長","answer":"おまえは男なのに、そういう子どもたちの活動といったようなものが、やはり基本的に見直されていかなくてはならないという部分です。子どもたちの認識、もっとオープンに考えていくようなきっかけにできるんではないかと、こんなふうに考えてあります。","id":"exchange-116"},{"speaker":"松澤委員","kind":"質問","question":"そのような形になっていくわけですから、それに対して、実際にその大もとが間違えているんじゃないかという発信はできないんでしょうか。その辺はいかがか尋ねました。","respondent":"中島指導課長","answer":"偏見といったようなものを受けることなく育っていく、またそういう場を実現する、それが教育委員会の務めであると考えています。名簿につきましても実施していき、その中身をどのように充実していくか、ここの部分であると考えています。","id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"職業体験というんでしょうか、職場体験というんでしょうか、中学生ですか。いつごろから始まったのかということと、全校でやっているのかどうか、それについてお伺いしたいと思います。","respondent":"中島指導課長","answer":"職場体験、または職場訪問という活動ですが、基本的には、中学校のほうで多く実施をしていただいております。平成１５年度は９校で実施、２年生を中心に実施していただいておりまして、１３校での実施というような状況です。","id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"職場体験というもの、私の知り合いの家がコンビニをやっているものですから、結構いろいろ中学校の方が職場体験に見えるんです。やはり学校ですから、それぞれ学校の温度差が違うんですけれども、すばらしいところはすばらしいというんです。","respondent":"中島指導課長","answer":"いろいろ学校で実施されておりますけれども、自分の進路を、子どもたちの大きな転機にもなっている状況があります。一貫教育の中で考えております市民科の中でも、そちらのほうで、また全区的に展開できるように考えてまいりたいと考えています。","id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問","question":"３２９ページ、図書館の窓口業務のこと、あと２９９ページ、人権尊重教育について、お伺いをいたします。特に維持運営費というところに載っていると思うんですが、この載せ方が非常にわかりにくいと思うんですが、どこに載っているか説明を求めました。","respondent":"市岡企画財政課長","answer":"非常勤の人件費につきましては事業費として見るという関係がありますので、維持運営費のところに載せている。これを逆に、一般的な人件費として扱いますと、人件費を含めた予算全体がわからなくなるということで、このような扱いをしています。","id":"exchange-120"},{"speaker":"飯沼委員","kind":"質問","question":"多分、委託なので、全体の金額の下の項目では全館清掃等とか、こういうところに入っているんでしょうか。その辺が、どうしてこんなにわかりにくいのか、まず率直な疑問なんですが。","respondent":"古里品川図書館長","answer":"例年、この項目で挙げてございまして、その名称をそのまま使ったものです。金額については、委員がご発言なさった金額です。","id":"exchange-121"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと大変わかりにくいので、ぜひこういうのはわかりやすい表示をお願いしたい、これは要望です。どこでも論議がなかったんですが、なぜ区はこの大切な窓口業務を委託にするのかというところと、区民への影響をぜひ説明を求めました。","respondent":"古里品川図書館長","answer":"効率的な運営という検討をしてございまして、窓口での対応が非常によくなったという評価が、どこの区でもあります。さまざまな検討をしたところ、今回、踏み切った次第です。","id":"exchange-122"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点、委託の単価を知りたいので、ちょっと調べておいていただきたいんです。もう１点は、委託によって正規の職員と、委託業者の職員との関係がどう変わるのか、指示、命令系統、指導のところを説明するよう求めました。","respondent":"古里品川図書館長","answer":"ゆたか図書館につきましては、６名を正規職員、五反田図書館、大崎図書館につきましては、５名の正規職員と１名の再任用嘱託員を配置をする予定です。","id":"exchange-123"},{"speaker":"飯沼委員","kind":"意見","question":"現状の正規、非常勤、嘱託非常勤の数と、今後変わって委託をするときの数を対比をして知りたいんですとの意見を述べました。","respondent":"古里品川図書館長","answer":"荏原図書館ですが、現在、正規職員１０名、それから、嘱託員２名、非常勤職員が４名の配置です。リクエストに対する処理業務、そして、資料整理等が委託をする内容です。","id":"exchange-124"},{"speaker":"飯沼委員","kind":"質問","question":"この重要な部門を委託に出してしまうのは、一体、この辺はどうとらえていらっしゃるのかなと思うのが１点。先ほど、サービスがよいという他区の評判ということでしたが、あちこちで委託によって問題点が出ているんですが、その辺の認識はあるのか尋ねました。","respondent":"古里品川図書館長","answer":"それから、問題点がさまざまあるですが、２３区、先行区で実施をしている例を見まして、いろいろな問題点というのはほとんどないと考えています。その後、業者のほうがむしろこれを反面教師といたしまして、徹底したプライバシー保護という社員教育をしています。","id":"exchange-125"},{"speaker":"飯沼委員","kind":"質問","question":"ペナルティとして業者が１年回指名を辞退したといった問題とか、本の返却については、すごく細かいルールがある。子どもが２回連続で痴漢におそわれたという話とか、この辺も含めて、問題意識をお伺いしたいと思います。","respondent":"古里品川図書館長","answer":"職員として当然の責務ですから、そういう認識のもとに、民間委託後の職員の業務の範囲についても指示しています。そして快適な環境づくりをすることは、現在も、これからも全く変わらないものだと思ってあります。","id":"exchange-126"},{"speaker":"飯沼委員","kind":"提案","question":"よその区の方からもお伺いをしましたけれども、資料が紛失をしてしまう、再び探すのが大変困難だと。利用者の懇談会を、形だけじゃなく実質のあるものにしていくことを提案したいんですが、いかがか尋ねました。","respondent":"古里品川図書館長","answer":"２１世紀の区民の生涯学習活動を支える上で、さまざまな分野でいろいろな検討をした結果、その中で判断をした内容です。図書館協議会の設置、あるいは利用者懇談会の設置につきましても、今後の検討の中で進めてまいりたいと考えていますので。","id":"exchange-127"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私がちょっと伺ったところによると、企業は、パートの賃金と同じぐらいの比率でもうけを上乗せしている。こういった面では、パートの賃金の２倍が委託料、単価になっていると聞いたんですが、その辺はどうなんか尋ねました。","respondent":"古里品川図書館長","answer":"単純な比較はできないものだと思います。委託の経費について検討をしまして、企業の努力も十分になされた適正な内容で、契約ができているものと考えています。","id":"exchange-128"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２,９６５万円を、非常勤の年収１４６万円で割り返したら、非常勤２０人分の予算だという数字が出たんです。委託の仕事の内容からすると、決して安くはないという面では、非常勤の制度を活用してやっていきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"大西委員","kind":"質問","question":"プラン２１関連事業ならびに、３０５ページ、２９９ページの指導資料作成委員会についてお尋ねします。学校が今うたっている内容と、現実にやっている内容、これがどのぐらいの整合性があるかという点は、把握されていますか尋ねました。","respondent":"中島指導課長","answer":"習熟度別学習ですけれども、通常の学級担任、教科指導の担当、それと１人ではなくて幾つかの教員がチームを組んで指導をするという状況があります。","id":"exchange-130"},{"speaker":"大西委員","kind":"質問・要望","question":"教えている先生が１人いて、それもボランティアですから、ほかの子どもたちが少し放っておかれているということがあったりする。何であれ外に求めて、そういう形で子どもたちの習熟度を高めていく努力、それに対する行政としてのバックアップというのはどんなものか尋ねました。","respondent":"中島指導課長","answer":"算数、やはりここの部分である程度習熟度に分けて実施をしたほうがより効果的な指導ができるというような流れで展開していくという状況があります。","id":"exchange-131"},{"speaker":"大西委員","kind":"質問・要望","question":"に、行政としてできる得る限りの力を注いでいただきたいなと、これは要望しておきたいと思います。ちょっとこれはお尋ねなんですが、教育委員会として、全校的に何らかの指導というのはありますか。","respondent":"中島指導課長","answer":"１年間取り組んできた状況を、各学校から、私どもは報告を受ける形になっております。この子どもたちの学力の状況について、情意面からの学びについて各学校が把握し、それを私どもに報告をしてきているという状況があります。","id":"exchange-132"},{"speaker":"大西委員","kind":"質問・要望","question":"私はこれが、今、教育者に求められているもので、子どもたちも、そういうことをできる先生たちを求めていると思うんです。褒めて励ませばとか、こういう共通の点を、何らかの形で求めているというものはありますか。","respondent":"中島指導課長","answer":"習熟度別学習を進めているある学校におきましては、とても楽しいというようなデータが７０％を超えて出てきているというような結果もあります。それからもう一つには、それぞれの学校の教員が、自分の専門の教科ごとに、月一度集まって研修会を実施する状況があります。","id":"exchange-133"},{"speaker":"大西委員","kind":"質問・要望","question":"すごく特化して、ほんとうに魅力のある学校づくりというんですか、選択のしがいのある学校づくり。だから、今、品川区が非常におやつの問題に関してデリケートになっている主体の部分というのを、ちょっと教えていただきたいんです。","respondent":"富田教育改革担当課長","answer":"学校給食におきましても、朝、昼、晩、３食きっちり食べていただく、これでやっていきたいと、基本的な部分を考えているところです。あるいは６時までの利用で、こういった方向に向けて努めていきたいというのが、すまいるスクールとしての見解です。","id":"exchange-134"},{"speaker":"大西委員","kind":"質問・要望","question":"現実的に、「補食という意味でどうなんですか」ということで、課長はそのことに対して答弁しているわけですよ。金額的な面もあるでしょうから、そのような形で対応していただけることをお願いして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"本多委員","kind":"質問・要望","question":"６年生が年間５時間ということで、１年生から６年生まで３時間ということだったんですけれども、もう少し詳しく教えてほしいと求めました。４０校ということになりますので、その辺のスケジュールですとか、ちょっと教えてほしいと求めました。","respondent":"中島指導課長","answer":"小学校の１、２年生段階では、英語に触れる場面をＡＬＴとともにつくっていくというような活動をしています。子どもたちが英語を学ぶ上で、ＡＬＴの方と触れ合う時間というのを、これから多くの学校で重視した取り組みを展開していきたいと考えています。","id":"exchange-136"},{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ総合的な学習での時間で、特色ある内容を充実していただきたいと思うんですが、時間的には、学校それぞれの特色で取り組めるということか尋ねました。","respondent":"中島指導課長","answer":"これだけ欲しいということを、さまざまな実態を考慮しながら、ＡＬＴの派遣については考えてまいりたいと思います。１年生からの英語学習の展開に向けて、今後、体制を整えていくというような流れになろうかと考えています。","id":"exchange-137"},{"speaker":"本多委員","kind":"質問","question":"中学校では学習で、入り方なんですが、これは従来どおりでよろしいのでしょうか。拡充ということではほんとうに望ましい方向だと思うんですが、その辺の線引きというか、整理というのはされているんか尋ねました。","respondent":"中島指導課長","answer":"５、６、７年生を中心とした一貫性が一番ポイントになってくる部分ではないかなと思います。６年生、そして７年生の滑らかな連携ということで、子どもたちが身につけていけるように考えているところです。","id":"exchange-138"},{"speaker":"本多委員","kind":"質問・要望","question":"生きた英語というんでしょうか、話せる英語というところで、品川区の役割というのものはものすごく大きいと思っているんです。その辺のプラン２１での夢と力をはぐくむという意味での期待感について、どのようにお考えか、教えてほしいと求めました。","respondent":"中島指導課長","answer":"３、２の三つの段階でまとめた内容で、英語学習の展開を考えております。現在、先行的に進めております英語学習の推進校もありますので、多くの情報を取り入れながら、英語学習の充実に資していきたいと考えています。","id":"exchange-139"},{"speaker":"本多委員","kind":"質問・要望","question":"次の３２７ページの文化センター事業、プラネタリウム室運営費について、教えてほしいと求めました。天体望遠鏡は幾つぐらいあるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"五反田文化センター本館に大きいのが１台、小型が１台、計２台あります。","id":"exchange-140"},{"speaker":"本多委員","kind":"質問","question":"それぞれ取り組みはされているんだと思うんですが、例えば、１年を通じて一番星が見える時期というのが２月ぐらいだと思うんです。１年に何回か、実際の星空を見るような星空観測でしょうか、お考えはいかがか尋ねました。","respondent":"上川内生涯学習課長","answer":"プラネタリウム、昭和５７年ぐらいからずっと続いてあります。１０名とか、２名とか、こちらで把握しております。","id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"子ども、児童を対象にしたものですとか、当然、生涯学習で一般区民への取り組みですとか、さまざまあると思うんですけれども、より一層拡充をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"藤田委員","kind":"質問","question":"私からは、３点お伺いいたします。この辺をお伺いしたいと思います。","respondent":"中島指導課長、谷田部学務課長","answer":"それから、夏休みの間を使ったサマースクールですとか、各学校はさまざまな取り組みを実施していただいているところです。管理運営規則を変更して、夏季休業日を短縮しながら子どもたちの学力の定着を図っていくということは… いろいろな種類がございまして、さまざまな動物が飼われているです。１４人の入学者が２校、１０人が１校、１３人の入学者が１校という状況です。","id":"exchange-143"},{"speaker":"藤田委員","kind":"質問・要望","question":"何も短縮をしなくても、十分に今の中で、ぜひともご努力をいただきたいと強く要望しておきます。悪い面はあまり強調したくないんですけれども、何かそういう感想があれば、お聞かせほしいと求めました。","respondent":"中島指導課長、谷田部学務課長","answer":"鳥インフルエンザの対応の流れの中で、校長を通しまして、全校体制で飼育のあり方を見直すようにというような指導をしております。学校での対応はそのような形の中で、生命尊重というような教育的な意義を継続していきながら… 児童生徒が活性化するとか、社会の多様化への適用力や社会性の育成に効果的だとか、学校行事が活発になるというようなことが言われてあります。","id":"exchange-144"},{"speaker":"藤田委員","kind":"質問・要望","question":"これはちょっと考えをお聞きしておきたいんですが、兄弟校というんですか、何か交流をしながらやるものはないのか。いかがか尋ねました。","respondent":"中島指導課長","answer":"特に、非常に少人数の中で６年間という流れを、固定化された人間関係の中でという部分は、大きいな課題の一つであると認識しています。教育活動に工夫して取り組んでいただいているところですが、教育活動の工夫につきまして、共に考えていきたいと考えております。","id":"exchange-145"},{"speaker":"藤田委員","kind":"質問・要望","question":"強い要望等がたくさんありますけれども、これはやっぱり改革をするわけですから、受ける問題なんですね。その反面、そういう面をぜひともこれから検討していただきたいと、このように強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問・要望","question":"昨今、半径１０cmの円の面積を求める問題がありました。それでも、小学校５年生の約半分の子は、円の面積が求められない。","respondent":"中島指導課長","answer":"私どもが実施いたしました学力定着度調査、そこをまた補っていくというような形で、小学校でも今後の取り組みをやっているところです。これは、１回だけのテストで、また判断できる部分ではないと思いますし、さまざまな実情がある部分かなと考えています。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"そういうふうに、やはり、教えていかなきゃいけないんじゃないですか。我々大人が指導していく、それが教育委員会じゃないかなというふうに思うんですけれども、その辺どうか尋ねました。","respondent":"中島指導課長","answer":"８０％の学習指導要領の内容でつくったにもかかわらず、それによって、また学校の対応が当然変わってくる部分ではないかなと思います。教科指導の充実は、私どもも常に目指しています。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、どうするんですか。こういうことも、じゃあ、入ってきたらどうするんだ、そこら辺も考えないで、女の先生がバットを持って立ち向かって、勝てるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、ある意味で、品川区教育委員会の過失責任を問われるんでしょうか。それとも、あくまで保護者の責任になるんか尋ねました。","respondent":"中島指導課長","answer":"これは、不審者侵入に限らず、私どもが設置している小中学校で起きた事故に関しては、区と教育委員会がその責務を負う形です。","id":"exchange-150"},{"speaker":"須貝委員","kind":"意見","question":"２年生、３年生、そこら辺。やはりもっともっと教育委員会で考えなきゃいけないと思うんですけれども、その辺ちょっとご回答くださいとの意見を述べました。","respondent":"古川教育次長","answer":"日々の対応についての取り組みの部分と、あるいは保護者も含めて、どう取り組んでいけばいいだろうか。日々の取り組みの中で、学校での体制、そして教育委員会としてもそれを支援していく考え方は持ってあります。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"ですけれども、家庭科室とか、理科室とか、美術室、これにはクーラーが設置されていない。これはしてあげるべきじゃないかと思うんですけれども、何かあるんでしょうか、そのご見解だけ説明を求めました。","respondent":"谷田部学務課長","answer":"平成１４年度、１５年度の２カ年度にわたりまして、普通教室に空調機を設置させていただきました。ほかの特別教室につきましては、財政等の問題もありますし、今後の課題かなと思ってあります。","id":"exchange-152"},{"speaker":"塚本委員","kind":"質問","question":"私のほうから、教育委員会制度の課題と、すまいるスクールについて伺います。現状で何を課題としてとらえ、どういう議論がなされているのか、お知らせ願いたいと思います。","respondent":"鷹倉庶務課長","answer":"平成１０年にもそういうことが問題になったということは、どういう役割を教育委員の方々が果たされているんだろうかという課題があったかと思います。","id":"exchange-153"},{"speaker":"塚本委員","kind":"質問","question":"話が大きいですから仕方のないことですけれども、昨年暮れに英国に、教育改革の現状と背景ということの命題を与えられて行ってまいりました。どういう分野のことは指導監督し、どういう分野のことは相談する、現状でどう把握されているかを伺いたいと思います。","respondent":"中島指導課長","answer":"これまでにも都のほうに申し入れを行い、今、検討の状況も進んでいると聞いてあります。大きな課題の部分ではあるととらえてはありますけれども、極力、前向きにこういったところに取り組んでいければなと考えている状況です。","id":"exchange-154"},{"speaker":"塚本委員","kind":"提案","question":"どういうコミュニケーションをとればいいのか、全国の注目を浴びているわけですから、話が進んでいかないと思います。そういう大きな考え方のずれが出てきているように思うんですけれども、この点に関しては、いかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"しかしながら、すまいるスクールの検討の３カ月前、平成１３年６月、大阪池田小学校の痛ましい事件が起こりました。これらを進める中におきましても、学校とのさらなる連携、模索していきたいと考えているところです。","id":"exchange-155"},{"speaker":"塚本委員","kind":"質問","question":"何でもそうですかと、この心配、そうですね、工夫すればどうにかなりますと。そう思いますが、見解はいかがか尋ねました。","respondent":"古川教育次長","answer":"保護者、あるいは親の求めをすべて区が受け入れて、それをまたすまいるスクールで実現していくという考えにも立ってないのもまた事実です。こういう観点で、すまいるスクールの運営につきましては、十分に意を尽くしてまいりたいと、このように考えてあります。","id":"exchange-156"},{"speaker":"土井委員","kind":"質問・要望","question":"先ほど質問がありましたけれども、いわゆる学校でどういう小動物を、どう飼っているのかという調査等をやりたいやにも伺っているんですよ。どうせ答えも出てくるでしょうから、ここで若干お話をすれば、例えば私立の場合ですと、お受験で試験を受けさせて入れているわけですね。","respondent":"鷹倉庶務課長、中島指導課長","answer":"そこに学校のほうから、メンバーに教職員の方に入っていただくという形で、今進めております。４月１日から会議体を興していくために、今、教職員の推薦を求めているという段階です。その中で、それの実現に向けて、プラン２１がさまざまな方策を講じているところもご理解いただいているところではないかなと考えています。","id":"exchange-157"},{"speaker":"土井委員","kind":"質問・要望","question":"情操教育をしていくということのための必要があるんですから、どうしているのかというのがちょっと気になるものですから、お聞かせいただきたい。対処が必ず必要になってくるわけですから、この部分をどう考え、何かありましたら説明を求めました。","respondent":"谷田部学務課長、若月教育長","answer":"飼育動物の関係ですけれども、学務課のほうで、飼育動物が病気になった際には、獣医師に見てもらうということで予算計上しています。そういうことで、日常的には、動物病院の先生方とは… さまざまな方法を、その子どもに合った、子どものレベルに合ったキャッチボールのやり方もあります。試合に参加できる意欲を持たせる、これが我々教師というプロ集団に求められている要請ではないだろうかと、こんなふうに考えています。","id":"exchange-158"},{"speaker":"土井委員","kind":"質問・要望","question":"と同時に、子どもたちの間でも、例えば死んじゃったというときにどうするのか、みんなで話し合ってうまいぐあいにやってもらいたいと思うんですよ。プラン２１のほうですが、いわゆる生きる力をつけてもらう、そういうためにご努力をお願い申し上げて終わらせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"沢田委員","kind":"質問","question":"私は、３０１ページのプラン２１、あるいは小中一貫校にかかわって、１点だけ質問をしたいと思います。習熟度別学習の占める位置が大きいと思いますけれども、これまでの習熟度別学習をどう展開をしていくのか、区側の考えをお知らせ願いたいと思います。","respondent":"中島指導課長","answer":"現在の取り組みの形は、もうすべての小中一貫校での実施という形になっておりますので、実際の予算的には継続をする形で取り組んでいく。これは、今の状況の継続という形では、今後も同じ部分と考えています。","id":"exchange-160"},{"speaker":"沢田委員","kind":"意見","question":"あるいは実践がどうなのかということと、それから、習熟度別学習がより優秀だという研究結果は果たしてあるのかという点。説明願いたいと思いますとの意見を述べました。","respondent":"中島指導課長","answer":"その中には、具体的に、学習内容の習熟の程度に応じた指導を充実していくというような部分が追加されてあります。習熟度別学習の充実というのは、日本で申し上げれば、全国的な方向かなという考えがあります。","id":"exchange-161"},{"speaker":"沢田委員","kind":"質問","question":"スイスの３カ国だけで、混合教育とでも言うんでしょうか、そういうふうになっている。もしこのテストのねらい、結果をどう分析するかということが区側にありましたら、ご説明願いたいんですが。","respondent":"中島指導課長","answer":"進学予定者の進路のことをトラックというわけですが、これを振り分ける社会構造のことを指していると、私どもは理解しています。その指導の手段を考察するものでもないと、このように、この調査についてはとらえてあります。","id":"exchange-162"},{"speaker":"沢田委員","kind":"質問","question":"そこを知らないとすれば、子どもたちをここに影響させるものですから、今からでもいいから研究してほしい、勉強してほしいと、まず思います。１９８０年代に２０％の失業率、どうにもならなくなった段階で、教育委員会の権限を学校と教員に下ろした。","respondent":"中島指導課長","answer":"これは国立教育政策研究所のスタッフの話ですけれども、そういったような視点もぬぐい去ることはできないというようなことを話しています。そして何よりも、今私どもが進めている中での子どもたちの育成をベクトルをそろえる形で進めていくのが重要と、このように考えてあります。","id":"exchange-163"},{"speaker":"沢田委員","kind":"質問・要望","question":"書店で本をずっと見るのが私の趣味ですから、果たしてこれでいいのかと、これは急いでいろいろな資料を取り寄せて研究すべきだと思います。先進国で４０人学級をやっているところはないわけですから、少人数学級、小グループの共同の学びの場をつくることを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-164"},{"speaker":"三上委員","kind":"質問","question":"これに対して、どう取り組んでいかれるか、ちょっとお伺いしたいと思います。それからもう一つは代表質問でお伺いしましたが、再質問すべきであったと思うんですけれども、この件についてちょっとお伺いしたいと思います。","respondent":"鷹倉庶務課長","answer":"荏原第一中学校のグラウンドの砂ぼこりの件で質問していただきました。具体的にどういう形で対応していくかというのは、どういう対策をしていくか、こういう形でやっていきたいと考えています。","id":"exchange-165"},{"speaker":"三上委員","kind":"質問","question":"ですから、対応をお願いしたいと思っているんですが、ご意見をちょっとお伺いしておきたいと思います。ちょっとお伺いしたい。","respondent":"鷹倉庶務課長","answer":"まちづくり事業部とも、いろいろ歩調をそろえながら、一緒に研究していきたい、取り組んでいきたいと考えています。定数を０にし、過員の解消をしていっている結果の中で、今残っているという形です。","id":"exchange-166"},{"speaker":"三上委員","kind":"質問・要望","question":"そういったこともありますので、それについてはしっかりと計画を立ててやっていただきたいと、こういうふうに要望しておきたいと思います。現実、今そういうふうに区の職員が残っている中にあって、学校間格差ということについては、どういうふうにお考えになっていらっしゃいますか。","respondent":"鷹倉庶務課長","answer":"確かに、正規の区の職員がいる部分と、嘱託の部分、そして非常勤の部分という形で、混成しているわけです。県費負担の事務職員の力、あるいは非常勤の力、全体をトータルとしてとらえながら各学校の格差がないような形での配置に取り組んでいるです。","id":"exchange-167"},{"speaker":"三上委員","kind":"質問","question":"生徒数もやっぱり仕事量的には考えるべきだろうと、こう考えたときに、児童数が大井第一小学校は７２１名います。人数的には、それなりの配置をされていると、そういうふうに受けとめたいんですけれども、第二日野小学校に、今何名配置されているんか尋ねました。","respondent":"鷹倉庶務課長","answer":"第二日野小学校につきましては、事務が県費職員が１名、そして区費職員はいませんので、非常勤が１名配置されているところです。","id":"exchange-168"},{"speaker":"三上委員","kind":"意見","question":"現段階と４月の段階でちょっと違いがあるということで申し上げておきましたので、そこらあたりの数字がちょっと違っているのかわかりませんけれども、７４名しかいない第二日野小学校と、７２１名と１０倍いる生徒数のところの職員数は違いはありますかとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"第二日野小学校につきましては、ご案内のとおり小中一貫校の開設を控えて、これからいろいろ準備をしていくという要素があるということがあります。本格的な小中一貫校に向けて、日野中学校との事務の連携だとか、いろいろ打ち合わせをしていくという要素があります。","id":"exchange-169"},{"speaker":"三上委員","kind":"質問","question":"時間があれですから、ちょっと先に進みますけれども、こういった都費職員の代表質問の流れからいったら、都費職員の異動について伺っています。基本原則として、都費職員の異動条件というのは、どういうふうになっておりますか。","respondent":"鷹倉庶務課長","answer":"代表質問でもお答えしておりますけれども、それに基づきますと、現任校に引き続き５年以上勤務する職員は異動するものとなるということがあります。そうした上で、原則として同一区に１０年勤務した時点で、他区への異動対象となっているということが一つの基準です。","id":"exchange-170"},{"speaker":"三上委員","kind":"質問","question":"同じ品川区内に１０年以上になったら異動するということが一つの原則論として、今おっしゃったわけですから、２０年以上いるような人っていますか。ちょっと長い人について、ちょっと言っていただけますか。","respondent":"鷹倉庶務課長","answer":"確かに、２０年以上いらっしゃる方もいらっしゃいます。","id":"exchange-171"},{"speaker":"三上委員","kind":"質問","question":"それが移らないということについて、それでいいと思っていらっしゃるんですか。どうなんでしょう。","respondent":"鷹倉庶務課長","answer":"そして、先ほど、２０年以上の方がいらっしゃいますわけですけれども、これは区内の中で各学校を異動されてあります。原則的には、１０年勤務した時点で他区へ異動するということになっているわけですけれども、異動しない場合も例外的にあります。","id":"exchange-172"},{"speaker":"三上委員","kind":"質問","question":"１０年以上が原則という、原則というのはどういうことですか。どうなんか尋ねました。","respondent":"中島指導課長","answer":"東京都の区市町村学校事務に関しましての異動実施基準というのが、私のほうから、今の部分をご答弁をさせていただきたいと思います。各事務職の人数の定数の関係で、非常に区外異動というのは、実質的には非常に少ないという現実があります。","id":"exchange-173"},{"speaker":"三上委員","kind":"質問・要望","question":"６年間も経っているということですから、そのところを十分に考えていただきたい。図書館部会で、そういう監査前監査なんてやっていますか、どうか尋ねました。","respondent":"古里品川図書館長","answer":"通常の事務的なレベルでは、各館の職員にチェックをするように申し伝えてありますが、他の館から他の館に行って、それをチェックするというようなことはしてございません。","id":"exchange-174"},{"speaker":"三上委員","kind":"質問","question":"時間があればずっと皆さんにお伺いしたかったんですけれども、それができないからですけれども、これは、本来だれが聞いたっておかしいと思いますよ。おかしいじゃありませんか。","respondent":"古川教育次長","answer":"少なくとも監査に臨むに当たって、これまでの学校の体制があまりにもお粗末であった、この一言に尽きるであろうと思ってあります。あるいは、監査資料等について整理をしているわけであって、決して不適切な処理をしているわけではございません。","id":"exchange-175"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのことについて、ご理解しているのか、ぜひ確認をしていただき、答弁をいただきたいのが一つ。それから協力を求めることがあるかと思いますので、まずこのことは基本的な部分としてきちっと答弁をいただきたいんですが、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"去年の６月９日の文教委員会で、小中一貫校の基本的な考え方、基本設計等をご説明申し上げたところです。今回の説明会の中で、どういうふうに対応していくのかというような点のご質問だったかと思いますけれども、説明会を開催していく中で。","id":"exchange-176"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、議会の議決の重みをどう考えているかということを、もう１回、きちんと答弁をお願いしたい。それから、削った修正案が、いわゆる最終的な案であるかどうか、そのことをお伺いしたいんですが、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"地域への説明会は、そして年を越して１月１９日に第３回目の説明をしたわけですけれども、２回目の１２月１７日の段階で。１月１９日に提案したものが最終案かですけれども、私ども、３回目のときに、区としてこれが最終案ですという形で、住民説明会に臨んでおります。","id":"exchange-177"},{"speaker":"伊藤委員","kind":"質問・要望","question":"お伺いしたのは、教育委員会が決定したことはわかっているんですけれども、もう少し具体的な答弁をいただきたいのが一つ。それを品川区が選択してしまったわけですから、そのことについての、これからの将来的な対応、そのことについての取り組みをぜひ説明を求めました。","respondent":"古川教育次長","answer":"現実に説明会の中でのさまざまな要望、さまざまな角度での検討を、これからの中にはそれを生かしていきたいと思ってあります。現実の対応というのは、あるいは私どもの説明を加えることによって、このように考えてあります。","id":"exchange-178"},{"speaker":"伊藤委員","kind":"質問・要望","question":"反対したら変わるという風潮が出てきてしまったわけですから、それについてどう対処していくかということを、もう一つ答弁いただきたい。もし払うんであるんでしたら、何かしら法的な対応があるんでしょうかということをお伺いいたしますが、いかがか尋ねました。","respondent":"古川教育次長、本間総務部長","answer":"前段の関係ですが、私ども、反対があったのは事実ですが、反対があったら即変更したというわけではございません。あくまでも、小中一貫校の必要な事業を平成１８年４月に向けて完成させていくということの一点に絞り込みながら… 区が近隣に行いました補償的な面ですが、例えば、今までですと、電波障害等々について対応したということはありますが、具体的な迷惑料として、金額で、法規制に合致した建物で賠償責任を生じたということは、今まで１件もございません。","id":"exchange-179"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/906948?Template=document&Id=832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":128948,"voices":411}},{"id":"h16-20040317-3","meetingId":"h16-c-budget","date":"2004年3月17日","dateIso":"2004-03-17","committee":"予算特別委員会","time":"午前１０時０５分～午後６時５９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を120件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"初めに、東京二十三区清掃一部事務組合のことについてお伺いをいたします。スリム化、地域処理への移行など仲間づくりを含めて、改めて区長から決意を述べてほしいと求めました。","respondent":"高橋区長","answer":"一番難しい中間処理の問題について、平成１７年度末まで東京二十三区清掃一部事務組合において中間処理を実施していくということを決めまして。東京二十三区清掃一部事務組合は区長会の意向に対して実施をする、これからもそのような方向で努力してまいりたいと考えています。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"今回こうやって我々質問事項とさせていただきましたが、品川区にとって何がよいかということをやっていってほしいと求めました。導入後３年が経過しておりますが、事業部制のメリット、デメリット等はどのように今把握をされているのかお聞きいたします。","respondent":"市岡企画財政課長","answer":"少し背景について説明しますと、平成１２年にはご案内のとおり都区制度改革行われ、あるいは地方分権一括法が施行される。こういう財政構造の転換に大きく寄与してきた、このように考えてあります。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"予算編成について、私も触れていきたいと思います。もうちょっと具体的にメリットの部分、３年間やってきたけれどもあまり変わらなかったと思う部分があれば、もう一度改めて細かく教えていただきたい。","respondent":"市岡企画財政課長","answer":"１点は、これまでもご説明申し上げましたとおり事業部編成枠方式と、こういうことを取り入れました。ここでも積極的に政策提案あるいは見直しの状況等、各事業部ごとの編成方針についても説明していただくと、このようなことをやってあります。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問・要望","question":"この中で今お伺いをして、経常経費が事業部編成枠方式を取られたんだという形のお話がありました。経常経費もマイナスシーリングをかけて自由度を使わせてくれという思いがあるわけでしょうから、お答えをほしいと求めました。","respondent":"太川区民生活事業部長、小沼福祉事業部長、新美保健高齢事業部長、松本環境清掃事業部長、中谷まちづくり事業部長","answer":"私どもはそれを臨時政策事業のほうに回させていただけるということで予算編成してまいりました。そのうち先ほどの経営会議等でプレゼンテーションを… 私どもの場合ですと、障害者等を中心とする厚生援護部門と子育ての支援の関係ということの中で。プレゼンテーションは限られた時間ですけれども… 第１にリハビリ介護予防の充実、痴呆性高齢者のケアの充実等、介護保険第２期の課題への取り組み、これが第１の課題です。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"今、お話を伺った中で、私の調べた中では福祉関係が非常に多いなというのと、教育関係も多いなというところがあります。ですから、そこの２人の事業部長に、三人の方に答えていただければありがたい思います。","respondent":"市岡企画財政課長","answer":"各事業部門がそれぞれ重点と考えている施策について、現場の実態を十分私どものほうで聞きながら、各事業部門と財調については調整をしています。","id":"exchange-005"},{"speaker":"石田委員","kind":"質問","question":"ですから、さっと答えられるというところまで持っていくのが本来の事業部制だろうと私は思っております。企画部はそうやって戦略的に人を配置しているんだよと、情報システム課でも結構ですが、そういう点についてお話をお伺いしたいと思います。","respondent":"本間総務部長","answer":"委員ご指摘のとおり事業部の経営に必要な、例えば財政面に精通した職員等々の各事業部からの要求というものは、当然強いものがあります。そういう中で、各事業部におけます経営能力は拡充していると、このように考えてあります。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"各事業部長にどういう気持ちなんだというのを幾つかお伺いしてもいいのかなと考えていますが、ゼネラリストという話をするわけではありませんが。今、若干努力はしているというご答弁がありましたが、もう一段突っ込んで、その辺の点のお考えをお聞かせ願いたいと思います。","respondent":"高橋区長","answer":"そういう面も私は必要じゃないのかなというふうなことを思いつつ、現在３年目に事業部制が入ってきているわけです。この成果は少しずつでも伸ばすように、皆さん方のご意見をいただきながら、よりよい事業部制にしていくよう努力をしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問","question":"今のお話の点は、ぜひもう一度お伺いをしたいと思います。先ほどちょっとお伺いをいたしましたが、どういう意味合いで事業部制を敷いたのかというところで、この辺の点を改めてもう一度お聞きします。","respondent":"濱野助役","answer":"そこの協力関係あるいは、そこの援助を仰ぎながらそういう経営をやっていく。事業そのものは、その分野についてのスペシャリスト的な知識というのは、一番重要なことだというふうに考えてあります。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"もしやっていたらやっていたでも構いませんが、財調等を含める研修の強化をしていただきたい、こういう考え方はどうなのか。款別審査の予算・決算特別委員会の形の中で、そういう意味の研修と、款別審査のときの説明の部分をどうお考えになっているか説明を求めました。","respondent":"濱野助役、中尾根企画部長","answer":"そういうことを通しながら、その事業部長は財調のありようについてはかなり精通をしております。その辺はご心配なきようにやっているつもりですので、よろしくお願いします。 例えば今回の予算特別委員会での説明につきましては、それぞれの予算審議のために統一的な説明をするということで、今後においても統一した説明をこちらのほうでさせていただきたいと。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"今、５段階で評価をされていると思いますが、１と２を取っている人の数を教えていただきたい。教員の場合は５段階で、下のほうがＣ、Ｄということだと思いますが、この辺のＣ、Ｄを取っている人の数を教えていただきたい。","respondent":"本間総務部長、若月教育長","answer":"厳格な対応をしていますが、連携して問題の職員についての行動等々を把握して、厳格かつ客観的に把握しているという状況です。厳格な指導… Ｄが３名、中学校の場合にはＣが５５名のＤが５名と、こういった枠の中で評定をするというようなことになってあります。さて… それぞれの厳格な指導や研修を行う中で、それぞれの職員につきまして生活態度なり、職務に向かう姿勢なりに改善の傾向が見られるという状況です。","id":"exchange-010"},{"speaker":"石田委員","kind":"質問","question":"２を取った人はこうというような研修等があるとは判断しておりませんので、研修等を含めてシステム的にそういうことを行っているのかどうか、改めてお伺いしたい。","respondent":"本間総務部長","answer":"そういう意味で接遇の研修等には必ず参加させるなど、そういう研修ともリンクして、こういう職員の資質の向上に努めているです。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問","question":"私が言っているのはそういう意味あいで、例えば１の方にシステム的に特別な研修を行うべきだろうと考えています。そういう方には、どういう処置をされているのか、それを併せてお聞きしたい。","respondent":"高橋区長","answer":"真面目に働いている職員に対しまして、不真面目な職員に対しましてやはり厳罰をもってあたることも必要だと考えています。この研修も一般の研修ではなくて特別な研修をし、善導してもだめな場合、これはやむを得ず分限の適用もこれからやっていきたいと考えています。","id":"exchange-012"},{"speaker":"石田委員","kind":"提案","question":"そうすると、さまざまいい提案等も出てこなくなってくる。指導は非常に強くやってほしいと求めましたので、最後にその辺の点のお話を伺って、私の質問とさせてほしいと求めました。","respondent":"若月教育長","answer":"いわゆる人事考課の低い教員、いわゆる指導力不足の教員についての対応です。さらに個別的に研修を強化し、それぞれの教員が自らの進路を自らで考えられるような、そんな状況もつくっていきたいと、こんなふうに考えております。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"予算編成に対しまして、私ども自民党品川区議団につきましては、昨年の１０月初頭に区長のほうに予算政策、予算要望書を出させていただきました。あるいは区民の皆さんからのお声を入れての予算編成に対する要望をしたわけですが、いろんな場面で議会側からの予算要望という形があると思います。","respondent":"中尾根企画部長、本間総務部長","answer":"要は戦略的な組織ですから、時代に合った政策というものを、常に区民のニーズに合わせて求めていくというのが特徴です。広い意味での施策ですけれども、これを基本に区民が安心して暮らせる、このもとに編成したつもりです。そういう中で、研修だけではなくていろんな仕事を経験する中で、さらにその職員の能力が伸びるというジョブローテーションという考え方もあります。","id":"exchange-014"},{"speaker":"須藤委員","kind":"意見","question":"続きまして、ケーブルテレビの活用についてお尋ねをいたします。平成８年４月に開局されまして、それから現在のケーブルテレビの区側の活用状況、そういったものにつきましてお知らせくださいとの意見を述べました。","respondent":"中尾根企画部長","answer":"今、委員が歴史的な経過をご説明いただきましたけれども、行く行くは双方向性を活用した行政のプラスを見込めるのではないか。区民に提供してまいりましたけれども、もっと力を入れていきたいと、このように考えているところです。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"当初予想したより、進捗状況というのは早いんじゃないかなというような感じを持ちますが、その辺はいかがでしょうか。そういったものとケーブルテレビとうまく組み合わせというか、そういったものがどんなふうに図られていくかお聞かせ願いたいと思います。","respondent":"中尾根企画部長","answer":"そのときに、しかも無料で見られる５チャンネルというものも提供していこうという考え方でございましたので、この加入率が非常に高いです。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問・要望","question":"出資金が２億５,０００万円というのが計上されておりますが、この質問に対しまして、詳しくご説明をお願いいたします。併せて、今後の区の係わり方についてもお知らせをほしいと求めました。","respondent":"中尾根企画部長","answer":"強力に支援を区としてはしてまいりましたけれども、そうした会社そのものの経営方針が新しい転換期の中で大きく作用する時期にあるだろうと。デジタル化に対応するだとか、こういうことの中に区としても全力を尽くして参加していきたい、このようなことです。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問・要望","question":"最初にお話しましたように、区の催しとかそういった中に、いろんなイベント等についてもお知らせいただきたいという話があったわけです。そういったことについても広報していくということが必要だろうと思いますが、いかがか尋ねました。","respondent":"中尾根企画部長","answer":"したがいまして、区民の姿が見えるものに、地域のメディアとしていく必要があるだろうと考えています。双方向性を活用した医療の分野での画像を見ながらのやり取りだとか、そういったことも将来的には活用できるように、このように考えてあります。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど、そのときの社会情勢に合わせたことも考えてくるというようなことで、少子化の問題について少しご質問をさせてほしいと求めました。逆に子どもの状況から見て、少子化という形が児童の福祉に与える影響というのはどんなものがあるかお聞かせ願いたいと思います。","respondent":"小沼福祉事業部長","answer":"今、１世帯当たり１.９１程度の構成人数ですので、あるいは見えないというようなところが一つ大きな問題であろうかと思います。もちろん、私ども直接に区民生活に密着する形での少子化支援をつかさどるところといたしましては、こういうふうに考えてあります。","id":"exchange-019"},{"speaker":"須藤委員","kind":"質問","question":"柔軟性がなくなってきている。そういった体の面でも変化が見られますけれども、このあたりについてはいかがか尋ねました。","respondent":"伊藤品川区保健センター所長、小沼福祉事業部長","answer":"児童の体力の低下ということに関しましては、平成１３年度に全国と東京都と比較をいたしますと、小中学校で全般的に下回ってきている。それから、１０年前のデータと最近の体力テストの比較をいたしますと… あるいは、散歩等に連れて行きましても、なかなか体力的な低下というような問題が見え始めているということ、これは事実です。","id":"exchange-020"},{"speaker":"須藤委員","kind":"質問","question":"ちょっと、その辺を学校のほうでそういったデータを取っていらっしゃるかどうか。それから、足の形態異常、そういったのを見られているんじゃないですかと。","respondent":"伊藤品川区保健センター所長","answer":"低体温ということに関しましては、私ども保健サイドとしては格別のデータは持ち合わせておりません。乳児健診とか３歳児健診とか、いろいろな健診の場はありますけれども、小学校に入る前の段階で特に持ち合わせておりません。","id":"exchange-021"},{"speaker":"須藤委員","kind":"質問","question":"ですから、大人たちは自分のこういった研究あるいは追求していために時間がというので、いろんな考え方ができると思います。そういったことにつきましては、いろんな面で危惧されてくるわけですが、改めて児童福祉法第１条、第２条についてお知らせ願いたいと思います。","respondent":"小沼福祉事業部長","answer":"今、ちょっと法文が手元にございませんけれども、児童福祉法の理念あるいは趣旨というところに行き着くと思います。","id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"いわゆる３歳児神話だとか母性神話だとかというふうな形で、相互の同調性というか、いろんな研究がなされているわけです。保育所に預けるとか、そういった乳幼児の環境整備というものについては、どんなふうにお考えか尋ねました。","respondent":"小沼福祉事業部長","answer":"行政としましては補完していくというのがこれからの、また今後の児童福祉行政の基本的なスタンスであらねばならないというふうに考えてあります。今申し上げたようなところは、第３条にもまた同じようなことが言われておりますので、間違いないというふうに考えているところです。","id":"exchange-023"},{"speaker":"須藤委員","kind":"提案","question":"今、そういったものを前にご提案したことがあるんですが、通信簿みたいな形で学期ごとに返されたりというようなことはいかがでしょうか。それぞれお答えをほしいと求めました。","respondent":"若月教育長、小沼福祉事業部長","answer":"骨格の問題、そうしたこともこれから大変子どもの体力についても、健康についても重要なことだろうと思います。今後、学校とも十分に検討しながら、そうしたものを家庭に適切に情報が提供できるよう検討していきたいと… 常々その子どもについての健康管理あるいは生活面での観察というようなことに努めていまして、あるいは乳幼児の健全育成に役立てると。こういうようなことも兼ねて、いずれにしましても健全育成に努めていると、こういうような状況です。","id":"exchange-024"},{"speaker":"須藤委員","kind":"質問・要望","question":"いずれにいたしましても、次世代を担う子どものためにという政策で持っていってほしいと求めました。改めて質問しますけれども、保育園あるいは児童センター、そういったものを含めてお知らせ願いたいと思います。","respondent":"古川教育次長","answer":"これが一つ東京都が２３区含めまして体制を取っている、こういうところに私どもも最大の備えということでやってあります。学校１１０番システムを中心にしたさまざまな防犯体制を取っていると、こういう現状です。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのことにつきましては、今お話しさせていただきましたように、子どもの体力あるいは柔軟性、そういったものに考慮していただけるかどうか。すまいるスクールに全部入れちゃうよというのではなくて、そうした応用性も考えてほしいと求めましたが、いかがか尋ねました。","respondent":"古川教育次長","answer":"すまいるスクールは、これもたびたびご説明していますけれども、小学生の放課後の過ごし方はさまざまであると思ってあります。学習、塾もそうでしょうが、そういったものとすまいるスクールがバッティングするというふうには考えてございません。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問・要望","question":"続きまして、指定管理者制度につきましてお尋ねをします。管理者制度へ切り替わる３年間の間に、どういった手順で進まれていくのか、そのあたりにつきましてお話を聞かせてほしいと求めました。","respondent":"中尾根企画部長","answer":"それから二つ目には、ランニングコストの縮減等にどのようにつながっていくのか、財政にどのように寄与していくのかという点が２点目。それから、この３点から今後の指定管理者制度をどのように導入するかということを検討していきたいと、このように考えてあります。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問","question":"その辺の棲み分けというか、考え方というのが必要であるかと思いますけれども、福祉施設への指定管理者制度の導入についてはいかがでしょうか。今後、３年間、どうやって具体的に進んでいくかお聞かせ願いたいと思います。","respondent":"中尾根企画部長","answer":"こういう考え方からこの分野でのお願いをしてきたわけですけれども、どのように考えていくのか、ここが今後の検討になるかと思います。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問・要望","question":"ただ、やはりいろんな面でご配慮を願って、３年間の間に検討されて対応されてほしいと求めました。あるいは地域センターでの役割、その辺をつなげたりする場合の区側の役割というのをお知らせ願いたいと思います。","respondent":"太川区民生活事業部長","answer":"地域団体の活動に対してまして、地域社会の活性化につながるよう、区といたしましては側面からの支援をしていくということが大きなものだと思います。もう一つ、それが自主的にまた主体的に地域の問題を解決できるよう、そういう支援もしていくものと考えています。","id":"exchange-029"},{"speaker":"須藤委員","kind":"意見","question":"近年、インターネットが非常に発達してきて、若い人たちはそういったものに対応してきております。そういったインターネットの活用を、地域センターを中心にされていくようなシステムを構築されたらいかがかと思いますが、お考えを説明するよう求めました。","respondent":"太川区民生活事業部長","answer":"これは既にインターネットを使って約２０ぐらいの町会がホームページ等をつくりまして、それから行事の内容、大変大きな反響を呼んです。地域センター、それから町会等々の中で積極的にそれにつきまして取り組んでいくということで、今後やってまいりたいと考えています。","id":"exchange-030"},{"speaker":"須藤委員","kind":"質問","question":"今、事業部長のお話のように、一つのまちの声が立ち上がってきた。これがどんどん大きく広がっていくことを祈念しながら、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"若林委員","kind":"提案","question":"質問の１点目といたしまして、地域との協働とは何でしょうか。２点目といたしまして、平成１６年度予算を執行することによりまして、これからどのように実現されていくと思われるか伺いますとの意見を述べました。","respondent":"太川区民生活事業部長","answer":"活動の場の提供や指導者の育成、必要に応じては活動費の助成など、側面からの支援が欠かすことのできない要素と考えているところです。次に、平成１６年度におきまして、ボランティアの参加をいただきながら実施していく事業が多々あります。","id":"exchange-032"},{"speaker":"若林委員","kind":"質問","question":"そこで、質問のもう一つは、上大崎地域の地形的特徴を区としてどのように認識しておられるかお尋ねいたします。さらに、３点目は、その上で上大崎地域の区民ニーズを、現在どう掌握されているのかを伺います。","respondent":"中尾根企画部長","answer":"したがいまして、目黒駅ないしは五反田駅の周辺は別としまして、全体としましては緩やかな変化が来ていると、こういう地域として認識しています。ただし、施設の場所のありようのことにつきましては、いろいろ今後にも課題が残っていると、このように認識しています。","id":"exchange-033"},{"speaker":"若林委員","kind":"質問","question":"この課題の解決のために、どのようなご努力をされていくのか伺いたいと思います。３点目は連帯感ある地域社会の構築や協働を進めるために、どうお答えしていく姿勢なのかをお尋ねしたいと思います。","respondent":"岩野まちづくり事業部次長、野田口選挙管理委員会事務局長","answer":"こういった中で、さまざまなバリアがあるですが、ご指摘のバリアの解消に努めていきたいというふうに考えてあります。今言ったような例えば住民の方のふれあいが事業の中に導入できるかどうかといったようなことを検討しながら… 現在２９名ということで体制的にも強化してきてありますので、この選挙に関心を持っていただけるよう努めていきたいというふうに思ってあります。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"２点目は、併せて当プロジェクトに対し、区としてこれまでどのような地域の要望、期待の声を伺っているかを伺います。地域協働の中心拠点となるべき施設などを組み込まれるよう、実現させるべきと要望いたしますが、ご所見を伺います。","respondent":"岩野まちづくり事業部次長","answer":"それから、３点目が、ＩＴを含めた国際化に対応した情報交流拠点、まちづくりの中心となる行政サービス拠点等の形成を図っていただきたい。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"質問の１点目は、改めて特別支援教育の区でとらえられている理念を伺います。もう１点は、また心身障害学級や特別な場において教育を受けているすべての児童・生徒に、どのような効果があらわれると期待されているかを伺います。","respondent":"古川教育次長","answer":"これもたびたび特別支援教育についてはご説明申し上げているところですけれども、一人ひとりの教育ニーズに応じた個別の適切な教育支援を行うと。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問","question":"このようなことから、区検討委員会におきましても軽度発達障害児の親の代表を参加させる必要があると思いますが、ご所見を伺います。情報がひとり歩きしないよう、保護者の不安を最小限にとどめる工夫が必要と考えますが、お考えを伺います。","respondent":"古川教育次長","answer":"検討の状況に応じましては、検討の進捗によりましては、いずれにいたしましても検討委員会のあり方をこれから詰めてまいります。この特別支援教育は周知あるいは啓発といったことが一番大きな課題ではないかというふうにとらえてありますので、このように考えてあります。","id":"exchange-037"},{"speaker":"若林委員","kind":"質問・要望","question":"障害者団体の代表などが３０名の中に入っておりますけれども、ぜひとも前向きにお考えを願いたいと、改めて要望しておきます。の具体的な啓発活動を怠りなく行っていただきたいことから、お考えをお尋ねいたします。","respondent":"古川教育次長","answer":"私どもは当面この制度につきまして校内研修あるいは合同研修の実施、そして専門性の向上にまずは努めてまいりたいと、このように考えてあります。この特別支援教育に対するさまざまな理解、啓発に努めてまいりたいと、このように考えてあります。","id":"exchange-038"},{"speaker":"若林委員","kind":"質問・要望","question":"モデル校の設置について、お尋ねをいたします。東京都においても既に二つの自治体でモデル設置していることから、早期な設置を改めて要望したいと思いますが、お考えをお聞かせ願います。","respondent":"古川教育次長","answer":"こういうものをとらえながら既に２年目をこれから迎えようとしていますけれども、私どももこれから検討委員会を立ち上げてまいります。","id":"exchange-039"},{"speaker":"中島委員","kind":"質問・要望","question":"その中で、この学校１１０番の機能はどのようになっているのでしょうか。校舎内での問題、課題などがありましたら、教えてほしいと求めました。","respondent":"古川教育次長","answer":"学校１１０番の仕組みですが、平成１３年に全小中学校等に設置したわけですけれども、自動的に緊急通報がまいります。もちろん教育委員会も一定の設備については設置しながら、平成１６年度におきましては全小中学校、このように考えているところです。","id":"exchange-040"},{"speaker":"中島委員","kind":"提案","question":"そこで私は提案をしたいのですが、学校の入り口に学校事務の方がおられる事務室を配置してはいかがでしょうかということなんです。そういう点で便利であり、不審者の侵入も妨げるということもあると思いますので、この点についてのご見解をお知らせくださいとの意見を述べました。","respondent":"古川教育次長","answer":"１階の出入口近くに事務主事、こういったものをできるだけ近くに設置するような形で、それぞれ設計の中で配慮しています。そして人の対応、こういったものをこれから十分に検討していきたいと、このように考えてあります。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問・要望","question":"児童の命がかかっていることなのだということの視点を忘れないでほしいと求めました。次に、あらゆる危険から自分の身を守れるような教育、発達過程に応じた安全教育というのはどのようになっているのか尋ねました。","respondent":"古川教育次長","answer":"六年生とはまた違った対応になりますけれども、それぞれの学齢に応じた対応、指導を実はしています。手立てと申しますか、そういったことをさまざまな形で取り組んですし、自らの体を守るという観点からさまざまな取り組みをしているのが実情です。","id":"exchange-042"},{"speaker":"中島委員","kind":"提案","question":"そこで質問しますが、初めに学校図書館のコンピューターオンライン化について４点お伺いいたします。３点目は、協力するＮＰＯに期待するものはどのようなことなのでしょうかということで、質問をしますとの意見を述べました。","respondent":"古川教育次長","answer":"読書活動推進計画ですけれども、平成１５年度におきまして一定の計画立案の検討を進めてあります。来年度早々に、先ほど申し上げました検討委員会の中で学校図書館と区立図書館がそれぞれノウハウを持ち合いながら、このような考え方です。","id":"exchange-043"},{"speaker":"中島委員","kind":"質問","question":"これは質問者側の一方的な発言に終わった感がありましたので、改めて正確な認識をしていきたいと思いますので、質問をします。一つ目に、まず委託を行う基本的な考え方、これをお願いいたします。","respondent":"古川教育次長","answer":"民間の力を活用することによって、接遇も含めたサービスの向上が図られるということと、当然のことながらコストダウンにもつながっていると。","id":"exchange-044"},{"speaker":"中島委員","kind":"質問・要望","question":"民間の方にお願いして、できることはそこでやるということなんですが、区の職員が行う業務、役割、これについて説明をしてほしいと求めました。","respondent":"古川教育次長","answer":"こういったものがありますし、こういう民間委託によって一定の職員のノウハウを傾注できる部分なのかなというふうに思ってあります。こういったことが今回の民間委託の中から、さらなる活動業務として見えてきているのかなと、このように考えてあります。","id":"exchange-045"},{"speaker":"中島委員","kind":"提案","question":"私たち公明党は、この図書館の発展のために、以前図書館基金というものを提案してきた経緯があります。広く区民の方々の知的財産を育む図書館運営をお願いしたいと考えていますが、このことに対して、一言区としてのご所見をお願いいたしますとの意見を述べました。","respondent":"古川教育次長","answer":"品川区内１０館がさらなるスタートをし、そういうことに今後取り組んでまいりたいと、このように考えてあります。","id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"これまで私たちは、広報紙やケーブルテレビなどに、区民の方にとって必要と思われる内容を放映したり載せてほしいと要望してまいりました。そこで、初めに広報全般に対する現状と区の方針、今後の考え方をお伺いいたしたいと思います。","respondent":"中尾根企画部長","answer":"複雑な今の社会情勢を鑑みまして、相談件数も非常に多くなってございまして、特に法律相談等への期待というのも多くなっております。総じまして、新しく社会の中に参加する道具だてとしての情報提供という意味での期待というのが大きくなっているかと思います。","id":"exchange-047"},{"speaker":"中島委員","kind":"提案","question":"午前中も質問が出ておりましたが、このケーブルテレビの開局にあたっては、公明党もさまざまな先駆的な提案をしてまいりました。そして、平成８年の開局以来、地域のメディアとして、先ほども加入率が６０％を超えたと、このように伺いましたとの意見を述べました。","respondent":"中尾根企画部長","answer":"特に、大きな道路を隔てたり、線路をまたぐという場合に、関係のところの了解がなかなか取れない状況というのが横たわってあります。部分的には電波で飛ばしてもというところまで研究を進めてきておりますけれども、こういう状態をつくり上げるというのが使命かと考えています。","id":"exchange-048"},{"speaker":"中島委員","kind":"質問","question":"困難エリアというのは、同じ区民でありながら加入条件とか負担割合に不公平が生じているという、この現状は一刻も早く解消すべきと思います。個人宅への敷設への負担軽減、こうしたものを区として援助はできないものなのか、このことをお伺いしたいと思います。","respondent":"中尾根企画部長","answer":"例えばキャンペーン期間をやったり、ないしは減額の期間を設けたり、サービス期間を設けたりというようなことで対応してきてもらっています。ただし、各戸１万円ですけれども加入の援助をしていると、あとは基本的に会社と行政との関係の中で支援をしてきてあります。","id":"exchange-049"},{"speaker":"中島委員","kind":"質問・要望","question":"今、１万円の援助があると伺ったんですが、そんなものでは到底追いつかない金額を負担しなければ引けないという地域もあります。一定の期間限定を設け、区が補助金を出して火災報知機の設置を実施してはいかがでしょうか、ご所見をお伺いいたします。","respondent":"太川区民生活事業部長","answer":"ただ、今、委員のほうで設置助成をですけれども、現在私どものほうといたしましては設置については考えてございません。今後、それから区のほうで住宅防火推進協議会をつくってありますので、その中で十分わかりやすい啓発等について協議してまいりたいと思ってあります。","id":"exchange-050"},{"speaker":"中島委員","kind":"質問・要望","question":"どちらかと言えば賛成を含めて６６.９％、このように高い数字を示しております。ぜひ、区長の英断を期待したいと思いますので、ご検討をいただくことをことを要望して、最後に一言区長からお言葉をほしいと求めました。","respondent":"太川区民生活事業部長","answer":"今、お話しがございましたけれども、障害者、それからひとり暮らしの高齢者のお宅には火災警報機はつけてありますので、その辺のところをご理解いただきまして、あとは区民の方にはつけていただけるよう、啓発のほうに努力してまいりたいと思ってあります。","id":"exchange-051"},{"speaker":"中島委員","kind":"質問・要望","question":"急にここで区長の英断をと言っても無理と思います。でも、お心の中にしっかりとどめていただきたいと思いまして、ここで要望して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問・要望","question":"値上げ中止を求めて、質問していきたいと思います。区はどういうふうに受けとめて、どういうふうにしようとしているのか、初めに伺いたいと思います。","respondent":"小沼福祉事業部長","answer":"安心して産み育てられるというようなところが大きなところでの柱というふうに、私どもはそれを主軸に据えて、個々の施策に取り組んです。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問","question":"今、では実際に保育料がどういう内容で引き上げられるのか、その内容を伺いたいと思います。保護者１世帯当たりが幾ら値上げになるのか、この点も併せて伺いたいと思います。","respondent":"小沼福祉事業部長","answer":"これを１日当たりに直しますと１,１００円、１,３３０円、１,２３０円という形での相差が出ようかというふうに考えてあります。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問・要望","question":"区のほうは、国の徴収基準額４７％を６０％に引き上げることを目標にしているというふうにおっしゃいました。この点ではどういうふうに６０％まで持っていくというふうに考えておられるのか、そのスケジュール等があったらお聞かせいただきたい。","respondent":"小沼福祉事業部長","answer":"実額ベースで見ますと９.２％、国の徴収基準４７％をベースに考えますと、改定後は確か５１％程度になる数字的な状況です。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問","question":"それと、２７％にすると、現在から全体で幾らの負担が増えるのか、そこのところを併せて伺いたい。それと併せて、このＤ１０階層ですけれども、試算をしていたらこの階層がどういうふうに現在から増えるのか、この点も併せてお伺いしたいと思います。","respondent":"小沼福祉事業部長","answer":"したがいまして、これが２７％上げたときどうかということについては、ここでては差し控えさせていただければと思います。Ｄ１０階層ですが、Ｄ１０階層の３歳児の場合でしたら４万６,８００円ほどのご負担をお願いするようになるということを申し上げているところです。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうすると、今回の９.２％というのは、どういうことなんでしょうか。全体６０％まで持っていく、その６０％に持っていく中での９.２％というのはどういう意味なのか、教えてほしいと求めました。","respondent":"小沼福祉事業部長","answer":"それを具体的にいつに、次年度以降どうするのか、あるいは次の年度はどうするのかということで申し上げているものではございません。これは私ども実額にして９.２％、徴収基準で見ますと５１％というものを今回審査の中でお願いして、こういうものです。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"この保育料の値上げの中身と、全体の影響はどういうふうになるのか、この点をお伺いしたいというふうに思います。そして、実際に夜間保育の利用が大体２５％ぐらい、平均十五、六日利用されているというふうに伺いますけれども、これが実際そうなのかどうか。","respondent":"小沼福祉事業部長","answer":"現行１,９００円が４,０００円になってまいりますので、これは月額ですけれども負担増というようなところに数字的にはなろうかと思います。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"私は実際にどういうふうな影響になるのかと、どういう影響なのか、具体的に先ほどＤ１０階層の３歳児というふうに言いました。夜間１時間使った場合に、実際に幾ら今までと変わるのかというところを、もう一度お伺いしたいと思います。","respondent":"小沼福祉事業部長","answer":"ですから、年当たりに直しますと４万６,８００円、平成１６年度ベースで見ますと、そういう状況になってまいります。１日当たりにすると一番わかりやすいかなと思いますけれども、２３０円ほどの負担増という、数字的には出るです。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"そのかわりに新たな税源委譲として、そうすると差し引き１億１,７００万円の財源が単純計算でいって減ってくるということでいいのかどうなのか。もう一つ、三位一体の改革が今回の保育料の値上げにどういうふうに影響しているのか、改めて伺いたいと思います。","respondent":"市岡企画財政課長","answer":"これは再三ご説明しているとおり、これ以上に例えば介護保険の事務費交付金の削減が予定されているとか、これ以外の要素がまだあります。それから、これも款別でご説明申し上げましたが、三位一体改革と保育料の改定問題は全く理論的にも実態的にも関係はございません。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうすると、区の直接の財政がどうなのかということなんですけれども、今回の予算案でも１４億円あまり積み立てがされております。区民に保育料値上げで負担を押しつけるというのは筋が通らないんではないかと思いますけれども、その辺の考え方をお聞かせほしいと求めました。","respondent":"市岡企画財政課長","answer":"マイナスに転じたというご説明をさせていただきましたが、適正な負担のあり方ということを私どもも含めて考えていただく。これが多くの区民の方に支持される、そういうご議論のあり方ではないかというふうに考えてご提案申し上げているところです。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"質問・要望","question":"２人目の子どもを授かるのを躊躇してしまったり、あきらめる人が増えるんではないでしょうか」と、こういうふうに言っております。この調査では、そしてこの結果をこの予算にどういうふうに反映したのか、特に保育料ではどういうふうに考えたのかお聞かせほしいと求めました。","respondent":"中尾根企画部長","answer":"したがいまして、こういう切り口から子育て支援というのは、当区においても考えているものです。区としても新しい援助を考えたわけですが、この考え方と先ほどから言われておりますように、経済的な支援策の子育ての切り口は別の切り口なんです。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ここには区民の要望と区の考え方には全くずれがあるというふうに思うんですけれども、そこのところはどういうふうにお考えなのか。この調査結果を受けているわけですから、実際に保育園を利用されている父母の方々にどういう影響があるのか、このところはどうか尋ねました。","respondent":"中尾根企画部長、小沼福祉事業部長","answer":"働くことだと、それから経済的支援ということですから、そのことは踏まえていると。にも係わらず、その上で区が最も基軸としているのはストックだと、このように答弁したつもりですので、よろしくお願いします。 これは大変大切なことだと思いますので、一言申し上げておきます。出生率が回復した先進国がそういうような状況ですので、ひとつそういう点もご賢察の上、ご理解のほどをお願いできればと思います。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それなら、改定してから調査するんですか、そこのところをお聞かせほしいと求めました。今の景気対策、景気状況だとか、区民の暮らし、この点からも併せて伺いたいと思います。","respondent":"小沼福祉事業部長","answer":"保育料がゼロ、もしくは低額というようなご意見をおっしゃられる方というのは、ちょっと私には理解できないと。それから、これは確か説明した３月の条例改正のときに保育課長からお話し申し上げたんですが、説明の中で申し上げたというふうに記憶しています。","id":"exchange-064"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうは言っても一律に９％の値上げですから、それを理由にして、保育料そのものを引き上げるという理由にはならないと思います。受益者負担という考え方というのは、改めて保育あるいは区政全体でどういうふうに考えているのかお伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"これは予算のご説明でも申しましたが、サービスの受け手である保護者の方に、やはり現在のまだまだ厳しい景気の影響を受けて大変ご苦労されている。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、そもそも国の徴収基準額ということはどうなんだというふうに思うんですけれども、この点はどうでしょうか。ですから、一貫しないんじゃないかというふうに思いますが、どうか尋ねました。","respondent":"市岡企画財政課長","answer":"これがもし委員おっしゃられるように、現実に今品川区では国に対して値上げした後でも５１％、その点もよろしくご理解をいただきたいと思います。適正な負担ということを区民全体のコンセンサスの中で進めていく、こういう必要のある施策であると、このように理解しています。","id":"exchange-066"},{"speaker":"宮崎委員","kind":"質問","question":"これは単純に利用している人なのかというふうに言うと、それでは国が今進めている少子化対策は何なのかということになるんですよ。この点で、どういうふうにお考えか尋ねました。","respondent":"市岡企画財政課長","answer":"保育については、品川区はまさに国の施策を超えた形でいろいろ新しい子育ての支援策をやっているところでございまして、国は関係ございません。私どももいろいろ説明責任を果たしてまいりたいと、こういうことを申し上げているわけです。","id":"exchange-067"},{"speaker":"宮崎委員","kind":"質問・要望","question":"少子化社会対策基本法に基づいてやっていると思うんですけれども、この理念、そしてこの基本法は自治体に対して何を求めているのか。そしてもう一つ、どうしろと言っているのか、その基本法をどういうふうに受けとめているのか伺いたいと思います。","respondent":"小沼福祉事業部長","answer":"少子化社会対策基本法と次世代育成支援推進法、子育て分野の中で三位一体ではございませんけれども、三者補完の法律と言われてあります。理想的な子育てをできるような社会をつくり上げていこうと、これが基本的なスタンスであるというふうに、私のほうは認識しています。","id":"exchange-068"},{"speaker":"宮崎委員","kind":"質問","question":"第１６条には、こういうふうに書いてあります。この認識と今の答弁では、全くまたこれもずれがあるというふうに思いますが、いかがか尋ねました。","respondent":"高橋区長","answer":"先ほどから国、国というようなお話が出ておりますが、それではうちの保育も国基準によって実施をしてよろしいでございましょうか。したがいまして、今までずっと説明したことを、よくよく理解をしていただかないと、今回の話はかみ合いません。","id":"exchange-069"},{"speaker":"宮崎委員","kind":"意見","question":"この負担軽減は必要だと、そして区自身がやった調査でも負担を軽減してほしいというふうに言っているわけですよ。仕事をやめて子育て専念となると、その方と働きながら子育てして税金を納める、この違いというのはどういうふうに認識をされておりますかとの意見を述べました。","respondent":"高橋区長","answer":"まだ国基準の６０％まで行っていないんですよと、こういうことを説明としてやらせていただいております。議会で決まりましたら、私のほうで特集を組ませていただきまして、区民のほうに十分に周知をしてまいりたいと思っています。","id":"exchange-070"},{"speaker":"宮崎委員","kind":"提案","question":"新規の事業を提案して、そうすると今回福祉事業部としては、すこやか医療助成など幾つかの事業をやっております。そういう中で、保育料と新規事業との関係、いわゆる資金のやりくりというのはどういうふうにやられてきたのか、お伺いしたいと思いますとの意見を述べました。","respondent":"市岡企画財政課長","answer":"委員のご指摘のとおり、今回の予算の大きな柱は、子育て支援です。この子育て支援というのは、もう経常的な事業ではありませんので、こういうことです。","id":"exchange-071"},{"speaker":"宮崎委員","kind":"質問","question":"あらゆるというのは、一体何なんでしょうか。こういうところに基金の新たな積み増しを減らしてでも負担をなくすということが必要ではないかと思うんですけれども、そこのところはどうか尋ねました。","respondent":"市岡企画財政課長","answer":"例えば子育て支援の関係では、今回いろいろ新しく出した生活支援型保育とか、それから財源対策をしたりして一般財源を投入しております。","id":"exchange-072"},{"speaker":"宮崎委員","kind":"質問・要望","question":"「基金の使い方をどうするのかという」質問に対して、区長は「今後は消費的でないソフトの面で考えていきたい」というふうに答弁しております。最後になりますが、今回の値上げはやっぱり見直して、中止するように強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"本間委員","kind":"確認","question":"この質問につきましては、昨年第３回定例本会議並びに本年２月の第１回定例本会議の代表質問の経過を踏まえ、もう一度確認の意味を含めお伺いします。どうか、地域の発展に貢献できるよう何らかの支援を仰ぐことはできないものでしょうか、お尋ねいたします。","respondent":"新美保健高齢事業部長","answer":"あるいは痴呆性高齢者の増加等への対応をするために、地域の方々に利用していただくような在宅介護支援のための施設を整備する方向で検討をし。","id":"exchange-074"},{"speaker":"本間委員","kind":"意見","question":"「安心できる施設ができるといいね」などと、高齢者の方々が心待ちにいたしております。どうか、区長をはじめ関係者のご努力を見守っていきたいと思いますが、この点についてご見解やご決意がありましたらお知らせくださいとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"先ほども申し上げましたように、高齢者、特に後期高齢者がこれからも増加をしてまいります。そういった意味では、地域にきめ細かな在宅支援のための基盤整備は、そのための用地として取得に向けて粘り強く交渉をしてまいりたいと思います。","id":"exchange-075"},{"speaker":"本間委員","kind":"質問・要望","question":"その他書道や大工職人の技術などを生かした、さまざまなよい仕事をこなすことができるとしての評判を地域で伺っております。教育研修を行い、適切な仕事へのマッチングを効果的に進められているとのことでありますが、この点についてどのようにお考えかお尋ねします。","respondent":"新美保健高齢事業部長","answer":"サポしながわはお尋ねにありましたようにシルバー人材センターと社会福祉協議会の連携体制のもとで、平成１４年度に開設をしたものです。","id":"exchange-076"},{"speaker":"本間委員","kind":"質問","question":"就職先の開拓につきましては、あきらめかけている地域の中小企業へ再就職できるようなシステムの構築について、どのようにお考えかお尋ねします。この件について、地域の中小企業への再就職のシステム構築について、お考えをお伺いいたします。","respondent":"新美保健高齢事業部長","answer":"とりわけ地元の中小企業への再就職支援システムですが、区内の産業関係の団体に直接サポしながわのＰＲをさせていただき周知に努めてまいりました。さらに、当然そういう情報も活用するという形で、求人先開拓と地域へのつなぎの仕組みづくりに努めているところです。","id":"exchange-077"},{"speaker":"本間委員","kind":"質問・要望","question":"今回の質問では、さらに違った視点から何点かお伺いしたいと思いますので、よろしくお願いします。保育園は保育士の資格と、現場において立場や資格の違いによって生じる具体的な問題点や課題などはないのでしょうか、この点についてお尋ねします。","respondent":"本間総務部長、古川教育次長","answer":"幼稚園教諭につきましては、２３区合同で採用選考を行い、合格者の中から区の教育委員会が面接を行い採用を決定しているという違いがあります。幼稚園の教諭につきましては、区立幼稚園の間での異動ということになってあります。ただいま総務部長からご説明申し上げましたけれども、併せて幼稚園教諭の資格を持っていると、この二つの資格を持っている者を配置をしています。","id":"exchange-078"},{"speaker":"本間委員","kind":"質問・要望","question":"所管の窓口は、どこが責任を持ってあたることになるのでしょうか。それぞれが持つメリットとデメリットについては、どのようにお考えでしょうか、その点についてお伺いいたします。","respondent":"小沼福祉事業部長","answer":"０・１・２歳ということで、慣れているという視点で、子どもを就学前まで見れるのが保育園型の就学前教育施設の一つの大きな特徴と言われてあります。やはり、現場の職員はそれだけの力がありますので、大きな意味でのデメリットはないと私自身は考えてあります。","id":"exchange-079"},{"speaker":"本間委員","kind":"質問・要望","question":"一つ、その学校のご苦労を察するのでありますが、いわゆる残された学校の保護者や地域での説明会や周知はどのようになされているのでしょうか。これまでの学童保育クラブとくらべてどのような点で違いがあり、どのような点が評価され人気が出ているとお考えでしょうか示すよう求めました。","respondent":"古川教育次長","answer":"できるだけ私どもは早く１校でもということで、平成１２年度当初は１２校あるいは１０校というような実施計画上の数字を持ってございましたけれども。説明会におきましても保護者の方々にご理解をいただきながら、もう少しお待ちくださいと、こういうことで進めているところです。","id":"exchange-080"},{"speaker":"本間委員","kind":"質問","question":"不利益をこうむるのではないかなどの苦情はどのように把握されているのでしょうか、まだ実際にはないのでしょうか。地域での指導員やボランティアの皆さんの人的供給については、どのようになっていますか、可能な範囲で示すよう求めました。","respondent":"古川教育次長","answer":"説明会におきましても、そういう中で自分の子どもの、特に４年生以上ですね。ボランティアにより多くの方々に参画していただけるように、そういう仕組みもこれから考えていきたいと、このように思ってあります。","id":"exchange-081"},{"speaker":"本間委員","kind":"質問・要望","question":"引き続き今後閉鎖される施設の有効利用につきましては、どのようにお考えでしょうか。これまでの地域の利用の実績などを勘案するなど、利用の方向性についてはどのようにお考えでしょうか、お尋ねいたします。","respondent":"中尾根企画部長","answer":"子育ての施策ということを重点に検討はしますが、幅広く検討してふさわしいものに使っていきたいと、こういう３段階の検討内容となっています。平成１７年度以降については、先ほど言いましたような基準に従って、もう一度どのように使っていくか検討する予定になってあります。","id":"exchange-082"},{"speaker":"本間委員","kind":"質問・要望","question":"対応をしていくことの必要性、重要性や認識についてはどのようにお考えでしょうか、そのご見解をお伺いいたします。役割を担う方への事前の教育研修はどのようにお考えになっているのか尋ねました。","respondent":"太川区民生活事業部長","answer":"基本的には防犯ということで、安心・安全のまちの部分でも、防犯を主たる業務として対応してまいりたいというふうに考えてあります。","id":"exchange-083"},{"speaker":"本間委員","kind":"質問","question":"そこで、お伺いします。先ほどの部分と重なるわけですけれども、最後に町会・自治会の数に比べて１００人という人員は、この件についてのご見解をお尋ねしたいと思います。","respondent":"太川区民生活事業部長","answer":"そういう意味からいいますと１００名というのは、既に自主的に防犯活動に取り組んでいる方とか、それから事業所の場合もあろうかと思います。","id":"exchange-084","title":"町会・自治会支援"},{"speaker":"本間委員","kind":"質問・要望","question":"そのとき集まった人数は６０名を超える規模で、大変皆さん感激をしていただきました。これからも実際に地域の人たちに、案内などをして啓蒙してほしいと求めましたが、この点についてのお考えはいかがか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"周知に努めているところですが、ＰＲはますます必要ですので、努めてまいりたいと考えています。都のほうでもさらに周知、ＰＲに努めていただくよう提案をしてまいりたいと、このように考えてあります。","id":"exchange-085"},{"speaker":"本間委員","kind":"質問","question":"周辺の地域住民の意向調査について、どのように行っていくのかお伺いします。最後に、下水道の計画は東京都が立案するということはわかっておりますけれども、品川区としてのこの件についてのご見解があればお尋ねいたします。","respondent":"中谷まちづくり事業部長","answer":"まず区としては２０年台に入りましてぐらいから、このように考えてありますので、ご理解いただきたいと存じます。区民の安全という観点から、区としては一番必要なのかなというふうに考えておりますので、ご理解のほどをお願いしたいと思います。","id":"exchange-086"},{"speaker":"西本委員","kind":"提案","question":"自ら参画提案し、区民による区民のための政策の展開になるための影武者として、行政の質や求められる人材とはどういうものであるのかという点です。","respondent":"中尾根企画部長","answer":"これを行政としてバックアップしていこうと、これがコミュニティづくりの基本と、こういうものの考え方で進めてきてあります。もう１点は、地域の充実に努めていきたいと、このように考えているところです。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"地域振興ですから、また町会長、また町会長というようなことになってしまうんではないかなという危惧があります。これはどういう意味なのか、それを全区的にどういうふうにしていくのか、そのところのご見解をお聞きしたいと思います。","respondent":"太川区民生活事業部長、小沼福祉事業部長","answer":"そうしませんと、なかなかもう一歩先に地域の活動というのは進んでいきにくくなってきているのかなということは、十分私どもも認識しています。そういうふうに考えてありますので、その点につきまして… それから子育て支援というような社会的な機運の高まり、福祉事業部の中に、将来構想を含めて改革の検討委員会というようなものを設定しています。","id":"exchange-088","title":"町会・自治会支援"},{"speaker":"西本委員","kind":"質問","question":"そのコミュニティをしていくために、事業部支援プロジェクトというのがあります。この辺はどういうふうにされていくのか、平成１６年度はどこまで目標という形で計画をされているのか、ご所見をお伺いしたいと思います。","respondent":"中尾根企画部長","answer":"１３基盤、地域を舞台に活動していただく、こういう仕組みづくりを考えているところです。そのための仕組みをつくるというところから出発させていきたいと、このように考えてあります。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"地域センターであるとか、保育園等々でもありますけれども、その施設長のあり方をどう考えていくのか、育成をどういうふうにしていくのか。これから求められている施設長の姿、どういうふうにお考えになっていられるのか、ご所見をお伺いいたします。","respondent":"本間総務部長","answer":"このような施設長につきましては、継続的な研修を実施して、施設長のあり方などについて、その育成に努めているです。事業部に極力権限を委譲するように進めてきたところですが、ご指摘のとおり今後はその事業部の中で、このように認識しています。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"要望、いろいろあるかと思いますが、そこをどういうふうにマネージメントしていくのか。その中で仕事の分析というものをどういうふうにされているのか、経営者としての考え方を今後どうされていくのかということをお聞きしたいと思います。","respondent":"小沼福祉事業部長","answer":"それぞれに分野分野で検討して技法あるいは技能というのを、切磋琢磨しているというところに着手し始めているということがあります。円滑にそれから的確な時代要請にこたえられるような保育園へと、一層舵を取って進めてまいりたいと、このように考えてあります。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"今、いろいろなところで育成に力を注いでいるというふうにお聞きいたしましたが、どのぐらい考えているのか。子どもたちは１０年も２０年も待つわけにいきませんし、それを視野に入れた形で、その辺についてお伺いいたします。","respondent":"本間総務部長","answer":"人材の育成といいますのは、区民サービス向上のためには必要不可欠のものですので、今後時代に合った職員の育成には継続して努めていくです。継続性という点からも、地域と信頼関係を築き地域と連携して進めていくのが、かように考えているところです。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"今、改革の時期になりますので、期待されるところが多分にありますし、継続的にそれは今後も行っていただきたいという思いは強くあります。その中で、もっと広い意味での人材活用というところに着手をする、将来にわたっての考え方をもう一度お聞きしたいと思います。","respondent":"本間総務部長","answer":"今、現在ご案内のとおり、公務員制度もいろいろな勤務の形態等が考え出されようとしています。今、ご指摘の点については今後十分検討していきたいと、かよう考えているところです。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"このように広い用地を取得した経緯と、それから計画づくりについてお伺いしたいと思います。これだけの資金をかけて、品川区において財政的な負担はどうなのだろうかというところを、ますお聞きしたいと思います。","respondent":"市岡企画財政課長、中谷まちづくり事業部長","answer":"これもいろいろな検討があったんですが、都市計画公園でしかも２haを超えますと、こういう非常にいい仕組みがあります。何とかここへ持っていきたいと思って、いろいろ検討いたしまして… こちらの防災センターと連携を図り、中には非常用のトイレ等も装備している、あるいは非常用の備蓄倉庫等も装備しています。それから、これはできた後のことですが、芝生の管理では大分苦労いたしました。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"理想的な天然芝で始めたところも、今は雑草も育成しないという状態にまで使われているという状態であるというふうにお聞きしています。それからこれからグラウンド等の使用方法について、どういうふうに考えられているのか、その辺をお聞きしたいと思います。","respondent":"中谷まちづくり事業部長","answer":"天然芝を人工芝に変えても、この申込方法等については、従来どおりの方法で運営を管理していきたいというふうに考えております。９０％程度の利用率ですので、こういう区民の皆さんの高い利用状況を考慮しながら、適切な運営管理を図っていきたいというふうに考えております。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"これからもたくさんの区民の方たちに使っていただきますようにということで、お願いしたいところです。維持管理についてお聞きしたいと思うんですが、もともとしながわ中央公園は、その辺の今後の維持管理についての考え方についてはいかがか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"公園の計画段階から、区民の皆さんにボランティアとして公園管理にも携わっていただきたいということを呼びかけてまいりました。今進めている事業を本格的に進めるということになっておりますので、区としてはこの中でしながわ中央公園についても、このように考えております。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひともいい関係をつくって素晴らしい公園の維持をしていただきたいなということで、私の総括質疑を終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"三村委員","kind":"質問","question":"今後、移動が困難な人が増加していくのではと想定されますが、品川区には現在移動困難者は何人ぐらいいると認識されていますでしょうか。今後の状況については、どのように推測をされているのかお伺いをいたします。","respondent":"新美保健高齢事業部長","answer":"移動が困難な方の数の把握と今後の見込みについてのご質問ですが、障害者、それぞれ要介護認定あるいは障害者手帳を取得時の判定等がありますので。とりわけ７５歳以上の後期高齢者の増加が見込まれておりますので、移動困難者の数も増加していくというふうに考えております。","id":"exchange-098"},{"speaker":"三村委員","kind":"質問・要望","question":"絵画の観賞など、また人との出会いやつき合いといった、人間生活に潤いをもたらす生活の質そのものを高めていくことも求められていると思います。だれもが自由に移動できる環境整備が、今後ますます重要になってくると考えますけれども、品川区のご所見をお伺いいたします。","respondent":"新美保健高齢事業部長","answer":"だれもが自由に移動ができる環境整備についての区の考え方ですが、品川区は昭和５０年代から、福祉のまちづくりを進めてまいりました。ご質問の生活の質の確保向上、外へ出るあるいはまちの中を移動する、そういう移動の確保が大変重要であることは十分認識をしております。","id":"exchange-099"},{"speaker":"三村委員","kind":"質問・要望","question":"その手助けを行政側としてぜひ行ってほしいと求めました。住民の力が発揮できるような環境づくりを、今後整えてほしいと求めましたけれども、お考えをお聞きしたいと思います。","respondent":"新美保健高齢事業部長","answer":"当然移送サービスの充実が求められるという認識を持っておりますし、その際、住民の方のボランティアとしての力を生かす方法で。継続的なサービスを提供していきたいというような方々がいらっしゃれば、相談をきめ細かく継続的に行う機能を今後も充実してまいりますので。","id":"exchange-100"},{"speaker":"三村委員","kind":"質問","question":"トラブルの発生が予想されますが、行政として予想されるトラブルとはどのようなものがあるのでしょうか。品川区としてはどのように対処されようとしているのか、お伺いをいたします。","respondent":"中谷まちづくり事業部長","answer":"あるいはそれに起因する二次的な問題、あとは工事上の問題等、生活上あるいは環境上の問題と四つぐらいに多く分かれるかと思います。区ではこれらに対処するために、環境開発指導要綱で建築紛争の予防の条例、あるいはワンルームマンションの指針などを設けまして指導しています。","id":"exchange-101"},{"speaker":"三村委員","kind":"質問","question":"千代田区では地区計画によるマンション規制条例と建築紛争を未然に防ぐ対策としての条例制定に取り組んでいます。今後、品川区でも建築紛争を未然に防ぐという観点から、どのような取り組みが可能であると考えているのか、ご所見をお伺いいたします。","respondent":"中谷まちづくり事業部長","answer":"あるいは、昭和５３年から開発指導要綱を設けるなど、かなり先駆的に取り組んでまいり、一定の効果も上げてきたということがあります。ただ、そしてまちの将来目指すべき方向を示し、そしてそれらに向けての地域の合意形成というものが前提となるというものです。","id":"exchange-102"},{"speaker":"三村委員","kind":"質問・要望","question":"以前より品川生活者ネットワークでは、市街地整備基本方針による地域ごとの説明会の実施を要望してまいりました。建築紛争の未然防止の観点からも、説明会の実施をぜひ実行していただければと要望いたしますが、お考えを、示すよう求めました。","respondent":"中谷まちづくり事業部長","answer":"この市街地整備基本方針は、品川区の将来の望ましい都市像を求めるということで、平成 １３年３月に策定したものです。区としては説明会を開くということではなくて、こういうような形でまちづくりを進めていきたいと、このように考えているところです。","id":"exchange-103"},{"speaker":"三村委員","kind":"質問・要望","question":"２階建ての住宅地に突然９階建てのマンションが建設されたりといったことが、ぜひ区のほうとしても積極的な働きかけを行ってほしいと求めました。現在進められている地区計画の状況、そして今後品川区で地区計画策定をどのように取り組まれていくのか、お伺いをいたします。","respondent":"中谷まちづくり事業部長","answer":"例えば、かつてはかなり区が入り込んでご説明しましたけれども、なかなか地域の皆さんは身近なものとして感じていただけないという状況があります。そういう地域ごとに合った計画ができるよう、区としても今後とも努めていきたいと、このように考えております。","id":"exchange-104"},{"speaker":"三村委員","kind":"質問","question":"次に、特別職報酬等審議会についてお伺いをいたします。今回、品川区では据え置きという決定に至った経緯についてお伺いをいたします。","respondent":"本間総務部長","answer":"特に他の２２区の現況や一般職の給与改定の状況等を十分勘案し、なおかつ区の行財政の事情等も考慮しながら慎重に検討を進めました。退職金を受け取らないという、まれなケースである長の退職金辞退という理由は品川区の場合は何らないと、このように考えているところです。","id":"exchange-105"},{"speaker":"三村委員","kind":"質問・要望","question":"区長自身が自らの姿勢を正すということで、今後についてはぜひもう一歩踏み込んだ判断をしていただきたいなと、要望をいたします。抽選をして制限を加えるなどという対応を行わず、きちんと区民に公開するよう求めますが、教育長のお考えを説明するよう求めました。","respondent":"古川教育次長","answer":"一般的には委員会室を使いながら実施しているのが通例でございまして、一般的には委員会室を使っているというような実態があります。さまざまなご意見あろうかと思いますが、そういう中で抽選によって多くの方がお見えになった場合には、１０名ということで実施しているものです。","id":"exchange-106"},{"speaker":"三村委員","kind":"質問","question":"意思形成過程が非公開となる改正が行われた理由をお聞きいたします。非公開の対象となる意思形成過程とは、具体的にはどういう内容になるのかお伺いをいたします。","respondent":"古川教育次長","answer":"検討、調査等の構成で、適正な執行に支障を来すおそれがある場合もあろうかと思ってあります。５名で構成されている教育委員会、５名の教育委員会の中で行われていると、こういうことです。","id":"exchange-107"},{"speaker":"三村委員","kind":"質問・要望","question":"可能な限りにおいて非公開という措置は取らないよう、ぜひ要望をいたしたいと思います。意思形成過程を非公開とするのであれば、最低限、決定後、議事録を公開することが必要かと考えますけれども、お考えを説明するよう求めました。","respondent":"古川教育次長","answer":"もう１点でありますけれども、非公開の会議における議事録等についての公開ということであります。当然情報公開条例の規定に基づきながら、それぞれの案件ごとに公開の可否を決定すると、このように考えております。","id":"exchange-108"},{"speaker":"三村委員","kind":"質問","question":"混乱が予想されるというものであれば、決定した後に公開される可能性が高いかと思いますけれども、それについてもう一度お聞きしたいんでけれども。非公開の内容については、そういう理由で非公開となったものに関しては、原則としては公開されるということでよろしいのか尋ねました。","respondent":"中尾根企画部長","answer":"先ほど言いましたような意思形成過程のことについては、基本的には時限秘という扱いというですので、ある一定の時期が必要だと。教育委員会自らが持っている規則の中での運用で適用しているということですので、判断が教育委員会サイドとなります。","id":"exchange-109"},{"speaker":"三村委員","kind":"質問","question":"では、教育委員会において、時限秘の期間というのは、大体どの程度を想定されているのか尋ねました。","respondent":"古川教育次長","answer":"会議体の公開、非公開は、それは会議規則にのっとって実施しております。それ以上のことについては、差し控えします。","id":"exchange-110"},{"speaker":"三村委員","kind":"質問・要望","question":"情報公開請求と会議の非公開のものについても、ぜひ情報公開の対象となるような判断をしていただければと、要望をします。情報を隠すのではなく、ぜひ教育委員会のほうに望むんですけれども、教育委員会の考えをお聞かせ願いたいと思います。","respondent":"古川教育次長","answer":"これは会議規則そのものの中で、それぞれの対応というのはあるわけでして、それにのっとった適正に処理をされているというふうに思ってあります。ただいまの委員のご意見については、参考とします。","id":"exchange-111"}]},{"id":"topic-02","title":"を終わります。 これをもって、総括質疑を終了いたします。 以上で、平成１６年度品川区各会計予算についての質疑は、すべて終了いたしました。 次に、第５号議案…","agenda":"を終わります。 これをもって、総括質疑を終了いたします。 以上で、平成１６年度品川区各会計予算についての質疑は、すべて終了いたしました。 次に、第５号議案…","exchanges":[{"speaker":"沢田委員","kind":"提案","question":"共産党、公式な調査としてはふさわしくなく、どうしても必要とするなら各会派に支給されている政務調査費を充てるべきと考え提案するものです。以上で、第５号議案、平成１６年度品川区一般会計予算案に対する修正提案にあたっての説明としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"塚本委員","kind":"質問","question":"１点だけお伺いします。ほかに修正すべき点はないのか、せっかくこれだけ努力したんですから、それでよろしゅうありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"沢田委員","kind":"提案","question":"ただ、我々は今回は条例提案をしたことに絞って提案をしておりますけれども、だんだんこれを広げていきたい。今回は、そういうことで二つの条例提案に沿った財源の裏打ちだということを、ご理解いただけると幸いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"提案","question":"同用地特別会計予算および共産党単独提案、平成１６年度品川区一般会計予算修正案についての、我が会派の意見を表明いたします。区議会第一党自由民主党品川区議団との連携を深めていただくことを要望し、共産党単独提案、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"},{"speaker":"三上委員","kind":"提案","question":"さらに、平成１５年３月にも、介護保険関連で予算修正を提案し、このときは減債基金繰入を財源としました。一体、財源論議を共産党はどう考えているか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"},{"speaker":"南委員","kind":"提案","question":"延長夜間保育料の値上げも加えると経済的負担は深刻ですから、中止をするべきです。すまいるスクールには１名のみ、しかも専用室もおやつもないのですからサービス向上とは言えませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-117"},{"speaker":"土井委員","kind":"提案","question":"今後の事業でこのようなことがないよう、事前の万全な検討を要望します。品川区民連合の各委員が提案、要望した事項を前向きに受けとめられ、我々もチェックと評価に汗をかくことを誓いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"藤原委員","kind":"質問・要望","question":"我が会派は平成１６年度一般会計、次の意見、要望を付して賛成いたします。以上、意見と要望を述べ、意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"井上委員","kind":"提案","question":"介護保険特別会計、用地特別会計の各平成１６年度予算に対し、意見と要望を以下に述べ賛成いたします。公立の学校で行う教育環境を整えるという意味では、教育委員会に市民と合意のもとに学校適性規模を検討することが求められていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/906948?Template=document&Id=834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":136599,"voices":276}},{"id":"h16-20040408-6","meetingId":"h16-cm04","date":"2004年4月8日","dateIso":"2004-04-08","committee":"区民委員会","time":"午後１時２８分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"これより幹部職員の異動および所管事項の変更","agenda":"これより幹部職員の異動および所管事項の変更","exchanges":[{"speaker":"松澤委員","kind":"意見","question":"２４万円から２２万円ということですけれども、これは現在、均等割の非課税限度額とおっしゃる、この２４万円の範囲で非課税になっている方は何人ぐらいいて、今度２２万円にすることによって、その数字がどう動くのか、お教え願いたいと思いますとの意見を述べました。","respondent":"太田税務課長","answer":"まだシミュレーションを平成１６年度はできてございませんけれども、平成１５年度の出たものでシミュレーションをしますと、対象８２名です。金額でいたしますと、所得割と均等割を含めまして２９万７,２００円の区としては増収になるという、こういう数字になっております。","id":"exchange-001"},{"speaker":"三村委員","kind":"質問・要望","question":"よくわからないので教えていただきたいんですけれども、こういう地方税法や何かの改正をする場合、イコールで改正をしなきゃいけないのか、区として独自の判断ができるものなのか、その辺のことをちょっと教えていただけますか。","respondent":"太田税務課長","answer":"区税条例上、地方税法の加算額を引用していますので、均等割についても基本的には地方税法の考え方に基づいて今回改定をするです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"この８２名というのは、この平成１５年度ベースで考えたときに８２名がという、もう一度教えていただけないか尋ねました。","respondent":"太田税務課長","answer":"要するに、平成１５年度ベースでやると８２名の方が非課税から課税になるという、そういうことです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"こういう不況の時代ですから、法律が変わることによって、こういう事態になったということですよね。だから、区としてその辺の見解というのは、どういうふうに感じていらっしゃるのか、ちょっと改めて伺いたいと思います。","respondent":"太田税務課長","answer":"先ほどもご説明申し上げましたけれども、今回につきましては、従来からいわゆる低所得者の方の税負担について配慮してきているわけです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"そういう法改正の中で、新たな増収がどのくらいというふうに伺ったら２９万円ということですから、率直にそういうふうに感じます。そういう方向で政治を求めて進めていかなきゃいけないんじゃないかなというふうに思いますので、今回のこの条例改正については、賛成はできません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663620?Template=document&Id=2386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":5396,"voices":35}},{"id":"h16-20040408-5","meetingId":"h16-cm04","date":"2004年4月8日","dateIso":"2004-04-08","committee":"総務委員会","time":"午後１時２６分～午後７時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"制限付き一般競争入札ということですけれども、前にもちょっとお伺いしたかもしれないんですけれども、どのような制限があるのかを教えてほしいと求めました。","respondent":"鷹倉経理課長","answer":"そして、空調も５,０００万円、あとの内容はほぼ同じです。台場小学校、荏原第五中学校についても、ほぼ同じような形で条件を付けた形で一般競争入札をしていただいているです。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"全体で見ますと、例えば本体工事以外に給排水とか電気設備等の工事の内容は、一般競争入札に入っている業者がダブっていますね。その辺は何か理由というか、そういう制限があるのかなと思ったんですけれども、その辺はいかがか尋ねました。","respondent":"鷹倉経理課長","answer":"広く業者の方々が選択の幅を広げるという意味で、重複申し込みをしている。区内で現在８４業者がいらっしゃいますけれども、広くいらっしゃいますので、重複申し込みをする必要はなかったという状態です。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"私がご質問をしているのは、荏原第五中学校と３件ありますが、その中で給排水施設とか電気設備は荏原第五中学校にも入札に加わっている。そういう企業は一切ないような感じなんですけれども、そういう部分での何か本体工事に関しての制限というのがもしあればお伺いいたします。","respondent":"鷹倉経理課長","answer":"台場小学校と大崎地区小中一貫校の第３グループ、あるいは荏原第五中と大崎地区小中一貫校の第３グループ、こういう形の重複は認められてあります。これは先ほど申し上げた共通の話ですけれども、区内の業者の方に広くチャンスを与えていくという内容です。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"給排水とか、電気設備等を見ると、大体同じような企業の方たちがそれぞれに入札に参加しておりますけれども、これはある程度制限に合致している企業が絞られてきているという考え方でよろしいんか尋ねました。","respondent":"鷹倉経理課長","answer":"条件のほかに参加資格というものがございまして、その参加資格の、区内の格付けと言っておりますけれども、これで一定の格付けをしています。その関係で、今委員がご指摘のような内容になっているのかと、このように考えてあります。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"見方だけ教えていただきたいんですけれども、例えば１番の安藤・大末・三英建設共同企業体の中で、これはどれがどうというふうに見ていけばよろしいんか尋ねました。","respondent":"鷹倉経理課長","answer":"横の同じラインで見ていただければと思います。今委員ご指摘のとおり、１、２、３の順で縦になっているです。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"例えば番号１番で見ますと、安藤・大末・三英の共同体としての資本金が一番上の金額で、そういうのではないんか尋ねました。","respondent":"鷹倉経理課長","answer":"安藤が港区で８９億円、そして大末が千代田区で５３億円、三英が品川区で３,６００万円、こういう形で読んでいただきたいと思います。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"伺いたいのは、教育をどういうふうに進めていくのかとか、企画のほうとしては独自につかむことがあるのか尋ねました。","respondent":"市岡企画財政課長","answer":"もちろん教育委員会のほうで事務的に方針を決め、実施計画ですね、区として計画をオーソライズしていくということはやってあります。その中で教育委員会が、地域の方のご意見や、全体のご意見を集約して、しかるべく計画として整理をしていく、こういうふうに受け止めてあります。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"そういうことがどういうふうに反映されるのかというふうに思うんですけれども、そういう意味では小中一貫校というのは新しい試みだと思うんです。そういうときに、そういうところの認識というか、こういうものは企画のほうとしてはつかまないでいいというふうなお考えなんか尋ねました。","respondent":"中尾根企画部長","answer":"企画の役割というのは、今の事業部制全体のことについてを底辺で支えるということです。区民の声ということで、そういうものに対してどう対応をしていくのか、企画そのものが単独に何かについてやるという仕組みにはなってございません。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"ある意味では教育委員会、区長部局でないですけれども、お互いにチェックし合うということが必要だというふうに私は思うんです。そういうところでやるとか、別に区民の意見を把握しているとかという、そういう考え方はいかがか尋ねました。","respondent":"中尾根企画部長","answer":"事業を進めるにあたりましては、いかにそれを実現させるか、そういう体制をとるというのが基本的になってあります。したがって、その意見に対してどういうふうに対応をしていけばいいのか、そういういろいろな側面からの事業部間での調整というものを行っているです。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"例えば東京都の中高一貫と、そういう関係というのは、今後どういうふうに調整が進むんだろうかというふうに思うんです。私としては教育委員会は非常に暴走しているんじゃないかという気もするんですけれども、その調整というのはどういうふうにやられるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"東京都は品川区とは別なんですけれども、そういうことは教育委員会に全く任せているという考え方か尋ねました。","respondent":"中尾根企画部長","answer":"そういうことについてどういうふうに受け止めていくのか、それは専門のセクションのところでお聞きになっていただきたいと私は思っております。区として決めたことについては全体として協力して、そのことを進める、こういう体制だと先ほどから説明しております。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"消費税込みで書かれていることについて、消費税というのは４月１日から税込みで消費者に対しては表示をしなさいというふうに法改正がありました。それは今回の消費税の表示改正に沿ったことなんか尋ねました。","respondent":"鷹倉経理課長","answer":"今回４月１日からのそういう動きがございましたので、その流れにも沿っているです。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"これは財務省のホームページから出してきたんだけれども、消費者に対して表示をする。そうすると、今回の場合は行政、品川区というのは消費者という立場に立つというふうに理解をしているわけか尋ねました。","respondent":"鷹倉経理課長","answer":"今回の趣旨というのは、全体額が誤解なく伝わるようにという趣旨があろうかと思います。消費者という線引きからは多少違うものがあるわけですけれども、全体額が分かるということから、今回こういう形にさせていただいたです。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"例えば５３億９,０００万円、５４億円、これを続けていかれるんですか。法的にこういう表示をしないといけないということなんか尋ねました。","respondent":"鷹倉経理課長","answer":"委員会資料としてこの作成が見にくいということであれば、２段書きにして、トータル額という形でお示しをさせていただきたいと思ってあります。本体価格、消費税、トータルという形の３段書きをさせていただきたいなと思ってあります。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"委員会ではぜひそういうふうにお願いしたいんだけれども、法規制がかかっているんですか。込みで入札をしなければいけないものなのか、別々で入札をしていくのが正しいのかという、その判断だと思うんです。","respondent":"鷹倉経理課長、本間総務部長","answer":"予定価格をお示ししているわけですけれども、税込みという形でお示ししています。それを踏まえて入札も税込みの部分で予定価格範囲内ということになってあります。先ほど経理課長が説明をさせていただきましたとおり、税込みで入札をしてもらいたいということを告示をして私どもは臨んです。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"行政がやることですから、こういうふうにしなさいよと言われれば、そういうふうにしなければ落札できないんだからする。考え方が、税込みの価格を知らせるために今回やっているというのは、消費者向けの小売り表示のことなんですよ。","respondent":"濱野助役","answer":"工事、区役所は行政体ではありますけれども、いわゆる消費者としての立場で物を契約するという形になるんだろうというふうに思います。条文については、後日お示しさせていただきたいと思います。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"いろいろなことを知らせなければいけないわけだけど、その辺の支障というか、そういうことはないですか。今回は特別なケースなんでしょうけれども、そういうところで何か支障が起きないものなんか尋ねました。","respondent":"市岡企画財政課長","answer":"そういうことができないかということも検討はしてみたんですが、いろいろ勘案した上で、今回こういうスケジュールにさせていただいたです。やや難しい問題、その直前に仮契約を新年度に入ってからやるということが一番無難なスケジュールではないかということを判断したものです。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"４月１日よりは、ここで現場説明をしなければいけないんだというのは分かっている。お聞きしているので、言い訳じゃなくて、それをお聞きします。","respondent":"市岡企画財政課長","answer":"これはチェックポイントというよりも効力要件ですので、これなしには契約はあり得ないんですということを言っているところです。誤解のないようにしておりますし、執行機関としての則を越えないように、そこは抑制をしてチェックをしているつもりです。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だからやっぱりゼロ債でいくべきじゃないのかなというふうに僕は思うので、それは一応要望として、これからもゼロ債実現に向けてお願いしておきます。だけど、学校建設というのが３件出て、１３社全く別々の会社が落札したというのは偶然か尋ねました。","respondent":"鷹倉経理課長","answer":"あるいは自分たちは今どういう仕事を抱えているか、そういう状態を見ながら、最終的に重複申し込みの可能な範囲の中から選択されていった。そして結果として１３社全体が違う結果になったという、こういう認識をしています。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"大崎地区小中一貫校の大成と、目黒川右岸の大成は違う会社ですか。荏原第五中学校はどうしようかという話、三校一遍というのが出てくるので、それについて何かお考えはありますか。","respondent":"鷹倉経理課長","answer":"それぞれがそういう話し合い的なことを避けていくと、一つの方法としてそういうものも考えられてありますし、私どももやってあります。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"これは補助が学校建設と別になるんですかね、生涯学習費のほうで上げていっているというのは、どういうふうに我々は知っておけばいいのか。生涯学習という、学校とは違うというのは分かるんだけれども、その辺を二つ説明を求めました。","respondent":"鷹倉経理課長、市岡企画財政課長","answer":"したがいまして、この辺のところを各ＪＶが諸費用、そして利益を見ながら入札金額を出してきているものと考えられます。周囲の動向に合わせた正確な見積もりを行っているですので、そういう傾向になるのかなと… 我々の予算でもできるだけ生涯学習のほうは生涯学習で補助金を取ろうと思って、８,９００万円ほど生涯学習の国庫補助金を落としています。","id":"exchange-021"},{"speaker":"本田委員","kind":"質問","question":"今システムの話がちょっと出ましたけれども、財調との関係はどういう関係になっているのかというのが１点。小学校、この辺の金額はどういうようなんだろうというふうにちょっと疑問に思っているんですけれども、何か特徴的な点があるんか尋ねました。","respondent":"市岡企画財政課長、宍戸施設担当課長","answer":"本委員会でも何回か都区検討会のご報告をさせていただいているんですが、まず、基準財政需要額の中に入れるという仕組みになってあります。この中で十分主張を尽くして、ますますこれからたくさん出てまいりますので… あるいはＰＣ工法といいまして、柱張りを工場でつくってきて、それを組み立てるという工法が入ってあります。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問","question":"品川区には３５校ですか、２３区全体の大きな問題でもあるし、これは大変な負担になってくるわけです。国の補助金等も確定していないということになれば、まだわからないと思うんですけれども、その辺は時期的にはどういう具合になるのか尋ねました。","respondent":"市岡企画財政課長","answer":"今の都区検討会自体が、平成１８年の例の清掃の特例的な対応が終わる時期を目途にしておりますので、このことは都区共通の理解にあると考えています。","id":"exchange-023"},{"speaker":"築舘委員","kind":"質問","question":"今度地下２階ですか、２号基ということで２つありますけれども、ここもやっていくのかどうか。プールのことに関してと、エレベーターのことに関してちょっとお聞きしたいと思います。","respondent":"宍戸施設担当課長","answer":"エレベーターですが、総合体育館専用のエレベーターということで２基ついてあります。ただし、深さにつきましては調整できるようになってございまして、そういう意味ではいろいろ話し合える幅としてはあるのかなと考えています。","id":"exchange-024"},{"speaker":"築舘委員","kind":"質問","question":"メディアセンターのほうで高学年の人が使うというんですかね、高学年者が５階、５年生から９年生まで５階で使うということです。１階からＲ階まで行けるわけですから、これからどんどん改築もあるでしょうから、そういった視点で見ていってもらいたいなという部分が一つ。","respondent":"宍戸施設担当課長","answer":"６階の特別教室、今のところ５階のメディアセンターについては学校専用の空間というふうなことで実施設計を進めているところです。今１基ですので、あとは基本的にはすべて健康な児童・生徒については階段を使いなさいというふうな前提でエレベーターの台数等を決めてあります。","id":"exchange-025"},{"speaker":"築舘委員","kind":"質問","question":"今年企画のほうで、学校の図書室も図書館とうまく連携させて、地域の方も使えるようにということでやったということだと思うんです。いいことをとり得ないという、そういう企画では私としては困るなと思うんですが、どうか尋ねました。","respondent":"中尾根企画部長","answer":"もう一方で、学校の機能ということを考えてやると、そういうものはなかなか１階のところにはこないという割り付けというふうになります。いろいろ検討をする中では、総合的に使っていくという方向に転換しておりますので、その点についてはご理解をいただきたいと思います。","id":"exchange-026"},{"speaker":"築舘委員","kind":"質問・要望","question":"２３ページにちょっと載っておりますけれども、監視設備ですか、もしご意見があったらお聞かせほしいと求めました。","respondent":"宍戸施設担当課長","answer":"今回、３校ともそうなんですけれども、かなりセキュリティという意味では重点を置いて検討をしています。しかも、監視カメラを３校とも付けてありますし、職員室等から警察に直結するというような設備を３校とも持ってあります。","id":"exchange-027"},{"speaker":"築舘委員","kind":"質問・要望","question":"これもこの有無の確認とか、そういうのはどういうふうになっているのか、お聞かせほしいと求めました。","respondent":"宍戸施設担当課長","answer":"したがいまして、６種類の化学物質につきまして、その結果が基準値以内であることを確認してから引き渡しを受けるというふうなことになってあります。その辺につきましては、工事の特記仕様書に明記しています。","id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"そうすると、そこにおいての駐車場スペースというのはどういう考え方、法的な根拠等があるのかなというのがちょっと気になったんです。本来的にはここでない委員会でやるべきことなんだと、やっていらっしゃるかもしれないんですけれども、ちょっと参考までにお聞きしたいと思います。","respondent":"宍戸施設担当課長","answer":"東京都に駐車場条例というのがございまして、それに基づいて駐車スペース等を確保しなければなりません。体育館何m2かに１台というふうなことになってございまして、小中一貫校につきましては２８台設けてあります。","id":"exchange-029"},{"speaker":"土井委員","kind":"意見","question":"２８台設けてあるとすれば、ここの真ん中にしかないわけだから、皆さんもっと車でお見えになる方もいらっしゃるんじゃないのという可能性もある。","respondent":"宍戸施設担当課長","answer":"３００平米に１台という規定がございまして、２６台で済むところを、２８台設けてあります。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"意見","question":"一つは、９ページのパースには植栽がこういうふうにされているんだけれども、１３ページの１階平面図にはそれがされていないんだけれども、この契約金額は外構工事も全部入っているんですよねとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"今回は外構工事については入ってございません。外構工事については別途、来年度契約するというふうなことになってあります。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"では、３校ともそういうふうに理解しなければいけないんですか。建設にあたって、外構工事は別にありますよというのは、僕は行政の説明不足だと思うけれども、思いませんか。","respondent":"市岡企画財政課長","answer":"先ほど来ご説明しているとおり、それでいろいろ工夫して、外構を外したと思います。それ以外の学校については基本的に全部外構工事を含めて債務負担を予算では取っておりますので、全体のご説明はできるというふうに思います。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"意見","question":"２校の場合もないから聞くけれども、それは、あとの外構工事については後年で発生してきますということは説明の中に入れるべきだと思う。","respondent":"宍戸施設担当課長","answer":"３回目の計画説明会、平成１６年１月１９日の段階で形状を変更するということが決まりまして、１月２０日に実施設計の変更について。","id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"ほかの建物全体の中で言ったら、変わるんじゃないのかなと、ごく素人は考える。１級建築士の課長がお答えになっているんだから、僕らの素人とは違う知識を持ってお話をされているんだろうと思うけれども、影響なかったんか尋ねました。","respondent":"宍戸施設担当課長","answer":"工事費としては、もし同じ仕様で元のボリュームをつくったとしたと仮定すれば、今回の設計によってやはり数百万円以上減ってあります。","id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"今入札して、この金額になっているけれども、あれがくっついていたら安かったという可能性だってあるわけじゃないですか。もしかしたら影響があって、４９億円で済んだかもわからないのかなという気がするので、僕は影響があったというふうにとっておくべきだと思いますよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問・要望","question":"調査するべきだというふうに言ったんですけれども、私どもは２００２年のときに区民の皆さんからアンケートをいただきました。今回の急いで契約というのはやめるべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"１点聞きたいんですけれども、屋上はどういうふうな使い方になるんでしょうか。ほかの学校は緑化とか、そういうのに使うんですが。","respondent":"宍戸施設担当課長","answer":"付ければよかったなと考えています。屋上の使い方につきまして、機械置場もありますけれども、屋上緑化として活用いたします。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"荏原第五中学校等太陽光とかもあるんだけれども、そこら辺の考え方はどういうふうになっているんか尋ねました。","respondent":"宍戸施設担当課長","answer":"環境に関する配慮ということで、それぞれ学校として取り組もうという姿勢はあります。太陽光発電につきましては台場小学校はやってございませんが、そのかわり太陽光パネルを活用した街路灯を外構工事の中で数基つくる予定はあります。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"そういうのは各学校で決めてくるんですか。その考え方がどういうふうにして決まるのかという基準があれば、説明を願います。","respondent":"宍戸施設担当課長","answer":"学校改築指針の中にもうたわれておりまして、それぞれの学校を設計する中で、そういった設計思想があることについては間違いございません。学校改築検討委員会と学校の先生が入り、どういうふうにしようというのを練り上げていくというふうな手法で決定していくものです。","id":"exchange-039"},{"speaker":"宮崎委員","kind":"質問","question":"もう一つ、工事中はグラウンドが使えなくなって、天王洲に行くとかというふうなお話だったんですけれども、歩いてかなり時間もかかるみたいな話だったんですけれども、そういうところの対応とか、あるいは利用の調整とか、そういうものというのはするようになるんか尋ねました。","respondent":"宍戸施設担当課長","answer":"教育委員会からそういうふうな区の施設を最大限利用して、なるべく教育環境に支障がないような工夫をしていこうというふうなことは聞いてあります。体育の授業、クラブ活動等につきましては、体育館を主に利用していくというふうなことになろうかと思います。","id":"exchange-040"},{"speaker":"川西委員","kind":"質問","question":"そういうことで、１２月、１月、２月の日照問題というのはどういうふうに検討をされたんですか。そのときに質問をさせていただいたから分かりましたけれども、ああいうものは、ここの絵のとおりか尋ねました。","respondent":"宍戸施設担当課長","answer":"桜の樹種、樹齢を考えると、今のところやむなく伐採せざるを得ないんじゃないかというふうなことになってあります。そのかわり、そういった伐採せざるを得なかった木につきましても、チップ化するなどしてリサイクルについては図ってまいりたいと思います。","id":"exchange-041"},{"speaker":"川西委員","kind":"質問","question":"日影規制というのは、あの位置であるんですか。今度建てるところだとないというのか、その辺が分かりましたらお願いいたします。","respondent":"宍戸施設担当課長","answer":"日影規制そのものが昭和４８年、大幅な改修ですとか、手を加えない限りはやむを得ないというふうな建築基準法上の取り扱いになってあります。したがいまして、今の建物は、今の日影規制の基準からいくとオーバーしているです。","id":"exchange-042"},{"speaker":"川西委員","kind":"質問","question":"ですから、排水関係とか、１２月、１月、２月が問題だと思うんです。４月のこの時期ですと、さっき３時に見ましたけれども、気持ちとして申し上げておくだけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"土井委員","kind":"質問・要望","question":"そういう特記事項は重要説明事項みたいなものですから、これからはよろしいんじゃないかと思うので、ぜひそうしていただけませんか。そうすると、そこの辺の関係は大丈夫なのかなと気になったものですから、ちょっと伺いたいと思います。","respondent":"宍戸施設担当課長","answer":"それから、舗装につきましても、インターロッキング等にして、歩きやすい空間にしたいというふうに考えてあります。すべて外構工事の中でやっていこうというふうなことです。","id":"exchange-044"},{"speaker":"土井委員","kind":"質問","question":"ここはどういう認定になっているのか実際はわかりませんし、何とも言いがたいんだけれども、そこのところが非常にひっかかるんです。ここでやるべきことであるかどうかというのも問題があるので、どうもそこら辺の近隣とのあれをどう認定するのか、それはどうなんか尋ねました。","respondent":"宍戸施設担当課長","answer":"通路扱いです。〔「２項道路とは言わないのか」と呼ぶ者あり〕２項道路でもなくて、通路扱いです。","id":"exchange-045"},{"speaker":"土井委員","kind":"質問","question":"というのは、あそこの公共溝渠の蓋をしてある溝は民地なの、それとも学校用地なの。それによって、あそこの蓋がどうなるかというものにも影響するので、どうなんか尋ねました。","respondent":"宍戸施設担当課長","answer":"あそこの公共溝渠につきましては民地です。","id":"exchange-046"},{"speaker":"土井委員","kind":"質問","question":"例えば２項道路ですと、昨今だったら枝みたいなところは手すりも付けてもいいよとかというような、いろいろな補助がありましたね。その辺はどんな形なんか尋ねました。","respondent":"宍戸施設担当課長","answer":"歩きにくい空間になってありますけれども、電柱を学校の敷地の中にやり、７０cm幅で舗装をするというふうなことで大分歩きやすくなるわけです。通路につきましては、これ以上とらなければならないという規定はないというふうに思います。","id":"exchange-047"},{"speaker":"土井委員","kind":"質問・要望","question":"できるかどうかわからないけれども、思いがありましたので、聞いておきます。あまりこれ以上聞きたくありませんけれども。","respondent":"中尾根企画部長","answer":"今の話についてはここで何とも言えませんので、そういうことについてはお伺いしましたので、受けとらせていただきます。","id":"exchange-048"},{"speaker":"林（宏）委員","kind":"質問","question":"学校改築をするのに、１校につき幾らぐらいかけていくのかという考え方が元にあるんですか。既存の学校を改築、新築していくという考え方であるんだけれども、そのときに、１校につき幾らぐらいかける、行政側にそういう考え方があるんか尋ねました。","respondent":"市岡企画財政課長","answer":"計画に対してどのぐらい充当していこう、そういう意味で言うと、２０億円から２５億円ぐらいでおさめたいなというのはあります。それとどちらをとるかということで、教育委員会のほうとも相談をしまして、基本的には学校単体の改築でいこうです。","id":"exchange-049"},{"speaker":"林（宏）委員","kind":"質問","question":"今みんな学校はそうじゃないですか。さっき言った、２０億円、２５億円で可能なんじゃないですかね。","respondent":"中尾根企画部長","answer":"建て替えるときにそのことはきちんと考えておかなければいけないということで、こういう考え方もきちんとこの場合は入れてあるんです。そういうことで、今回については台場小学校についてはそういう方法が結果的には一番いいのではないかという結論だったです。","id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問","question":"ただ１ｍ５０cmぐらい盛土がしてあるんですね。もう１点、今度のこの２校について、建築リサイクルということについては何か配慮をされているんか尋ねました。","respondent":"宍戸施設担当課長","answer":"今回、３校ともそうなんですけれども、建設リサイクル法にかかります。いろいろ建設途上に発生するものや何かにつきましても、あるいは解体して発生するいろいろなものにつきましても、リサイクルに努めていくです。","id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"入れていかなければいけないと思うので、それはこれからの２０年ぐらい続いていく学校の新築については特段の配慮をしていただきたい。もう１点、プールは屋上につくるというのは、これは学校を新築していく中で原則としているんか尋ねました。","respondent":"宍戸施設担当課長","answer":"学校改築指針の中で、土地を有効に利用するためには、なるべく屋上に持っていくほうが適切であろうというふうなことが出てございまして、それに則って適切に行ってあります。","id":"exchange-052"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"この金額とどれぐらいの差があるか計算できないんだけれども、これからずっと改築していく上で、その辺の金額の考えも入れておいていただきたいなと。この２校で考えたことはあるんか尋ねました。","respondent":"宍戸施設担当課長","answer":"屋根をかけるというところまで検討いたしましたので、屋根をかけたらどうなるかという検討をいたしましたので、今のところは屋根はかけていない状態の実施設計です。","id":"exchange-053"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それは金額的にどのぐらいのプラスになるかということがもし出ているならば教えていただきたい。高さなどはひっかかってくることもあるんでしょうから、高さが厳しいんだろうと思うけれども、金額的には分かりますか。","respondent":"宍戸施設担当課長","answer":"ちょっと今この場ではお答えできません。明日まででしたら、概算でしたらお答えできると思います。","id":"exchange-054"},{"speaker":"築舘委員","kind":"質問","question":"３２ページの空調設備ですけれども、すまいるスクールおよび管理諸室は、単独運転可能な個別空調機を設置すると書いてあるんですね。各教室はどういうふうになっているかということをお聞きしたいと思います。","respondent":"宍戸施設担当課長","answer":"大ざっぱに言えば、区役所と同じような方式です。メディアセンター、開放前提の空間という位置づけにしていますので、個別のパッケージ型の空調機を設置するというふうな計画にしています。","id":"exchange-055"},{"speaker":"築舘委員","kind":"質問","question":"そういうのは直しましょうということで、個別に教室にクーラーを付けたんですが、今付けているところはどういうふうになっているのかということ。先ほど普通の役所のようなクーラーですよと言われたんですけれども、それと、個別空調機というのはどう違うんか尋ねました。","respondent":"宍戸施設担当課長","answer":"ちょっと乱暴な説明だったんですけれども、特別教室につきましてはヒートポンプ型のパッケージエアコンになってあります。教室につきましては、ある程度一定ですけれども、個別に調整ができるという仕組みになってあります。","id":"exchange-056"},{"speaker":"川西委員","kind":"質問","question":"それだけ教えてください。それから、太陽光の補助金ですが、それは国庫補助というのは、こういう場合は取れるのか尋ねました。","respondent":"市岡企画財政課長、鷹倉経理課長","answer":"これが実は庁舎の省エネ型の照明設備、屋上緑化、こういうもので一部補助金が実際についております。だめでもともとみたいな世界ですので、努力はしますが、絶対取れるというものではないです。 これは平成１５年度予算でございましたけれども、その後にプレハブのリース料という形で平成１５年度分をすでにいただいております。今年度も引き続き平成１６年度分のリース料をいただくということになってあります。","id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"人間が壊すわけですから、プレハブ生活をするというのは、いわゆる人災なのね。そういうことをこれから改築をしていくときに、予算として上げていくというのはできないんですかね。","respondent":"市岡企画財政課長","answer":"不便を分かち合うことも含めて、生徒たちが分け合ってくれているわけですから、いろいろな形でできる範囲のことはしたいというふうに考えております。で、できるだけ対応できることは対応をしていきたい、こういうふうに考えてあります。","id":"exchange-058"},{"speaker":"林（宏）委員","kind":"質問","question":"やたら電気の入札が厳しいというんですか、こういうのをどういうふうに言うのか、例えば荏原第五中学校の４７ページなど凄いですよね。この入札状況という言葉で呼んでいいのかわからないけれども、これをどう捉えていらっしゃるんか尋ねました。","respondent":"鷹倉経理課長","answer":"今回重複はできないという形でやったわけですけれども、その結果、厳しい競争があったのかなということが想定されます。電気工事については区内の有力な力のあるところが結構いらっしゃるということで、厳しい競争になったのかと、このように考えるところです。","id":"exchange-059"},{"speaker":"林（宏）委員","kind":"質問","question":"そんな競争の仕方ではないんじゃないですか。入札の応札をした金額の見方というのは、どういうふうに持っておくべきなんか尋ねました。","respondent":"鷹倉経理課長","answer":"先ほども申し上げましたけれども、一定の基準に基づいて予定価格、あるいは予算等をつくっているわけです。この予定価格の中に一定の利益が見込まれているわけですけれども、そこをどこまで幅を見ていくかということが、各業界にあるのかなと思います。","id":"exchange-060"},{"speaker":"林（宏）委員","kind":"質問","question":"今年度は板橋区だか、江東区だかが２校やる。世田谷区でやるときは世田谷区の業者、大田区でやるときは大田区の業者という、学校改築に関してはこういう形でいくというふうになっているんか尋ねました。","respondent":"鷹倉経理課長","answer":"区外を考えてありますけれども、区内の業者でも十分対応できるということで、品川区はそういう形で対応をしています。その結果、ほかの区がどういうことになるのか、それは結果としてどうなっていくのかは、結果を見てみないとわからないと思います。","id":"exchange-061"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"世田谷区はこうするぞ、あるいはうちはこうするぞということになるのかどうか、品川区はけんかを売ったみたいな形になる。ぜひ関心を持ってというか、きちんと情報収集はしてほしいと求めましたので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"武内委員","kind":"質問","question":"入札に関してですけれども、入札をされるときに、入札最低ラインみたいというのは引かれるんか尋ねました。","respondent":"鷹倉経理課長","answer":"今回については特に引いてございません。","id":"exchange-063"},{"speaker":"武内委員","kind":"質問","question":"今回についてはないけれども、では、引かれるケースもあるということか尋ねました。","respondent":"鷹倉経理課長","answer":"物によっては最低価格という形で設ける場合もあります。","id":"exchange-064"},{"speaker":"武内委員","kind":"質問","question":"その設けたときは、それを下回ったら、それは失格というような形になるんか尋ねました。","respondent":"鷹倉経理課長","answer":"原則としてそうですけれども、ただ、あまりに下回った場合に、例外的に上の部分を取ることができるという規定はあります。それがあまりにもどうかという場合については、その上の部分を取るという規定も整備はされてあります。","id":"exchange-065"},{"speaker":"武内委員","kind":"質問・要望","question":"そういう心配が出てくることもあるかと思いますので、もちろんそんなことはないと思いますけれども、ぜひその辺のチェックをお願いしたいと思います。要望ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"２月２８日、本来であるべきゼロ債でやりたいんだと、国と都に強くゼロ債発行を認めてほしいということを行政側に要望したい。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/406359?Template=document&Id=1644#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":49048,"voices":177}},{"id":"h16-20040409-5","meetingId":"h16-cm04","date":"2004年4月9日","dateIso":"2004-04-09","committee":"総務委員会","time":"午前１０時０８分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"第４３号議案目黒川右岸排水施設整備工事その６請負契約","agenda":"第４３号議案目黒川右岸排水施設整備工事その６請負契約","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"何回かその５、その４と携わってきたんだけれども、１から６の合計で幾らぐらいかかったのかというのをちょっと説明を求めました。","respondent":"矢部下水道河川課長","answer":"合わせて延長としますと１.４キロになってあります。それから、金額ですけれども、その１からその６工事まで、合計いたしますと約４２億円となっています。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"もう一つは、この工期なんですけれども、予定は６月３０日ですよね。あるいは台風シーズンになるとかいうところがあるんだけれども、５月いっぱい、１カ月早く仕上げるというのは不可能なんでしょうかね。","respondent":"矢部下水道河川課長","answer":"実はこの工事、当初は平成１７年３月までに何とか完成できないかという形で当初は進めておりました。そういうこともあって、たたきにたたいた結果が６月３０日ということなものですから、それをさらに１カ月というのは非常に苦しいと考えております。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"これで予定は６月３０日ということなんだけれども、突貫工事までいかないにしても、できるだけ早く仕上げるようにということは可能なんですか。３分の１ぐらいが最初に使えたという記憶があるんだけれども、していただければありがたいなと思うんですけれども、いかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"昨年の１０月１３日の大雨のときに、そこに約６００ｔですか、水がたまりました。それで、下流につきましても委員おっしゃるとおり、なるべく早く終わるように努力していきたいと考えています。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"計算どおりにはいかないでしょうけれども、一つのカバーというか、防護にはなる。５回随意契約で来るんだけれども、妥当さというのかどうかわからないけれども、そういう基準はどこに置いていらっしゃるんか尋ねました。","respondent":"鷹倉経理課長","answer":"今回、その６の随意契約は、さかのぼりますと、その３のときに制限付き一般競争入札、こういうものをやっているわけですけれども、このときの落札率以下におさえるように随意契約をかけている、こういう考えです。","id":"exchange-004"},{"speaker":"土井委員","kind":"質問・要望","question":"この工法でやりますと、ただ掘削して後から埋めるというスタイルではありませんから、もともとあまり地盤のいいところとも限らないわけですよね。掘り出してくる土はかなり水分を含んだ土だということですから、まだ掘る前から、まだ掘ってないよと言ったぐらいのものですから。","respondent":"矢部下水道河川課長","answer":"この工事が始まるときに、住民説明会を開きました。付近の住民についても情報交換してくれということなものですから、このデータについては積極的に公開して、安心してもらっております。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"さっき言ったように、始まる前に、まだ掘ってもいないのに下がったという話がされているぐらいですから、相当皆さん気になっているなということなので、対処していただいたということで、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"この地域の雨水は、下水道管にもしつながっていれば、どっちのポンプ場に行くんですか。東品川のほうに行くんですか、鮫洲のほうに行くんですかね。","respondent":"矢部下水道河川課長","answer":"ですから、現在の工事が終わりますと、低地部の下水管の排水能力が余裕ができますので、それだけ浸水被害が少なくなるです。将来的に低地部の排水管をまた布設する予定にしてございまして、そこから東京湾に低地部だけの雨水ですけれども、放流される予定になっております。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"一時貯留する能力というのは、先ほど一時的に６００ｔというふうなことを言われましたけれども、どのくらいの能力を持つことになるんか尋ねました。","respondent":"矢部下水道河川課長","answer":"今回の工事が完成しますと、基本的には流下管として利用いたします。ですから、貯留能力が何ｔという形での評価ではなく、あくまでも、もう１本目黒川に向かってのバイパス管ができるというような形になります。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"そうすると、素人的な判断なんですけれども、満潮なんかとぶつかって、また大雨が来て、目黒川がいっぱいいっぱいになっているという場合のはけぐあいというのはどうなるんか尋ねました。","respondent":"矢部下水道河川課長","answer":"ただし、ここにつきましては、第四日野小学校からはけ口まで約１０ｍの落差があるんですすね。その水圧で目黒川に雨水を押し出すというような構造になっております。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"それで、今度の予算には入っていたと思うんですけれども、三共製薬の前の三嶽橋のつけ根のところが、見た目にわかる亀裂があるんですよね。その辺の安全性というのは、所管が違うところかもしれませんが、掌握されているんですかね。","respondent":"矢部下水道河川課長","answer":"橋等につきましては、委員ご指摘のとおり、東京都の建設局が順次進めているです。それにつきましては、建設局のほうにその辺の情報、そういうことはちょっとお伝えしながら検討をしてもらうような形にさせてもらいたいと思います。","id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"しかし、あれは特別区道、あれは何か公道なんですか。三共がつくった橋ということではないんか尋ねました。","respondent":"濱野助役","answer":"必ずしもはっきりした記憶ではありませんけれども、三嶽橋については区でしていると思います。改修のときに三共と話をしたということもあれしていますが、ちょっと答弁を保留させていただきたいと思います。","id":"exchange-011"},{"speaker":"本田委員","kind":"質問","question":"所管外のことですから。本件とは違ってはいますけれども、ちょっと指摘しておきますので、調査をお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"昨日から本日までに可決しました第４４号議案から第５３号議案および第４３議案に対し、昨日、林（宏）委員から提案がありました附帯決議","agenda":"昨日から本日までに可決しました第４４号議案から第５３号議案および第４３議案に対し、昨日、林（宏）委員から提案がありました附帯決議","exchanges":[{"speaker":"林（宏）委員","kind":"提案","question":"あるいはこれからゼロ債にしていっていただきたいという、委員会として決議をして、その意味を促したいということから提案をさせていただきました。〔附帯決議案朗読〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"提案","question":"行政側にお願いするという意味で、承認の上に、これを総務委員会の考え方として附帯していきたいということで提案をさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"この臨時会が行われるということですから、あまりかたいこと言わずにという言い方が適切であるかどうかはともかくも、やるべきだと。立て替え払いしますよと言っても言えないこともない状況なわけですから、そういうことができるような裁量を欲しいな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"川西委員","kind":"質問・要望","question":"中規模修繕というんですか、小破修理というのか、よく行います。これを機会に学校関係の中規模修繕というんでしょうか、小規模というのか、ああいうものももう少し工夫していただくような指導をお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"意見","question":"１のところで、どういうことが今後考えられるのか、どういうふうな影響が出てくるか。何かわかりますかとの意見を述べました。","respondent":"市岡企画財政課長","answer":"建物の規模も階高も、しかも小中一貫校のような相当程度の規模の工事について対応できるような制度になっていないという現実があるかと思います。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"意見","question":"我々議会のどうしても４定例会というのは日にちが決められていますから、６月というのが空白にならざるを得ないんですね、一般的にすぐ。行政はまたいろいろ功罪をお考えになっていらっしゃる、そういう意味ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"本田委員","kind":"意見","question":"２番のところでは、あえてやらなくてもいいのになとは思うところもあるんですけれども、そんなふうに受けとめております。自治権を広めていくという観点があるというふうに私はとらえますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"契約ですから、卒業式を新しい校舎で迎えてほしい、総務委員会で承認する。そういう意味で念押しをしたいなというんで２番目も入れたというのをご理解いただくようにしておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"本田委員","kind":"質問","question":"臨時会を開いた。決めたということ自体が重さを持っているわけですから、２番のところでは、だめ押し的なあれだなということを先ほど申し上げたわけで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"意見","question":"３月の予算で補正を組んで、できないのはなぜかと言ったら、何もこの臨時会を開かなくてもいいということになるわけです。学校をつくる、さっきの出た２０から２５億という目安の中で、こんな臨時会は本来は開かなくて済むわけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問","question":"ちょっといいですか。できれば、附帯決議の採決で委員長報告のどこに入れるかをここでやるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問","question":"宮崎委員から意見が出たけれども、言っている意味からすればどうなのかなというふうに思うんですけれども、できれば全会一致で総務委員会としては。ここまでやるんだとなれば、重さがまた違ってくるわけですから、その辺はどうなんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"本田委員","kind":"意見","question":"今、宮崎委員のだめだというようなことであれば、それはやむを得ないなというふうに思いますね。多数の意見として位置づけていただいて、行政サイドにもご努力をいただくというぐらいに、もうしようがないなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/406359?Template=document&Id=1646#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":13255,"voices":66}},{"id":"h16-20040412-6","meetingId":"h16-cm04","date":"2004年4月12日","dateIso":"2004-04-12","committee":"区民委員会","time":"午後１時０４分～午後４時１１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"２の報告事項","agenda":"２の報告事項","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"そういう発想が出た背景といいますか、なぜ、一般の人のための美術館をつくろうとしたのかというところ。チラシ代、それからセコム等のことがあると思うんですが、大体どれぐらいの予算がかかったのかとの意見を述べました。","respondent":"諸岡区民生活事業部副参事","answer":"ご質問の第１点目の、不適切の場合以外は、すべて基本的に作品を展示する予定です。そういったものを細かい部分ですが、ざっと含めまして、このような金額になってあります。","id":"exchange-001"},{"speaker":"嶋委員","kind":"質問","question":"それから、チラシのほうには、応募状況に変更がありとありますので、変更があるのかなと思いますが、４カ月は結構長いかなと思います。４カ月になぜされたのかお聞きしたいと思いますので、そこら辺、。","respondent":"諸岡区民生活事業部副参事","answer":"当然ご紹介することはできないんですけれども、例えばその方が区民作品展を開いたり、そういった機会をとらえて見ていただければと考えています。","id":"exchange-002"},{"speaker":"嶋委員","kind":"質問","question":"これは、私が聞きもらしたのかもしれませんが、４月１日から、インターネットで応募はできますけれども、実際、これが展示されていくのが、いつから開始をされるのか尋ねました。","respondent":"諸岡区民生活事業部副参事","answer":"４月１日からインターネットを公開いたしまして、応募を開始しております。４月３０日で切りまして、５月に入りましてからできればと思いますが、展示していきたいと考えています。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"１回に展示できる数というのは、どのぐらいになるんか尋ねました。","respondent":"諸岡区民生活事業部副参事","answer":"予定しておりますのは、大体５０点前後かなと。ただ、上限は１００点ぐらいは可能です。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"上手だから、下手だからというのはないと言ってますから、子どもたちの作品を一同に、何々小学校と。美術館に載っているということになると、相当な反響を呼ぶような気がするんですけれども、そういうような考えはいかがか尋ねました。","respondent":"諸岡区民生活事業部副参事","answer":"子ども作品展ということで、小学生の作品を、例えば企画展の中で、子ども作品展ということでやってみたいという案もあります。企画展の中で、そういったことをさせていただければと考えています。","id":"exchange-005"},{"speaker":"松澤委員","kind":"意見","question":"私のところなら戸越小学校６年生の全員の作品が載っているとか、全員の作品が載るような形になれば、これはすばらしいことだと思うんです。こういうところでやればすばらしいなと思うんですけれども、そういう考え方、方向性に持っていけないものか、最後にもう一度との意見を述べました。","respondent":"諸岡区民生活事業部副参事、山田区民生活事業部長","answer":"一般の方を対応していますので、企画展の中でとらえて掲示をするというようなことで、今のところ考えてあります。 それぞれ作品を、まただれがやるかという問題ということで、かなり学校の負担の部分が出てくるかなという心配もあります。これについては、ちょっと教育委員会と、どういう形だったら表現できるか協議していきたいと考えています。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"今の答弁、そんなの簡単だよという声も皆さんから出たんで、やってみれば簡単で、僕でもできるぐらいのことですから、そういう意味ではお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"三村委員","kind":"質問","question":"セキュリティのデータが添付されています、これを開けていいですかと、必ず聞かれますよね。かなりコンピュータウィルスの検出が高いかと思いますけれども、そういうことでは、どういうふうに対応されているんか尋ねました。","respondent":"諸岡区民生活事業部副参事","answer":"ＮＴＴが誇るサーバーセンターですが、そこに設置をされておりまして、そこでウィルス対策も講じられております。もしメールが感染した場合、自動的にウィルスを検出して、該当への送信を直ちに停止するとか、大変信頼の高いセキュリティを講じてあります。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"４月１日から募集を開始したようですけれども、現在、どのぐらいの応募状況なのか。どういう方々がいらっしゃるのか、どういう方々がおいでかということを、ちょっと教えてほしいと求めました。","respondent":"諸岡区民生活事業部副参事","answer":"品川文化振興事業団が発行いたしました「しながわの美術散歩」という本、これに、あるいはゆかりのある作品が展示されてあります。直ちにどれでも載せるということはできませんが、順次、計画的に少しずつ載せていければと考えています。","id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"そういう点では、作品が１０点と理解したんですけれども、いわゆる出品された方が必ずしも１０人とはならないのかなと考えています。わかりました、ありがとうありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"木下委員","kind":"質問","question":"申込みがあったら、上限が決まっているということは、とりあえずそういうふうにうたってあるんでしょうか。今はだめにしても、将来的にアップするようなことを考えていらっしゃるのかどうか、そこら辺のところをお聞かせ願えればと思います。","respondent":"諸岡区民生活事業部副参事","answer":"恒常的に１００点を超えるのがずっと続くようであれば、展示数を１００点までにしますというようなことも、これから載せていくことも考えてあります。簡単に、あるいは安い予算でそういったことが可能ということであれば、動画についても考えてみたいと考えています。","id":"exchange-011"},{"speaker":"田中副委員長","kind":"質問","question":"端的にお伺いしたいんですが、公序凌辱という部分で言うと、芸術の分野の作品に対する評価というのは非常に難しいものがあろうかと思うんです。逆に区側としてどのように保護していこうと考えていらっしゃるのか、大きく２点、お聞かせほしいと求めました。","respondent":"諸岡区民生活事業部副参事","answer":"載せることが適切かというのが非常に難しいですが、確かに、この部分の判定というのが一番難しい部分であると思います。１件数千円ということで、今後検討してみたいと思いますが、現在考えられる範囲での防止策は講じているつもりでおります。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"１,０００万円の範囲の中で５００万円までは追加ということで借りられる、そういうことでいいのかどうか確認したいと思いますので、お願いします。もう１回、区のほうはどういうふうに承知されて、改めてちょっと伺っておきたいと思います。","respondent":"日下部産業振興課長","answer":"少なくとも、今週中ぐらいにはでき上がると見込んでおりますので、でき上がり次第、早急に配布をして、間に合わせたいということで考えております。それから、４点目ですけれども、これについては、先ほど、資金の実施の背景のところでもご案内させていただきました。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"２点お伺いしますが、月々の返済負担を軽減すると書いてあるんですが、必ずするんでしょうか。するならば、なぜ一本化することで、返済が軽減するのか、そのシステムを詳しくお伺いしたい。","respondent":"日下部産業振興課長","answer":"私どもの試算でまいりますと、大体、月々の返済が１５万円ぐらいまでいってしまうんです。２点目の元金の返済ということなんですが、元金を含めての償還という、そういうようなことで理解をしていただきたいと思います。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"追加５００万円といったときに、信用保証料というのはどのぐらい取られるものか、数字的にお願いしたい。これは大丈夫そうだから安いとか、そういう区別があるのか、その辺のことを説明するよう求めました。","respondent":"日下部産業振興課長","answer":"ですから、それの２分の１を補助するということになりますと、ご本人負担７万円、逆に、区が７万円ほど補助するという形になってまいります。それから、事業者の経営状況とか、そういうことによって区別があるのかということですが、基本的に、それについてはございません。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"１０月２９日までということなんですけれども、あるいは経済状況を見てのことだろうと思いますけれども、半年に限ったというのは何なのか。せめて１年ぐらいはと私は思ったんですけれども、そこのところの考え方を、ちょっと教えていただきたいんです。","respondent":"日下部産業振興課長","answer":"６カ月間という、今後の景気の動向とか、借り入れの申込みの推移等も十分に見極める必要があるだろうと。そういったことも含めまして、まずは半年間で設定させていただいたです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"一つの手続の中で区の見解を出す部分ですけれども、やっぱり相当な経費をかけての建設ですから、やっぱり中止を求めていきたいなとは思っております。この装置を考えなさいという話ですから、土壌脱硝装置というものを、あえて具体的な方式として取り上げたところの区のご見解を伺いたいなと思います。","respondent":"金井環境課長","answer":"予定者は２５名のところ、欠席等も含めて１９名がご発言されたと聞いております。そういう予定はないという答えをしているようですけれども、私どもとしては、できるだけきちっとすべて要求していこうという考え方です。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"私が伺っているのは、１１町会のところでは、条件を整えてほしいという趣旨だという説明でした。品川区が意見書を出す部分のところですから、その責任を果たしていただきたいということを、改めて強くお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"三村委員","kind":"質問","question":"何点かお聞きしたいんですけれども、環境全般の２番で、事後調査が行われるのかというところをお聞きしたいんです。","respondent":"金井環境課長","answer":"基本的に、事後調査といいますのは、できる限り、環境影響評価をする項目について事後調査するという形になりますので、評価項目全般が対象。場合によっては、多少の減はあるかもしれませんが、基本的な考え方は、その評価項目全部です。","id":"exchange-019"},{"speaker":"三村委員","kind":"質問","question":"起こってしまった場合にもきちんと速やかな対応をしてくださいというような表現もこの中に入れるべきではないかと思うんです。この意見については、ある程度これが最終段階ということで、まだ修正が加えられるということでよろしいんか尋ねました。","respondent":"金井環境課長","answer":"確かに、地盤沈下のところには、事後の話は入ってございません。区としても、委員の皆さん方のご意見で参考になる部分については、追加は可能です。","id":"exchange-020"},{"speaker":"三村委員","kind":"質問","question":"それから、環境全般を見て、「適切な措置を講じられたい」とか、もう少し全体の表現を強めてほしいなと思います。低周波に対することを意見書の中に盛り込むということについて、ご意見をお伺いしたいんです。","respondent":"金井環境課長","answer":"先ほどの内容についてですが、２番目の「環境影響評価の予測を超える状況」というのは、全般的なことを申し上げております。低周波のことは、特にここには取り上げございませんけれども、少し検討したいと思います。","id":"exchange-021"},{"speaker":"三村委員","kind":"質問・要望","question":"１１町会のほうから、平成元年から１０年と、ここの浸水被害のある地域と１１町会の地域とほとんど重なるんです。品川区としては、どういうふうに都のほうに求めていくのか、そういったところをご答弁してほしいと求めました。","respondent":"金井環境課長","answer":"１枚目の大気汚染の１番のところで特に強調して、ここでさらに強くこういった内容を求めていこうということで、挙げさせていただいてものです。","id":"exchange-022"},{"speaker":"三村委員","kind":"質問・要望","question":"１点だけ、中央環状品川線のことで要望したいんですけれども、どういうふうなことが行われるのかという電話をされたそうなんです。中央環状品川線に対しての区民の意見を知りたいときに対応をされるのか、その点だけ、最後にお聞きしたいと思います。","respondent":"金井環境課長","answer":"環境影響評価準備書関係というのは、環境課で議会にご説明しておりますが、ここで公告縦覧をやっております。環境課のほうにお電話いただければ、私どもが誠実に対応させていただこうと思いますので、よろしくお願いいたします。","id":"exchange-023"},{"speaker":"三村委員","kind":"意見","question":"多分、環境窓口のほうに電話をされたかと思います。その辺のところは、どういうふうにされているのか、ケースの中で対応してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"田中副委員長","kind":"質問","question":"交通集中、渋滞ということに対する意見は、今回の環境影響に対する意見としては述べられないんでしょうか。交通渋滞対策を講じてほしいという内容が、今回は、そういうものが入っていないという理解をしてしまっていいんか尋ねました。","respondent":"金井環境課長","answer":"環境面ですけれども、渋滞の可能性が十分にあると考えられれば、そういった渋滞に伴う環境汚染という形になりますので、述べられないことはございません。","id":"exchange-025"},{"speaker":"田中副委員長","kind":"質問","question":"二次的なというんでしょうか、特に環境に対する影響が、まだあるような気がしてならないんです。非常に抽象的な質問になりますが、どの範囲までを対象にした意見書というふうに考えていいんか尋ねました。","respondent":"金井環境課長","answer":"どこまで具体的に細かく言うかというのがなかなか難しい面はありますけれども、意見としてお示ししても、何らおかしい話ではないと思います。ですから、そういったご趣旨は、私どもも意見があるということは十分承知をしているつもりです。","id":"exchange-026"},{"speaker":"田中副委員長","kind":"質問・要望","question":"私の要望としては、対策に対しての、東京都への要望というのをぜひ主体に行っていただきたいと思うんです。非常に将来の話で恐縮ですが、その辺の姿勢をお聞かせほしいと求めました。","respondent":"金井環境課長","answer":"今も他方面でやっておりますが、移動してはかることができますので、特にこの辺を重点的にやっていきたい。さらに事後、区としても積極的にきちっと調査をしていきたいと、私は考えております。","id":"exchange-027"},{"speaker":"田中副委員長","kind":"質問・要望","question":"ぜひ、よろしくお願いしますと同時に、引き継ぎのほどもよろしくお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"区としてどういうふうに今の現状を思っているのか、この点について、ちょっと見解を伺いたい。そのことが、３月２９日の意見を聞く会の発言された方々の意見も含めて、その点についての見解も伺いたいと思います。","respondent":"金井環境課長","answer":"平成１２年度から１０年間の予定ですが、東京都の測定局ですが、平成２２年度までにすべての環境基準を達成することを目標とすると。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"五反田周辺、あるいは環状６号線周辺についての現状認識について、伺ったつもりなんですけれども、それについては、見解はどうか尋ねました。","respondent":"金井環境課長","answer":"先ほども申し上げましたけれども、換気所の設置に対して反対をされているということは承知をしております。換気所設置によって、あるいは出入口の設置もされるということで、ここの位置については反対だという意見をされているということは聞いております。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"ちょっと質問したところが違うつもりでいたんですけれども、環状６号線の交通量等々の状況の中で、幾つか測定をしていますよね。区としては、環境課としては、今の現状をどういうふうにとらえていらっしゃるのか、それをお聞きしたかったんです。","respondent":"金井環境課長","answer":"三年前に２回ほど、その道路を私どもでは環境基準を調べてまいりましたし、これは間違いございません。国もそうですので、それにつながっているわけです。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"ほんとうにまず見直しをしていただきたいということを強く要請しながら、同時に、ほんとうによくしっかりと考えていかなきゃいけないと考えています。繰り返して申しわけありませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、始終ひっきりなしにあるわけです。そういう状況の中にいるわけですから、１万６,０００人の人口が住むまちですから、ほんとうに品川区に頑張っていただきたいと考えています。","respondent":"金井環境課長","answer":"千葉県のことを考えたというのは、感情的ではございませんけれども、やはりこれはちょっと論理が合わないのではないかなと思います。先ほどもご説明申し上げましたけれども、私は考えておりますし、これはしっかり意見を言っていきたいと考えています。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"深夜は１時間に２９本の離発着はしないと思いますけれども、ほんとうに環境の悪化そのものですから、ほんとうに頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"田中副委員長","kind":"質問・要望","question":"その前にお伺いしなくてはいけないんですが、悪天候時ということの定義といいますか、どの程度の状況が悪天候と言われているのか。もしわかればお聞かせほしいと求めました。","respondent":"金井環境課長","answer":"今のご質問の２点ですが、悪天候時のこのルートの便ですが、大変恐縮です、ちょっと把握しきれておりません。それから、悪天候時ってどのぐらいのことかというのは、大変恐縮です、正直言ってわかりません。","id":"exchange-035"},{"speaker":"田中副委員長","kind":"質問・要望","question":"国が意見を求めるということで、このルート上の各自治体にも意見を求めると思いますし、まさに東京都に対しても意見を求めることになろうと思います。どこまでご見解をお伺いできるかわからないんですけれども、品川区がもし単独で反対をした場合の全体への影響度というんでしょうか、予測の中では。","respondent":"金井環境課長","answer":"やはり海上に音を落とすことを考えて、再度、検討をしてほしいという話をされていると聞いております。さらに、こういった区域を活用したルート、これもさらに検討したほうがいいと。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"ただ、これを私たちが伺って、ああ、こういう見解で調査・研究も含めて、していくんだと見ていいのかどうか。あるいは、何かの形で区民の方々に出ていくのか、ちょっとその辺を伺いたいと思うんです。","respondent":"中山清掃リサイクル課長","answer":"その後の対応したものを報告することになっておりますので、今回は常任委員会に報告をさせていただきました。ご質問の今後の対応という部分につきましては、個別の施策の中で議会に報告すべきそれなりのときがあった際には、報告するべきものです。","id":"exchange-037"},{"speaker":"木下委員","kind":"質問・要望","question":"その他ということで、４月１日に、西品川で崩落事故がございましたけれども、それについて、品川区内で何カ所ぐらいそういう危険な地域があるのか。その後、どういう状況だったのか、お調べになっていらっしゃるんでしたら、そこら辺を教えていただきたい。","respondent":"久保田防災課長","answer":"現場のほうの監視状況も、業者が対応するという体制がつくられましたので、午後３時に本部を解散したという状況です。関係業者に一刻も早い応急対策を実施して、被災された住民の方々に対して誠意を持って対応してほしいということで、指導をしてきたという状況です。","id":"exchange-038"},{"speaker":"木下委員","kind":"確認","question":"区のほうから業者のほうに確認ですとか、どうしてこういうことが起こったのかというのは、おやりになられたんでしょうか。業者の言い分としては、何かおっしゃっていることがあるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663620?Template=document&Id=2388#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":53918,"voices":115}},{"id":"h16-20040412-7","meetingId":"h16-cm04","date":"2004年4月12日","dateIso":"2004-04-12","committee":"厚生委員会","time":"午後１時０４分～午後３時０６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林委員","kind":"質問","question":"基本的なところだけ１点。それから滝王子学童保育クラブの９４人、今お話があった後地学童保育クラブの５８人、１点教えていただけますか尋ねました。","respondent":"辻田児童課長","answer":"さらに３０名増えたため職員を配置したということで、言ってみれば、もとからいえば２名加配という形になってまいります。３名配置しております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それはそういうふうな仕組みですから仕方がないと思うんですが、どこに行ったのかというふうなあたりをちょっと教えていただきたいのが１点です。それと、４月の対応というのがすまいるスクールに行った場合、具体的にどのような対応がされたのかについても教えてほしいと求めました。","respondent":"辻田児童課長","answer":"４月１日以前、その前から行く予定の人につきましては、意識の改革であるとかというようなことも研修を通してやっております。きちっと児童センター、学童保育クラブ、そこら辺もきちっとフォローしていますよということで出かけているです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"学童保育クラブの子どもたちがすまいるスクールにこれからは通わざるを得ないというふうな状況になったわけですから、初めてということですよね。では、その子どもたちに対して、どれぐらいの体制でどういう対応がされるのかというあたりももうちょっと教えていただきたい。","respondent":"辻田児童課長","answer":"９月ぐらいから、私どものほうと共通した認識を持ちながらやっていっておりますので、十分その辺は今後も展開していけるというふうに考えております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"児童センターからの応援という形で行っているわけですよね。現在の時点では、すまいるスクールは児童センターのほうから応援が入って、複数の運営でされているというふうなことなんじゃないか尋ねました。","respondent":"辻田児童課長","answer":"４月１日、移行期ですので、混乱がないように努力しているということです。ただ、行ったというのは、心配だということで、児童センターの職員が確認をしに行ったという幾つかの事例があるです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その応援体制というのは、今年１２校が１０月から新たに開校されますけれども、そこに配置をされる方が応援に行っているということですか。応援に行っているところは、どこの職員が応援体制というのをとっているのか、そこら辺のところがちょっとよくわからないんですが。","respondent":"辻田児童課長","answer":"その職員が、要するに４月１日時点でまだ研修等も済んでおりませんけど、子どもを受け入れるということは非常になれております。それは昨年から私のほうから、児童センターから行くというようなことは一度もご答弁したことはございません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、そこの開校する１２校の職員が既に開校された１９校に応援に行っていると、こういうことでいいんですか。それだとしても、ちょっと人数が足りないというふうに思うんですけど、そこら辺は。","respondent":"辻田児童課長","answer":"全体では係長がおりますから３名という形になります。確かに１９人と１４人ですと五つばかり足りませんけど、中にはいろいろな状況がありますから、その状況を見ながら応援体制を組んでいたです。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは今複数で対応されているということなんですが、複数配置をぜひすまいるスクールのほうにも求めていただきたいと、これは要望です。これに対応する学童保育クラブが来年の４月から閉鎖をするという、こういうふうな方向でいいのかどうか、このことだけちょっと確認したいと求めました。","respondent":"辻田児童課長","answer":"今年立ち上がる１２校のいろいろな関係のスケジュールですけれども、まだ教育委員会とその辺については詰めておりません。説明会等も含めて、どういう形、日程でやっていくか、その辺については今後十分詰めていきたいというふうに考えております。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めてこのことについては父母に対してもしっかりと説明をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問","question":"１０月からの準備の職員も動いているということで、この辺の職員は教育委員会のほうに定数が動いたと受けとめていいんでしょうか。ちょっとその辺の定数が具体的に児童センター、学童保育クラブのところの定数が数字的に変わっているのか、その辺をはっきりとお伺いしたい。","respondent":"辻田児童課長","answer":"これにつきましては、今年度、移行することはすべて確実ですので、そちらのほうで４２名の定数を教育委員会につけております。ただ、これは一つの過渡期ですので、そっくりそのまま、今４２名が向こうに全部行くという形ではございません。","id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"じゃあ、４２名すべてが行くわけじゃないというところで、今の児童センター、学童保育クラブのところの定員が何人から何人に変わったのか教えていただきたいんですけれども。","respondent":"辻田児童課長","answer":"昨年の４月１日と比べますと、１２７人でございましたから、今年は１０９人ですので、１８人の減になっております。そのときの現員が１２５人、１０９人ですので、要するに１６人の減になっているです。","id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問","question":"定数のところは、これはまだ動きがあるということですか。確定しているということではなくて。","respondent":"辻田児童課長","answer":"基本的に４２名というものを置きながら、私どものほうの定数、これは児童センターの定数、各館の定数を何名にするかということを今検討しております。それに合わせて私どものほうも努力していくということです。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問","question":"は定員オーバーのところをお伺いします。スペース的にどう考えていらっしゃるのかなというのと、ほかのところはどうなっているんでしょうか、あわせてお伺いします。","respondent":"辻田児童課長","answer":"今回７４人ということで、定数６０人に対して７４人ということでしたけれども、１名配置しているという状況で対応しています。子どもたちがあふれ出ているという状況は、私どものほうは報告も受けておりませんし、ないというぐあいに考えております。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問","question":"もう一回お伺いしたいのと、どういう基準でここまで増やしているのかなという思いもあるんですけれども、スペースの問題と定数をどう考えているのかというところをお伺いしたいんですが。","respondent":"辻田児童課長","answer":"昔と違った形で畳１.何畳とか、そういうスペースがあれば、私どものほうは十分学童保育事業をきちっと実施していけるというぐあいに考えております。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ロッカーとか、くつ箱とか、個人の居場所をきちんとするところはよろしくお願いしたいと思います。育成室が前の国の基準としては１.６幾つか平米ということであったんであって、その辺は改めていただきたいなと思うんですが、これで最後にします。","respondent":"辻田児童課長","answer":"私、今まで育成室が狭くてもいいというようなことをご説明したことはございません。それから、いわゆる健全育成ということを目的としてこの事業を実施しているんだということで、ある一定程度整備されたというぐあいに考えております。","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"意見","question":"子どもたちの生活の場なので、ぜひぜひ毎日過ごす場所ですので、環境の問題も、職員の方々とか、父母の方々のお声を聞いていただいて、改善できるところはぜひ改善をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"三上委員","kind":"意見","question":"うちは夜１０時までやるよと手を挙げる園がないのか、いやそうじゃないと、そこらあたりはどうなんでしょう。希望はありませんか、夜１０時までやってもらいたいという、いかがでしょうとの意見を述べました。","respondent":"金子保育課長","answer":"それから荏原というところでそれぞれ実施してまいりましたが、その近辺に１０時までの保育園を増やしていくことによって分散を図ってきたところです。","id":"exchange-016"},{"speaker":"三上委員","kind":"意見","question":"結局、そういった夜１０時までやっているところまで、遠いところだけど連れていくと、これも大変な話なわけですよね。あまりオブラートに包まないでちょっと言ってくれないとの意見を述べました。","respondent":"金子保育課長","answer":"まず、その辺を重点的に解消してきたのが現実でありますし、今もその需要があるからそういった対応をしているわけです。ですので、この荏原地区の、特に西側といいますか、この辺については私どもでニーズを調べながら対応させていただきたいというふうに考えております。","id":"exchange-017"},{"speaker":"三上委員","kind":"意見","question":"調べてって、今までだって調べてきているはずなんでしょう。あるんですが、やれませんというのか、全くありませんからやっていないんですというのか、どっちかでしかないでしょうとの意見を述べました。","respondent":"金子保育課長","answer":"現在希望が集中している部分について、近くで対応していこうという対処の仕方を、先ほど申し上げたとおりしてまいりました。今空白の部分での住所から見て、どのようなニーズがあるかというのは、今後調べてみたいというふうに考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"定員に対して１０５％、１０３％という形で入っていますけども、予約の入園というのがありますよね。最大で何％ぐらいまで入れると考えられているのか、昨年の最大では何％になっているのか、このことについてちょっと説明を求めました。","respondent":"金子保育課長","answer":"入園予約の件ですけれども、これは毎年前期と後期に分けておりまして、４０名前後の数を予定しています。ですので、特に０歳のところで４０名ほどこれから入園予約の分を予定してあけているという部分はあります。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちなみに昨年の最もたくさん入ったところで何％かというところをひとつ教えていただきたいのと、正規職員の職種別の人数を全体で教えていただきたいのと、派遣の職員というのが品川区でどういう状況になっているのかについても教えてほしいと求めました。","respondent":"金子保育課長","answer":"非常勤はトータルの数字はちょっと持ってきていませんが、大体３７０人から３８０人前後だというふうに記憶しております。今年度の４月の段階で、３２人、人材派遣の職員を導入している数字です。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、各職種別の定員というところでは教えていただいたんですが、この定員に対して現在の人数というのは全く同じでしょうか。栄養士、それから資格のない人、それぞれ何名なのかということがわかったら教えてほしいと求めました。","respondent":"金子保育課長","answer":"あるいは正規職員が３名、非常勤職員が２名とか、いろんなパターンでおります。しかも、これも４月の時期には応援体制を組んだりしておりますので、必ずしも年間を通して一定の数字ではないということも承知しています。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは今４月１日ということで、この定員に満たっていないという理由は、一体どういうことなのかということをひとつ。提供されさえすれば、どんな実態になっていようともいいんだというふうな姿勢ではどうかなと思うんですけど、そこら辺のところはどうか尋ねました。","respondent":"金子保育課長","answer":"例年保育士の採用は８月ごろに採用試験をしているわけですが、平成１５年度につきましては、１２月から１月にかけて職員の採用試験を行いました。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"看護師に対しても３名足りないわけですけれども、この後どんどん大変な状況になってくるんじゃないかなと思うんですね。そこら辺のところも含めてちょっと教えていただきたいのと、それからあと、把握している人数をぜひ教えてほしいと求めました。","respondent":"金子保育課長","answer":"正規職員を採用する方針は今看護師では、２園については保健業務委託ということで看護師を委託業者から保健業務を委託しているというものです。それからもう一園につきましては、非常勤の看護師を配置しているということで、保健業務について遺漏がないように対応しています。","id":"exchange-023"},{"speaker":"須藤委員","kind":"意見","question":"そこで、新しく始まってきたんですけれども、この方々にこの秋からの保育料の改正についての説明はどういうふうになさっていらっしゃるのか。","respondent":"金子保育課長","answer":"現在、４月１５日に保護者に向けて園の中で掲示をしようということで、掲示物の準備をしています。区民全体に対しても４月１５日に広報の特集号を配布して、保育料の改定、全区民に対して説明できるような広報紙を準備しています。","id":"exchange-024"},{"speaker":"須藤委員","kind":"意見","question":"こういう保護者の方にご連絡していかないと、後ろ手に回っていっちゃうと、また話がいろいろややこしくなる。それには「２７％値上げを」なんていう話になってきているので、委員会でもお話しさせていただきましたけれども、改めてお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"待機児の問題を１点お伺いしたいんですが、一体これからどうしたらいいのかというご質問も受けているんですが、１点教えていただきたいんですが。","respondent":"金子保育課長","answer":"入園できなかった方に対するご説明ということですが、まず認証保育所Ａ型、認証保育所も区内でかなり数が増えてきております。ケースによりましては、ファミリーサポートセンターの利用等々も考えられますので、いろいろな方のご事情に応じてご説明を申し上げているところです。","id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今後どうなっていくのかなというところが大変心配されているんですけれども、保育の行政のところをどう考えて行動を立てていらっしゃるのかなというのが一つ、中・長期的なところの見通しというのをぜひお聞かせいただきたいんですが。","respondent":"金子保育課長","answer":"企画部が中心になってつくっていくというところで、長期的にはそこの部分で検討してまいりたいというふうに考えているところです。今年度中では６月にぷりすくーる西五反田、定数増も含めて改修工事をしてまいりますので、今後も引き続き努めていく考えでおります。","id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問","question":"認証保育園のところは、今後これからも区内で増えていく状況にあるのか、あと、分園方式なんかもとっていくような方向なんでしょうか。ぷりすくーる西五反田が開設しますけれども、幼保一元化の手法なんかもこれから積極的に取り入れていくのかどうか、その点も含めてお伺いします。","respondent":"金子保育課長","answer":"認証保育所の件ですが、今後確実に予定されているのは今１件です。これも今後いろいろな方式の中のそれぞれ一つだと思いますので、それらのことを含めて待機児解消には努めていきたいというふうに考えております。","id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういった面で、行政としてチェックの部分というんですか、責任が持てるような状況で進めてほしいなと思っているんです。お答えをいただけたらと思います。","respondent":"金子保育課長","answer":"必要があれば指導していくという立場でありますが、この立ち入りをする際に、必ず区の同行を求めております。良好なサービスを提供していることを確認しつつ、東京都と連携して必要な指導はしていかなければならないだろうというふうに考えてあります。","id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"都と区の連携があるだろうなと思ったので、知り得た情報というか、ぜひ知らせていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"大西委員","kind":"意見","question":"参考にちょっとお尋ねしておきたいんですけど、０歳児から５歳児までの待機児童数、それと今後、先ほど課長のほうから話がありましたぷりすくーる西五反田等、また、改修によって解消される部分等でその増減を予測してのところをちょっとお聞かせ願いたいんですけどとの意見を述べました。","respondent":"金子保育課長","answer":"２歳が４６人、３歳から５歳、保育の待機児解消策として見ることはできるだろうと思っています。滝王子保育園と西品川保育園が年度内に改修をいたしますが、最終的には両方足して５０名程度の定員増は図れるというふうに考えているところです。","id":"exchange-031"},{"speaker":"大西委員","kind":"質問","question":"すみません。ちょっとお尋ねしたかったのは、年齢別に待機児童というのを把握はされていますか尋ねました。","respondent":"金子保育課長","answer":"失礼いたしました。待機児の年齢別ですけれども、０歳が２８人、１歳が３６人、２歳が８６人、３歳が２７人、４歳が６人、５歳が１人、計１８４人です。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません、先ほどのちょっと続きで確認させていただきたいんですけど、そこら辺のところはどういう考え方でいくのかをちょっと教えてください。この保健業務委託というのはどういうことなのか、どういうところにどうなっているのかについても教えてほしいと求めました。","respondent":"金子保育課長","answer":"この看護師につきましては、区としまして今後どうするかという方針は確定しているわけではございません。今後ですけれども、今後の入園者の数等々あるいはほかの保育園の状況等も含めて対応は考えていきたいというふうに思っております。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこれはしっかりと確保していただきたいということと、これに対しては今でもほんとうに保育士たちは大変な中で業務の拡大がどんどんされているという状況もありますので、中途採用も含めてしっかりとした体制をとっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"大沢委員","kind":"質問","question":"４９名の枠というもの、この４月１日現在ですか、これが行われた時点でなくすような工夫というのはされているんでしょうか。ここの３園があるということを判断するのは、申し渡しはしているんでしょうか、ちょっとお伺いしたい。","respondent":"金子保育課長","answer":"ですので、あまり遠いところの方については、事情によって説明する場合もありますけれども、しない場合が多いということ。現在のところはそういうふうに可能な方についてはこちらのほうに申し込まれると有利であるよというふうなご案内をしているのが現状です。","id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"今お伺いした東大井保育園ですか、通えなさそうだというのは、あくまでもこちらの提供する側の判断だと思うんですね。ですから、どうしても保育園に入れたいというご事情の方は、いかがなものか尋ねました。","respondent":"金子保育課長","answer":"これについてご説明しておりまして、八潮はほかのところよりも比較的有利であるということは皆さんにわかるようにご説明していますので、先ほど説明がちょっと足りなくて失礼いたしました。","id":"exchange-036"},{"speaker":"大西委員","kind":"質問","question":"先ほど待機児童数を年齢別に教えていただいたんですけど、ちょっと私の解釈でいいかどうかお尋ねしたいんですが、そうすると。今の３歳児よりも今の２歳児が７４名ほど少ないわけですから、大方８０％ほどは、これは解消されるというふうに単純に考えていいんか尋ねました。","respondent":"金子保育課長","answer":"今の大西委員のご質問ですが、新たに申し込まれてくる方もいるとは思いますが、単純に計算していくと、そういうふうにはなります。３歳未満全体の中でどの年齢の子を今入れるのがいいのか、あるいは３歳以上の中で、ストレートにいかない部分はあります。","id":"exchange-037"},{"speaker":"若林委員","kind":"質問・要望","question":"二つの読んでいただきたい方、ちょっとお知らせ、どういう方を目的にそれぞれつくられたか。どういう方にめくっていただいて、内容を吟味していただくというか、ちょっと説明を求めました。","respondent":"高橋介護保険担当課長","answer":"介護保険のページというところで、少しＱ＆Ａ等を載せてありますが、そんなに制度についてほど詳しくは載ってございません。それが大きな違いかと思いますので、よろしくご理解いただきたいと思います。","id":"exchange-038"},{"speaker":"若林委員","kind":"質問","question":"要支援の方とか要介護１の方とか、高齢者の方に説明をするということは、今まであったんでしょうか。こういうものはどうしても必要だったんか尋ねました。","respondent":"高橋介護保険担当課長","answer":"先ほど最初にご説明しましたけれども、それからブルーのパンフレット、それによってサービスについては説明できた部分かなと思います。よろしいでございましょうか。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１万冊ということですけど、これは区民がいただきたいということでお伺いしたら、どんどんいただけるという仕組みでいいのか。どういう業者があって、これをどのようにつくり変えていくという計画があるのかどうか、このことについて説明を求めました。","respondent":"高橋介護保険担当課長","answer":"その間、また見直す部分がございましたら、その部分はまた見直しし、手を入れて新しくしていければと考えているところです。新しい物をつくり変えていくということで、今年の秋ごろからまた進めて、来年１月ごろには２００５年版ができればいいと考えているところです。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほんとうにいいパンフレットをつくっていただいてありがとうあります。事業者の方々からとか、区民の方々からもさまざまな意見が出されましたら、ぜひ充実をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これから勉強させていただきたいなと思うんですが、以前のままがそのままなのか、ちょっとその点を説明するよう求めました。","respondent":"高橋介護保険担当課長","answer":"今委員お尋ねの今までのパンフレットについてですが、当面残してまいりたいと思います。その部分だけ聞きたいという方に、その部分についてはまたケアマネージャーが一人ひとりの利用者の立場に立って説明を加えるということも含めまして。","id":"exchange-042"},{"speaker":"塚本委員長","kind":"質問","question":"私のほうから伺います。関係を少し説明していただければ。","respondent":"高橋介護保険担当課長","answer":"１１ページをお開きいただきますと、「ハートページ２００４年品川区版は、品川区の協力のもと編集発行されました。ハートページがそういう会社であるということで、毎年品川区も出してまいりたいというところで無料配布ということで作成したところです。","id":"exchange-043"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２００５年度が見直しの時期に来ているので、国の状況とまた区の検討の状況を含めてご報告ほしいと求めましたが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"須藤委員","kind":"確認","question":"ちょっと確認だけど、委員長、もう一回委員会があるので、そこの対応という考え方で出されて……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"須藤委員","kind":"質問","question":"私立幼稚園も今度こっちでやるというようなお話を伺ってきているんで、児童の問題、子育ての基本政策。介護保険制度はほんとうに１回だけでは済まない問題で、児童の問題について、少し皆さんとでご議論してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"須藤委員","kind":"質問・要望","question":"僕らもどこそこにどうだよというのはわかるんだけど、それから６月ごろにスタートするとか、つかんでおいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一つ確認だけさせていただきたいんですけど、課長のほうからもそういうふうにお聞きしていたんですけど、そこのところだけ確認していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"須藤委員","kind":"意見","question":"支援費制度で、何か特段に大きな、今までご報告いただいている形だろうと思うので、その辺が変わったというのならあれだけど、さっきの介護保険と同じで、状況がこんなだよぐらいな形だろうと思うんだけどねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/256749?Template=document&Id=3074#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":35146,"voices":120}},{"id":"h16-20040412-9","meetingId":"h16-cm04","date":"2004年4月12日","dateIso":"2004-04-12","committee":"文教委員会","time":"午後１時０４分～午後４時１４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"議会運営委員会で開催の２日前に各委員に資料を渡して、この資料がなぜ当日になってしまったのか説明をいただきたいなと思ったんです。当然２日前というと土日がありますけれども、委員会審議の直接の中身ではないんですけれども、資料について説明していただきたいなと思います。","respondent":"市川庶務課長","answer":"冒頭本件の経過ということで説明申し上げましたけれども、去る４月９日に今回の報告事項のもととなる契約議案がそれぞれ議決をいただきました。そのような日程上の関係で、例外的に席上配付にさせていただいたと、このように受け止めていただければと思います。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"委員会審議ですから、４月２日に作成された資料だったり、委員会の２日前に提出する余地があったんじゃないのかなと思うんです。委員会審議を理事者のほうにお願いというんですか、委員長のお考えもお聞かせいただければなと思います。","respondent":"市川庶務課長","answer":"１番目の、ただいま説明するものにつきましては、その点のことをひとつご理解いただきたいと思います。もう１件のほうにつきましては、こういう事情で席上配付になったもので、特に他意はないということで受けとめていただきたいと思います。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"４月２日にできた資料だったりするもので、十分２日前というところを見て、先週の木曜日の時点で出せたと思うんです。文教委員長のご意見も聞きたいんですけれども、改めて２日前というのはルールとして守っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"堺委員長","kind":"質問・要望","question":"委員長としても先ほど申し上げましたように、なるべく資料等については申し合わせ確認事項にありますとおり、よろしくお願いしたいと思います。質疑はよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"私たちは文教委員会には少なくとも正直に数字を出してほしいという問題と、庶務課長は「それは新年度の予算ですから」というような形で。これは過去の問題ですから、これ以上は言いません。","respondent":"市川庶務課長","answer":"当然、今委員の言われたような、近隣に対する工事説明を踏まえた上で、具体的な工事の着手に入る。これが私どもも予定しています。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"工事着工予定と説明会の間に、当然タイムラグがあるわけですから、そこはなるべく早くやらなければ協定書の合意のないままの工事にならざるを得ない。大成建設とＪＶで組んで落札したんだから、もっと早い段階で話し合いはできる可能性があるんじゃないかと思うんですが、いかがか尋ねました。","respondent":"市川庶務課長","answer":"説明会の日程につきましては、極力早い時期での説明会の開催ということで日程調整をいたしました。要するに契約締結後、なるべく速やかな時期に実施をする、これは私ども基本的に考えております。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"今度の工期が２２カ月ですから、普通の中層マンションの倍の工事期間がかかるわけですね。非常に有形無形の迷惑を近隣に与えるわけですから、そういう努力を、ぜひお願いをしたいということだけ要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"例えば校庭に置こうとなると、仮校舎の関係で小さくなってしまう校庭ですから、適切じゃないのかなと思うんです。作業時間というのは、この説明会で行われるとは思いますけれども、今の段階で説明できる範囲がありましたら伺いたいなと思います。","respondent":"市川庶務課長","answer":"詳細については承知していません。町会の説明会に、ご意見をいただいた点、改めて確認をさせていただきたいと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"着工は着工で決まっていて、どうしてもトラブルの原因になりますので、基本的な住民との信頼関係を築く上での区の姿勢をもう一度教えていただきたい。荏原第五中学校の生徒や学校関係者に伺いますと、何とか体育のスペースですか、２点質問したいと思います。","respondent":"市川庶務課長","answer":"先ほど沢田委員のご質問にお答えしたとおりですので、そういうことで受けとめていただければと思います。それから、プールですけれども、文教大学附属中学校・高等学校のプールを借用するということで話を進めてあります。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"業者によっては、かなり騒音を抑えられてできるところもあるということを聞いているんですが、今回の業者はその辺の確認をどうされているのか。それがうまく組み入れられるような状況になっているのかどうか、そこの調整が難しいところにあるのかどうか、確認をしておきたいと思います。","respondent":"市川庶務課長","answer":"その辺は十分に吟味をするでしょうし、またそれに基づいて私どもに相談があれば、それで対応をさせていただきたいと思ってあります。私どもが介在したほうがいい結果が出るというものについては、積極的に連携を図っていく、そういう姿勢です。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"安全性、騒音については、関係者の方たちと話をしていただいて、できるだけ教育現場に支障のないように、ぜひ工夫をしていただきたいと思っています。やはり定期的にどういう状況かというふうに確認をしていただいて、問題解決が速やかになると思われるときもあるでしょうから、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、そういうような都会の特殊性というのか、そういうものも十二分に説明会で説明してほしいと求めました。ですから、確認したいのが、都心の限られたスペースの中で、それからどんなに頑張っても工事すると騒音は出るんです。","respondent":"市川庶務課長","answer":"これまでの私どものかつての説明会でも、この辺の姿勢は特にぐらついてきたということではなく、一貫したものを持って対応してきたと思ってあります。ここのバランスを取って、特に近隣の方に説明をしてきているつもりですし、堅持してまいりたいというふうに思ってあります。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それは当然ですよね、都会生活の中では。いい関係、十分その背後関係を含めた上でのご理解で説明していただきたいということを改めてお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そうなってくるのであれば、日付ぐらいは入れるべきなんだろうと考えていますが、その辺を抜いてあるというのはわかりづらい。なぜ日付を入れなかったのかと、引渡しという意味、まずこの辺のところの説明をいただきたい。","respondent":"市川庶務課長","answer":"２点目から先に答えしますけれども、おっしゃるとおりかと思います。引渡しを受ければ、引渡しの当日からでも引っ越しはできるです。","id":"exchange-014"},{"speaker":"石田副委員長","kind":"質問","question":"どうしてそういう質問をしたかというと、シックハウスの問題があるので、ある一定期間置かなくてはならないだろうなと考えています。区民の目から見れば同じわけですから、そういう部分も丁寧に書くべきだと思うんだけれども、その辺の考えはどうされているんか尋ねました。","respondent":"古川教育次長","answer":"もちろん、今週あるいは２０日ですとか、これからそれぞれ説明会に入ってまいります。地域説明につきましては、可能な限り十分な説明を加えていきたいと、このように考えております。","id":"exchange-015"},{"speaker":"石田副委員長","kind":"質問・要望","question":"区民には、そういう形でしっかりお願いしたいと思います。１１日までやられたか、仮校舎もどうやって壊して、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"１点だけ、迷惑料の問題について、先ほど出すべき根拠がない支出はあり得ないという答弁、これは根拠がなければ出すのはおかしな話だし、しかも税金ですからつかみ金みたいなものは許されないというのは、それは一般論としてはわかりますけれども、出すべき根拠というのはどんな根拠なんか尋ねました。","respondent":"市川庶務課長","answer":"根拠としては今申し上げたものと、いずれにしても支出には予算に基づく支出ということになりますので、議会の議決に基づく予算によって執行する。そういう意味で、根拠ということが言えるかと思います。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"あそこは１１１億円の税金投入した建物で、町会を含めて４年半の運動をやって、社会的常識の範囲内で迷惑料が出されている。そこで聞きたいんですが、例えば裁判所の判決が出れば当然ですけれども、和解が成立した場合はどうなんか尋ねました。","respondent":"市川庶務課長","answer":"ご案内のとおり、和解というのは判決に準ずるものですから、そういうものとして粛々として講ぜられるものです。","id":"exchange-018"},{"speaker":"沢田委員","kind":"意見","question":"例えば、裁判所が間に入って和解が成立したら当然払うべきだし、そういうことも含めて住民の理解を得るために努力をすべきだと。ただ、迷惑料を出してほしいというレベルでの話には至っていないですけれども、最後はそういうことでもやらなければとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"不十分な内容で工事日程を、文教委員はこれで了承したというふうに取られると、あまりにも不十分な内容で、真意じゃないのかなと思うんです。","respondent":"古川教育次長","answer":"それぞれの説明会の中で、当然これに加えて詳細な内容のものを持ってまいりますが、これがぎりぎりです。こういうことで、ご説明申し上げます。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのが、そういう答弁の整合性というんでしょうか、書いてあることと答弁の整合性はどうなるということをお伺いしたいのが一つ。それから、例えば教職員証を今度つくられるはずですから、出入口を対応していくというような計画がおありでしょうかということをお伺いしておきます。","respondent":"古川教育次長、市川庶務課長","answer":"そのことを大きく変えるという観点からの大きな実施設計の変更はないように、この大きな方向は第一回定例会等々でご説明したとおり。したがいまして、これと全体の設計の完了、そして実施設計後の施工段階における一定の修正と… 説明してまいりました区全体の近隣セキュリティーシステムの学校施設の安全管理への適用ということも含めて、今、今後検討してまいります。その上で、アリーナあるいはプールへの動線がつくられている、そういうことを考えております。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"それから、動線のほうですが、それぞれわかったんですが、要は校庭に出入りするときに、正門から入れるんですかということをお伺いしたい。わざわざ正門を通って校舎の中を通ってだけしか行けないのかということをお伺いしたいんです。","respondent":"市川庶務課長、古川教育次長","answer":"校舎であろうと、校庭であろうと、出入口は１カ所というのが今回の考え方です。若干これから実施設計をやっていく中で、こういう若干の実施設計段階における変更、こちらの必要な範囲で変えていく部分は一定あるです。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その後のランニングコスト、確認したいのがオープンスペースの冷暖房のランニングコスト、何か対応を考えておりますかということが一つ。それは変わっていないんでしたら、セキュリティー対策をどう考えているかということ、それをお聞かせほしいと求めました。","respondent":"市川庶務課長","answer":"これは重ねての説明になるかと思うんですが、今の時点では、そういうふうに考えてあります。それから、地域開放となりますと、この辺については今後の実施設計を詰めていく段階で検討させていただきたいと思います。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"お伺いしたかったのが１月２０日の文教委員会で「ガレリヤ」という表現の中で、１階から３階まで吹き抜けのスペースでやっていくんですよ。ですから、そういう工夫をしてみたらいかがでしょうかということをお伺いしますので、改めて答弁をほしいと求めました。","respondent":"市川庶務課長","answer":"１月２０日にも前任の課長から、最終的にはこういう答え方をさせていただいたと思うんですが、その辺を改めて念頭に置いた上で実施設計に取り組んでまいりたいと考えています。","id":"exchange-024"},{"speaker":"山路委員","kind":"質問","question":"そのとおりにこの設計はなっているんですけれども、４ページの小中一貫校の職員室は２階ということで、第二延山小学校は事務室の横に置いてあります。全部すりガラスで見えないということはありませんか、その辺を教えてもらいたいと思います。","respondent":"古川教育次長","answer":"さまざまな角度から検討してございまして、できるだけハードの危機に耐える部分と、それから人的なソフト面からの体制づくりを考えてあります。今回施設の状況は若干異なりますが、趣旨といたしましてはそういう観点をとらえて、それぞれに生かしたつもりです。","id":"exchange-025"},{"speaker":"山路委員","kind":"質問","question":"監視といっても出入りする人のことですからあれですけれども、万が一の事故に備えて出入りをよく見張っていただく。そういう点は非常に組まれていると思うんですけれども、そういう計画、またここには取り入れるのか取り入れないのかお伺いしておきます。","respondent":"古川教育次長","answer":"今の警官、警察によるボックスというものは考えてございませんが、あるいは今回のセキュリティーに関する一つの研究も必要です。全体の中でのさまざまな可能性を探りながら、学校のより安全な環境づくりを進めてまいりたいと、このように考えてあります。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"配置図について若干理由を伺いたいんですけれども、大井地区小中一貫校も第二延山小学校も同様なんですが、その理由を教えてほしいと求めました。やっぱり校庭に近いほうが放しやすいというんですか、なぜ離れているのかという理由と、それも何か理由があればそれぞれ教えてほしいなと思います。","respondent":"富田教育改革担当課長","answer":"どういった配置が望ましいかという、そういった全体計画の中で、すまいるスクールの配置が決まってきたものというふうに解釈をしております。この中では、その他の学校との兼用スペースができるだけ広く取れるようにということで、こういった配置の場所になってきたです。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"僕が伺いたかったのは、配置図ですから、それぞれ一個一個の場所に各々理由があると思うんですね。僕の思いとしては、校庭が見えたほうがいいんじゃないのかなと思うんですけれども、離れている理由を教えてほしいんです。","respondent":"富田教育改革担当課長","answer":"例えばほかの教室ですとか体育館、そういったものさまざま活用して展開していく事業であります。あるいはランチルームですとか、体育館といったところとは、比較的活動の多いスペースと近接するような場所に配置をしているです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"この場所に配置するとなって、全体のいろんな配置によってすまいるスクールの職員配置もおのずと決まってくるのかなと思うんです。ここに何人、専任が何人で非常勤が何人という体制を検討しているのかなとか、もし検討していることがあれば説明を求めました。","respondent":"富田教育改革担当課長","answer":"今時点、で大井地区小中一貫校のすまいるスクールの配置人員というのは考えておりません。心身障害学級利用の児童の状況、さまざま勘案しながら大井地区小中一貫校開設に間に合う時期に検討してまいりたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"本題の質問をしたいんですけれども、この基本設計を文教委員会に説明されましたけれども、今後の大井地区における地元説明会の日程はいつなのでしょうか説明を求めました。","respondent":"市川庶務課長","answer":"大井地区小中一貫校について４月２７日、それから２８日第二延山小学校、それぞれ建設計画の説明会を予定しています。説明が漏れたこと、お詫び申し上げます。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"この説明会の周知方法および前回もチラシなどを配付したと地域の方から伺いましたけれども、一定のお考えがあって配付をしていると思うので、その説明をお願いします。","respondent":"市川庶務課長","answer":"大井地区小中一貫校につきましては、伊藤中学校、原小学校、大井第一小学校、山中小学校、それぞれ子どもたちを通じて保護者に説明会の周知を図る。第二延山小学校についても、基本的な周知の仕方については同様に考えてあります。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"大崎地区でいろいろ問題がありましたので、高さの２倍の範囲の地域の方にもチラシを配付したり説明することを、今説明したとおりお願いいたします。地域と学校の関係ですか、そこで学んでいく子どもたちにとっての成長につながるとお考えなのか、その考え方を少し説明してほしいと求めました。","respondent":"中島指導課長","answer":"従来のような昔からある学区域の子どもたちが、そのままそこの学校へ行くというような形とは異なっている状況があります。地域に説明すべき学校の情報、保護者に説明し、このように考えております。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"私、大井地区小中一貫校の周りのご近所の方に伺ってみました。区の姿勢を聞きたいんですけれども、説明会に参加できなかった方に関しては、どのような説明を行っていくつもりなのか教えてほしいと求めました。","respondent":"市川庶務課長、堺委員長","answer":"説明会というのは、この日にこういう内容で説明をしますということでご案内をするものですので、ここに来られなかった方を改めて説明対象にして何か代替するようなことを行うということは。 中塚委員、これで１人で８回目になるんですね。発言を制限するつもりはありませんけれども、１人で委員会をというわけではございませんので、ひとつよろしくご協力のほどをお願いいたします。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際に近隣の方に伺ったら、これは要望としますけれども、こういう姿勢は持っていただきたいなと思います。昨年の７月８日と９日の教育委員会は非公開のままですけれども、今後も議事録を公開するつもりはないのかどうか伺いたいのが質問です。","respondent":"古川教育次長","answer":"一定の時間的な経過があったとしても、内容によってはやはり公開できないあるいは公開することは適当でないといったこともあろうかと思ってあります。しかしながら、内容によっては非公開にとどまるものもあると、このように考えてあります。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"その要望が３ページの設計の中に入っているのかどうか。ですから、この辺の状況を踏まえた設計になっているか、まず３ページのほうからお願いしたいと思います。","respondent":"市川庶務課長","answer":"校庭の砂塵対策につきましては、委員ご指摘のとおり実施計画の段階で、これまで寄せられたさまざまなご意見なりを勘案した上で検討します。その辺、実施計画の段階で、どこまで全体の計画の回しの中で対応できるか、その辺少しお時間をいただければと思います。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"屋内のプールを貸したことで、近隣の方たちの要望が達成されているのかどうかというところの確認は必ずしていただきたいと思うんです。区の考えと、どういう対処が必要なのか、他に何か考えられないのかどうかということの確認をぜひしていただきたいなと思います。","respondent":"中島指導課長、谷田部学務課長、富田教育改革担当課長","answer":"これは小中一貫校の教育内容で、１年生から４年生までは学級担任制で実施していく。学校によって実施状況は多様という形ですけれども、柔道… 最後の中学校の心身障害学級ですけれども、中学校部分につきましては新設ということで計画しているものです。 ２階のすまいるスクールの並びにあります和室の活用についてですが、主に放課後、夜間また日曜日は地域開放ということも考えております。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"同時に、新たに影響するところは大体わかるわけですから、出向いていって説明をするということを行ってほしいなというふうに思うんですね。こういう説明ができている、少なくとも影響はどのぐらいかということはわかるわけですから、その辺のお考えを最後にお聞きしたいと思います。","respondent":"市川庶務課長","answer":"今ご説明いただいた件について、具体的に影響を受ける方への対応については、今後対応させていただきたいと思います。","id":"exchange-037"},{"speaker":"沢田委員","kind":"質問・要望","question":"今あった日照問題なんですが、最大で日影時間はどれぐらい奪うことになるのか、わかったら教えていただきたいということ。セキュリティー問題は近隣対策とは別として、どんな条件を提示したのか、その２点を教えていただけますか。","respondent":"市川庶務課長","answer":"１番目の質問、今手元に資料がございませんので、お答えは留保させていただきたいと思います。それと工期の短縮、そのようなことに加えて、周辺への日影等の影響を考慮した計画、こういったことを条件として提示しています。","id":"exchange-038"},{"speaker":"沢田委員","kind":"質問・要望","question":"だけど、同時にそのことが大崎地区では、確かに３教室確保したという努力は認めるけれども、いまだに引きずっているし、根本的に改善されていない。やっぱり、その問題はこっちにこれだけ努力したことを、少しでも向こうに返るように努力していただきたいということだけ述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"本間委員","kind":"質問","question":"その辺は細かいところはどうということではなくして、屋上緑化というのはどういう部分で配慮して、ちょっとわかりづらいというふうな感じがあります。それから、非常に努力されている姿はわかるんですが、屋上緑化に対してもう少しわかりやすい部分でのねらい等も含めて説明を求めました。","respondent":"市川庶務課長","answer":"今回の新しい学校施設の建設工事につきましては、でき得る限りそういった考え方を実現する。非常に抽象的な考え方ですけれども、今申し上げたような考え方を、こういったことで実施計画に結びつけていきたいというふうに考えております。","id":"exchange-040"},{"speaker":"石田副委員長","kind":"質問","question":"簡単に２点だけ。図書室の開放は、両方ともどのように考えて計画されているかお聞きします。","respondent":"古里品川図書館長","answer":"地域開放については、以前本会議でもご答弁させていただきましたが、できるだけ地域開放をしていきたいと思ってあります。学校教育の内容を含めて検討を進めてまいりたいということで、これから一緒に検討を開始するということにしています。","id":"exchange-041"},{"speaker":"石田副委員長","kind":"質問・要望","question":"例えば小中一貫校については１年生から４年生のメディアセンターの部分、校長室とか会議室のあたり、スパンは１５ｍ４０cmで同じなわけですよね。８×９ぐらいでお考えなのかなと思っていますが、プロポーザルの要件を含めてどのようにお考えかというのだけ聞かせていただきたい。","respondent":"古川教育次長","answer":"あるいはこれから実施設計に入っていく部分につきましても、これから実施設計の中で地域開放ゾーンをどのようにとらえていくか。小学校１年生から中学校３年生、いわゆる９年生までの身長の差はかなりありますので、温水かどうかは別にいたしまして。","id":"exchange-042"},{"speaker":"沢田委員","kind":"意見","question":"伊藤中学校も、１３２人から８４人に落ち込んでいるんですね。この辺は、区としてどのような原因というか、分析をしているのか、その考えを聞かせてほしいんですがとの意見を述べました。","respondent":"谷田部学務課長","answer":"それから、大井地区小中一貫校の計画説明の段階で、その説明会に参加された当時の小学校６年生を持つ保護者の方から。詳細には私どもつかんでございませんけれども、先ほどの要素があって、このような結果になったというふうには感じてあります。","id":"exchange-043"},{"speaker":"沢田委員","kind":"質問・要望","question":"こうした格好で出てくるというのは大変な問題ですから、なぜこうなったのかということを求めたいと思いますが、いかがでしょうか。それから区内の他の中学校にいった総数と、私立に行った総数というのは、今手元に資料があったら教えてほしいんですが。","respondent":"谷田部学務課長","answer":"しかしながら、大崎地区小中一貫校は、これまで小中一貫教育の必要性を十分認識した上での計画ですので。基本的には、従来から品川区の私立中学校に進学する率は２５％ぐらいという、今年もそのような傾向だろうというふうには思ってあります。","id":"exchange-044"},{"speaker":"沢田委員","kind":"質問","question":"１３８人が１００人近く減っちゃっているから、これは半端じゃない数なんですよね。多分荏原第一中学校に相当行っていると思うので、その数があったら教えてほしいと、その点もさっき聞いたんです。","respondent":"谷田部学務課長","answer":"これは出入りがありますので、ほかの学校に行ったりという関係がありますので、４６人が日野中学校に行ったということです。それから、数字を整理してございませんのでいい加減なことは言えませんけれども、傾向としては荏原第一中学校に行かれる方が多かったという状況です。","id":"exchange-045"},{"speaker":"沢田委員","kind":"質問","question":"日野中学校がこんなにドラスチックにあらわれた１年生の減少が何だったのか、そこがどこに行ったのかというのを、少し調査して分析する必要がある。やっぱり生かしていく必要があるんじゃないかなというふうに思うので、その点だけいかがか尋ねました。","respondent":"谷田部学務課長","answer":"特に中学校の場合は３年間を、例えば仮設で２年間、なかなかご理解されない部分があろうかと思います。私どもは委員ご指摘のように、その辺については十分私どもは区民の選択行動につきましては、傾向をつかんでいきたいというふうには思ってあります。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"確か、３クラスまでだったでしょうか、４クラスまでということで抽選になったわけですね。学校選択制ですから、この数値を見ると、今後そういうところを見ていく必要があるのかないのかというところのお考えをお聞きしたいなと考えています。","respondent":"谷田部学務課長","answer":"これはまさしく情緒障害の関係で、特別支援教育で言えばＤタイプと言われるものです。今後も重要になってまいりますので、これは心身障害児教育担当の校長先生をはじめ、私どもも努力していきたいというふうに思ってあります。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"品川区はいろいろな制度をされているわけですから、子どもたちにとっていい教育をやっていただくように指導をお願いしたいと思います。それから日野中学校、原小学校を移転されるわけですから、その中での地域割というのは今後どうされていくのか。","respondent":"谷田部学務課長","answer":"小学校は１８校の中から選べるということで、希望が集中した場合には学区域外の子どもは抽選という意味では、学区域というものがあるのは事実です。かつてピークのときの子どもに比べて２分の１、３分の１近く減ってありますので、今のところ考えていないという状況です。","id":"exchange-048"},{"speaker":"西本委員","kind":"意見","question":"小中一貫校ということを全区的に展開するという中では、やはりそこの区分けもある程度はっきりしていったほうがいいんじゃないか。これから教育改革プラン２１をやるにあたって、これは意見として申し上げて終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから学校選択制の話が出て、学校選択制の中で子どもたちに混乱をもたらしているのかなというのが、私の率直な感想です。この間、改めて学校選択の目的ですか、子どもの成長にてらしてどうして必要な制度として導入したのか説明をしてほしいと求めました。","respondent":"谷田部学務課長","answer":"学校を変えるためには、校長以下教職員の意識改革を含めて当然あるわけです。それが、要は区民の期待に応える教育を区立の小中学校で展開しているんだというために、学校選択制度を導入したというのがきっかけです。","id":"exchange-050"},{"speaker":"中塚委員","kind":"意見","question":"おそらく今後も続けていくお考えだと思うので、今の子どもの現状に対してこの制度が本当に必要なんだという説明をほしいと求めました。教員のキャパとかいろいろありますけれども、子どもの成長にてらしているという説明をしてほしいと求めました。","respondent":"谷田部学務課長","answer":"自分の子どもにとって一番ふさわしい教育を受けさせたいというのが、保護者の皆さん方の気持ちです。それぞれ小学校４０校、中学校１８校、結果的には子どものための教育がそこでなされるです。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"板橋区では２人になったと、北区の３区は、やっぱり子どもの成長にふさわしくないのじゃないかという話が出ているので質問をしているんですね。世田谷区の区長は導入しないと明言していますけれども、教育長のお考えを求めて、最後にご意見を聞かせてほしいと求めました。","respondent":"谷田部学務課長","answer":"それから、学校選択制を取らない区は、それは各区の自治体のそれぞれの考え方ですので、私どもが論及する立場ではございません。昨年１２月に実施いたしました『「教育プラン２１」保護者対象アンケート』は、なぜこういう数字があるのに、私ども理解できないところです。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"確認","question":"確認しますけれども、普通にとらえていけばもう一度原点に立ち返ってやっていきたいという思いでやらせてほしいということですね。その部分でやられたんでしょうから、頑張ってくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"沢田委員","kind":"質問","question":"管理職の異動についてはわかったんですが、教員全体の状況というのがわかったら教えてほしいんですが。前にも問題になりまして、退職と区内から転出と転入と新任がどうなのか、ちょっと動態を教えてほしいと求めました。","respondent":"中島指導課長","answer":"転入、退職、またそれに伴う新規教員の採用というような状況が起こっております。具体的な数字が固まっておりませんので、また固まりましてから情報提供するということで、よろしゅうございましょうか。","id":"exchange-054"},{"speaker":"沢田委員","kind":"質問","question":"１点だけなんですが、過日の本会議の代表質問で、３０人増えたら１人非常勤をつけるという答弁があったんですが、具体的に今度の中で増えた部分というのはあるんか尋ねました。","respondent":"富田教育改革担当課長","answer":"３０人増えるごとに１人増やしていきたいというふうに申し上げておりますが、ある程度の参加予測を立てた上で非常勤職員の配置をしてきております。実際に現在のところ４月６日、７日の入学式を明けての参加状況を見てみますと、ほほ予測の範囲内です。","id":"exchange-055"},{"speaker":"沢田委員","kind":"質問","question":"学童保育クラブからの移行を見込んで、標準的なものに既にプラスアルファしているから、新たに全部は出てこないという意味ですよね、今の答弁は。かなりの部分で増やしたというのであれば、何人増えたのかというのがわかれば教えてほしいんですが。","respondent":"富田教育改革担当課長","answer":"ちょっと説明が詳しくなりますと難しいことになるんですけれども、例えば１人当たりの週あたりの勤務日数等々を計算してまいりませんと、実際１日当たりというところが出てまいりませんので。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"４月に非常勤職員を増やしたと伺ったんですけれども、４月から採用されなかった方の話をこの前させていただきました。僕の認識では、２０代のＢ勤が４月以降アルバイトで働いていると伺ったんですけれども、どういうことになっているのか説明を伺いたいと思います。","respondent":"富田教育改革担当課長","answer":"冬休みと三期休業等がありますので、すまいるスクールを朝から利用するということになってまいりますので、臨時職員の任用を若干しております。したがいまして、３月末で一たん非常勤職員を任期満了となった者についても、一部春休みのみということでの任用を行った者もいるです。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"臨時職員の数がわかったら教えていただきたいのと、そのうち何人が４月以降勤務をされているのか、数字があったら教えていただきたい。同じ子どもたちと言ったほうが正しいんでしょうか、同じ職場で働く非常勤が何人いるのか、もし数字がわかりましたら説明していただきたい。","respondent":"富田教育改革担当課長","answer":"この臨時職員には３月末で非常勤が終わった者もおりますし、あるいは学生の方々等も入っているということで、それぞれさまざまな状況の中で臨時職員をお願いしているです。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"１点目の質問の答えがなかったので、もう１回質問いたしますけれども、３月まで働いていた非常勤のうち、何人の方が４月以降も継続して働いているのか、何人中何人ぐらい。","respondent":"富田教育改革担当課長","answer":"ただいまのご質問の数字については、ただいま資料を持ち合わせておりませんので、控えします。","id":"exchange-059"},{"speaker":"沢田委員","kind":"質問","question":"道路を挟んだ向こう側で縄文時代の住居跡が出てきたということで、土地はつながっていると見て、調査期間として１カ月止めるということなんか尋ねました。","respondent":"上川内生涯学習課長","answer":"本当に道路を挟んだ向こう側だったので、こちらのほうでも区の公園ということもありまして、試掘調査を行ったということです。試掘をしたら出てきたということです。","id":"exchange-060"},{"speaker":"沢田委員","kind":"意見","question":"そういった場合、どこまで広がる。一定道路で区切られて、対岸で出てきたからやるということなのか、その辺の基準がわからないんですがとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"隣地は今ではなくて、その周辺に史跡とか遺跡とかがかつて出たとか、そういうところについては試掘をすることになっております。そこに隣接している「ねむの木の庭」というのは隣接しておりますので、試掘してみたところ部分的なんですが出てきたということです。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/544596?Template=document&Id=4500#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":52153,"voices":150}},{"id":"h16-20040412-5","meetingId":"h16-cm04","date":"2004年4月12日","dateIso":"2004-04-12","committee":"総務委員会","time":"午後１時０４分～午後２時３９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"総合実施計画（第３次）策定","agenda":"総合実施計画（第３次）策定","exchanges":[{"speaker":"武内委員","kind":"質問","question":"これは来年度もまた平成１７年度から平成１９年度という形で毎年出るんでしょうか。それとも、何か変更が多いときに出されるのか、その辺をお聞きいたします。","respondent":"榎本行財政改革担当課長","answer":"総合実施計画の改定の時期ですけれども、平成１３年度から平成１５年度が第１次の実施計画を策定したです。その後１年おきまして、第２次が平成１５年度から平成１７年度ということで入っておりますけれども、毎年改定する予定で進めていく考えです。","id":"exchange-001"},{"speaker":"本田委員","kind":"質問・要望","question":"第２次と、どこがどういうふうに、ちょっと分かりにくい。２次、３次とやって、もう一度ご見解をお聞かせほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"実施計画というような形の考え方もありますけれども、１回つくったら実施計画を３年目に説明するとすると、常に最新の状態の実施計画で。","id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"その継続性がどういうふうにあるのか、少なくとも今の社会の中で１０年で一つ入れたものがいくなどということはあり得ない。少なくとも３年ぐらいというふうな感じもするぐらいですから、３年間の見通しを立てて、その辺のところをご意見を申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"土井委員","kind":"意見","question":"そこら辺がなぜ変わったのかというときには、こういうふうに思ったんだよ、こういう行きがかりが分かれば非常にありがたいということだと思います。特段何かありましたら、事務事業評価に係わる問題等も含めてとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"冊子等でそれぞれ公表はしている形ですけれども、ここの中にどういうふうに取り込むのかというところはまだ工夫を図っていきたいと考えています。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この中を見ても、どういうふうにやっていこうかというのがよくわからないのが何点かあるんですけれども、そこのところもお聞かせいただきたいんです。例えば障害者（児）福祉のところの３次評価の実施というふうになっておりますけれども、どういうふうなイメージでやろうとしているのか。","respondent":"鈴木（真）委員長、榎本行財政改革担当課長","answer":"あまり中身に入ってきますと、ほかの委員会との兼ね合いもありますので、総務委員会として答えられる範囲で、概略ということでお願いをしたいと思います。 ３年次の教員研修の実施が平成１６年度、１８年度、平成１６年度からあります。平成１７年度からは、さらに転入教員研修の充実ということを計画しております。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"教員の資質向上ということですけれども、私が聞きたかったのは、答えられる範囲でいいんですけれども、最終的には企画のほうでそれをまとめているわけですから、教員の問題意識ではどういうふうな研修ということなのかなということなんです。","respondent":"榎本行財政改革担当課長","answer":"プラン２１の展開もなかなかできないということで、教員のほうにつきましても研修をして、さらに充実を図っていきたいというふうに考えております。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の説明で、プラン２１との関係で、ある意味では品川区独自の研修ということになっていくということですね。どういうふうな問題意識で、どの辺まで説明できるかどうかわからないですけれども、分かるところまでお聞かせほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"次世代育成支援対策行動計画につきましては、企画財政課が所管となっておりまして、全庁の取りまとめをしていくことで予定しております。夏に向けての審議会等の設置をして、審議会のほうのやり方等も、新規の事業会議に図る予定で準備を進めておるところです。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう１点だけ、お聞きしたいんですけれども、住民の意見がどのくらいちゃんと反映するかというのが鍵だと思っています。例えば議会の前、後で住民の意見を聞くとか、それぞれ工夫をしていただきたいということを注文しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"意見","question":"日本の全体の流れは流れでつかみながら、区として大きい項目の一つが少子化対策、あるいは健全育成というのがまるっきり触れられていない。品川区の人口動態については、これをつくる上でどういうふうにつかまえているのかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"実際には長期基本計画のときに大まかな今後１０年間の人口動態等を示してございまして、そのあと、若干人口等は増えてきている状況もあります。小中学校の展開ですとか、この施策、各事業等の事業量を見ているという形です。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"行政を司る上で、そこが基本じゃないですか。どういう分析をされているんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"なかなか難しいところですけれども、それに対応できるだけのものについては、人口についてもそれぞれつかんでいきたいと思います。それと、乳幼児は数としては増えておりますけれども、出生率自体の統計でいくと減ってきているというようなデータになってあります。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"意見","question":"平成１７年、平成１８年の向こう３年間の数字が出てきているんだけれども、歳入のその他の額が平成１６年度に比べると百三十何億円減っている。投資的経費が減るのは、右の水色の表の中の６番が半分近くになっているということですが、この辺をちょっと説明を求めました。","respondent":"市岡企画財政課長","answer":"投資的事業の国庫等を除いた区の財源負担のうち、基金繰り入れで対応をしていた分が減ってくる。例えば財調などは１％ずつ増やしておりますし、税も堅調だということになっていますから、事業量見合いで財源構成が変わっているです。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"一応ベースになるところは、今のお話ということ。予算が永久に右肩上がりで上がっていくのがどういうものなのかという議論をしたことがあるんだけれども、特に執行部は受け入れるんか尋ねました。","respondent":"市岡企画財政課長","answer":"平成１８年度が下がっていますが、中期的スパンぐらいで見ていただくと、そんなに投資的事業が落ちてはこないと思います。これは端境期が平成１８年度になります。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"意見","question":"だから、これから予算というのはどういう、かくあるべきだという議論も数字的にはしていかなければいけないだろうと僕は思う。それぞれの部署の事業部に聞くと、手を握り合ってやっていますと言うかもわからないとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"例えば放置自転車ですとか、まちを見ている施策ですので、その辺の融合等の部分は考えていかなければいけない。その中で、無駄なく展開できるような形での事業の展開というのは図っていかなければいけないというふうに感じております。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"受ける側がそう受け止めているかどうかということも含めて、議会はまだ来年度になっていないけれども、今年新しい行政をつくっていってほしい。答えは年度末に聞きます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"築舘委員","kind":"質問","question":"３カ年を出しているわけですから、平成１８年度事業はどういう重点事業だというのを、もちろん計算されて出してきているというふうに思うんです。そのことと、それから環境ということをどういう形で締めくくって、今度は安心・安全なまちづくりになったのかということの経緯を説明するよう求めました。","respondent":"榎本行財政改革担当課長","answer":"それから、環境から安心・安全というところですけれども、環境につきましては、環境計画をつくって、方針を大きく打ち出したということ。","id":"exchange-015"},{"speaker":"築舘委員","kind":"質問・要望","question":"この計画の場合７つの品川プランという、これが総合的なものですから、それが自分たちの中心になっては困るわけですね。ですから、横串ですから、どうしても逆らう部分があるわけです。","respondent":"榎本行財政改革担当課長","answer":"これから平成１６年度の重点施策の事業部経営会議の検討というのも始まりますけれども。それに従ったこの計画等を進めてまいりますけれども、このプランの重点に添った形での事業にいくような形での工夫を図っているところです。","id":"exchange-016"},{"speaker":"築舘委員","kind":"質問","question":"お互いに各事業部から１人ずつ出てきて、政策ごとの予算はもちろんつくんですけれども、人材もそこに統合されてきてもおかしくはないんじゃないか。そういうことを柔軟にやってみる部署があってもいいんじゃないかという考え方ですけれども、この点はどうなんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"中心になるのはやはり企画部が中心になってやるべきだと考えていますし、それについては次世代育成行動計画の中でも検討をしていきますし、そういう場合については臨機応変にプロジェクト等の設置も考えております。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"どこでもいいんだけれども、一番左の上の企画財政課の新のところに、企画担当（主査）制という、制度の制という字が入ったのと、担当だけのところ、この「制」という意味を説明するよう求めました。","respondent":"榎本行財政改革担当課長","answer":"何々主査というのは、単独組織ということで、１人だけ係長を配置するという形です。主査制につきましては、係長２人の場合、事業量、必要度によって、１人の場合もありますけれども、２人の場合もあるです。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"分かりました。あるいは高齢者との接点、ここに置いたボランティア担当主査というのは、どういう仕事をしていく係長なんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"区民に対しては、どんなボランティアのメニューがあるのかというものを示していくような形での仕組みづくりをしていくという形で考えております。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、ボランティアという定義を品川区として付けるんですか。窓口として機能するには、品川区の全部のボランティアを把握していないと機能が発揮できなくなるけれども、そこまでやってもらうつもりか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"そこまでやる予定でございまして、どのレベルかというところがありますけれども、行政から応募をかけて区民の方を募集して、ボランティアをやっている事業については、きちんとつかんだ上で、情報等の共有等を図りたいというふうに考えております。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、課長の下に何人かの調査員とか、ボランティア担当係長１人でやるんですか。この組織を説明するよう求めました。","respondent":"榎本行財政改革担当課長","answer":"それぞれ分担をしていくということで、単独では事業というのはなかなかできませんので、チームを組んだ形での事業を展開していくという形で考えております。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"今の企画部企画財政課でそんな人がいるんですか。企画のところにそういうことをやる人がいるわけか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"そういった経験も使いながら、行く行くはまちへ出て情報もつかんでいくというところもありますし、ボランティアセンターからも情報をつかめるというふうに考えております。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"なぜ企画に置かなければいけないのか。なぜここの企画財政課にボランティア担当主査が必要なんか尋ねました。","respondent":"中尾根企画部長","answer":"全体の合意の中で進めていくのか、ここに到達しているボランティア担当は、実はそのことを試みとしてねらっている組織であります。これは新しい試みですので、一生懸命頑張っていきたいと思いますけれども、ぜひ側面のご協力をよろしくお願いしたいと思います。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"人事課長も相当考えていらっしゃるみたいですから、成功するために、ぜひ何らか考えていただきたい。期待しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"築舘委員","kind":"意見","question":"先ほど言ったように、二葉すこやか園の幼保一元化のほうは、変わっていなければ区立幼稚園の絡みがあるから教育委員会でやっていると思うんです。","respondent":"榎本行財政改革担当課長","answer":"これにつきましては、法律の壁もありますけれども、その壁を破るべくいろいろな試みもしています。幼保一元施設、それを見据えつつ、組織についてもまだまだこれから検討をしていきたいというふうに考えております。","id":"exchange-025"},{"speaker":"築舘委員","kind":"質問・要望","question":"その点では、今後しかるべきところである程度しっかりとやっていただきたいというのが希望です。総務課が捨てちゃったので、ちょっと残念です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"まだ開いていないのに増やした理由を説明するよう求めました。","respondent":"榎本行財政改革担当課長","answer":"予定ということで発表をさせていただきまして、第１回目は６月の上旬を予定して、これから日程調整等に入りたいと考えています。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"分野とか、選考にあたっての何か基準というのか、お考えはあるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"行政司法の分野という形で、それぞれ入っているということで、多方面からいろいろご意見がいただけるということで選考をしたところです。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"人数的には１０名がリミットとしてあるんですか。それとも、これからのそれにふさわしい方がいらっしゃったら入ってもらうということか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"今のところこれで決定ということで、任期２年という形で決定いたしましたので、１０名ということで考えております。ただ、補欠というか、途中で任期を代わられる方が出れば、また別といたします。","id":"exchange-029"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、例えばインターネットとか、会議が終わって２週間後か、１カ月後ぐらいに。かなり今後の区政の行方を動かすのかななどという不安もありますので、そういうことを伺うんですけれども、いかがか尋ねました。","respondent":"榎本行財政改革担当課長、鷹倉経理課長","answer":"会議のどんな点が話し合われたか、どういう話題があったかということについては、インターネット等が一番早く提供できますので、インターネットも活用しますし、議題に応じて、ほかの手段でも報告をしていきたいというふうに考えます。 ２点目は、８日の総務委員会で、法的根拠はどのようになっているのかというお尋ねがございました。私ども２月の段階でございましたけれども、１件決定をとらしていただきまして、このような経過です。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/406359?Template=document&Id=1648#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":29644,"voices":82}}]);
